```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';

export const options = {
  scenarios: {
    shop_flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';

const FORM_RE = /<form\b(?:[^>"']|"[^"]*"|'[^']*')*>[\s\S]*?<\/form\s*>/gi;
const FORM_OPEN_RE = /^<form\b(?:[^>"']|"[^"]*"|'[^']*')*>/i;
const INPUT_RE = /<input\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi;

// ---------- utilities ----------

function expect(name, cond) {
  const v = cond === true;
  return check(v, { [name]: (c) => c === true });
}

function accountFor(vu) {
  return 'bench-' + (((vu - 1) % 16) + 1);
}

function abs(path) {
  const p = String(path);
  if (p.indexOf('//') === 0) throw new Error('off-target URL refused: ' + p);
  if (p.charAt(0) === '/') return BASE + p;
  if (p === BASE || p.indexOf(BASE + '/') === 0) return p;
  throw new Error('off-target URL refused: ' + p);
}

function pathOnly(x) {
  return x ? String(x).split(/[?#]/)[0] : null;
}

function json(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function header(res, name) {
  const want = name.toLowerCase();
  const h = res.headers || {};
  const keys = Object.keys(h);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return h[keys[i]];
  }
  return null;
}

function decodeEntities(s) {
  return String(s)
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&#x27;|&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function stripNoise(html) {
  return String(html)
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<(script|style|template|textarea)\b[\s\S]*?<\/\1\s*>/gi, '');
}

function attrsOf(tag) {
  const body = String(tag).replace(/^<[a-zA-Z][^\s\/>]*/, '').replace(/\/?>$/, '');
  const out = {};
  const re = /([^\s"'<>\/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let m;
  while ((m = re.exec(body)) !== null) {
    const name = m[1].toLowerCase();
    if (Object.prototype.hasOwnProperty.call(out, name)) continue;
    const raw = m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] !== undefined ? m[4] : ''));
    out[name] = decodeEntities(raw);
  }
  return out;
}

function normalizeAction(raw) {
  if (raw === undefined || raw === null) return null;
  let s = decodeEntities(raw).trim();
  if (s.indexOf(BASE) === 0) {
    s = s.slice(BASE.length);
  } else if (/^[a-z][a-z0-9+.-]*:/i.test(s) || s.indexOf('//') === 0) {
    return null;
  }
  return s.charAt(0) === '/' ? s : null;
}

// Selects the hidden csrf input that lives inside the form posting to /v2/login.
function selectLoginToken(html) {
  const forms = stripNoise(html).match(FORM_RE) || [];
  for (const form of forms) {
    const open = (form.match(FORM_OPEN_RE) || [''])[0];
    const action = pathOnly(normalizeAction(attrsOf(open).action));
    if (action !== '/v2/login') continue;
    const inputs = form.match(INPUT_RE) || [];
    for (const tag of inputs) {
      const a = attrsOf(tag);
      const type = (a.type || '').trim().toLowerCase();
      if (a.name === 'csrf' && type === 'hidden' && !('disabled' in a) && a.value) {
        return a.value;
      }
    }
  }
  return null;
}

// Selects the challenge form action (/v2/challenges/{id}) and its input[name=challenge].
function selectChallenge(html) {
  const forms = stripNoise(html).match(FORM_RE) || [];
  for (const form of forms) {
    const open = (form.match(FORM_OPEN_RE) || [''])[0];
    const action = normalizeAction(attrsOf(open).action);
    if (!action || !/^\/v2\/challenges\/[^/?#]+$/.test(pathOnly(action))) continue;
    const inputs = form.match(INPUT_RE) || [];
    for (const tag of inputs) {
      const a = attrsOf(tag);
      if (a.name === 'challenge' && a.value && !('disabled' in a)) {
        return { action: action, challenge: a.value };
      }
    }
  }
  return null;
}

// ---------- session & transport ----------

function newSession(username) {
  return {
    username: username,
    jar: new http.CookieJar(),
    csrf: null,
    user: null,
    cartId: null,
    etag: null,
    idem: null,
  };
}

function absorbCsrf(s, res) {
  if (res.status < 200 || res.status >= 300) return;
  const j = json(res);
  if (j && typeof j.csrf === 'string' && j.csrf.length > 0) s.csrf = j.csrf;
}

function send(s, method, url, body, opts) {
  const o = opts || {};
  const headers = { Accept: 'application/json' };
  if (method !== 'GET' && !o.anon && s.csrf) headers['X-CSRF-Token'] = s.csrf;
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  if (o.headers) {
    Object.keys(o.headers).forEach((k) => {
      if (o.headers[k] !== null && o.headers[k] !== undefined) headers[k] = o.headers[k];
    });
  }
  const target = abs(url);
  const params = {
    headers: headers,
    redirects: 0,
    jar: s.jar,
    tags: { name: method + ' ' + pathOnly(target.slice(BASE.length)) },
  };
  const payload = body === undefined ? null : JSON.stringify(body);
  const res = method === 'GET'
    ? http.get(target, params)
    : http.request(method, target, payload, params);
  absorbCsrf(s, res);
  return res;
}

// ---------- error classification & bounded recovery ----------

function authKind(res) {
  if (res.status !== 401) return null;
  const j = json(res);
  const e = j && j.error;
  if (e === 'expired') return 'expired';
  if (e === 'session') return 'session';
  return 'denied';
}

// Runs an operation; on 401 expired/session performs recovery and retries the
// interrupted operation exactly once. Denied (or any other 401) is not retried.
function runOp(s, label, attempt) {
  let out = attempt();
  const kind = authKind(out.res);
  if (kind === null) return out;
  if (kind === 'denied') {
    return Object.assign({}, out, { ok: false, reason: 'denied:' + label });
  }
  if (!recover(s, kind)) {
    return Object.assign({}, out, { ok: false, reason: 'recovery_failed:' + label });
  }
  out = attempt();
  if (authKind(out.res) !== null) {
    return Object.assign({}, out, { ok: false, reason: 'auth_after_recovery:' + label });
  }
  return out;
}

function renew(s) {
  const r = send(s, 'POST', '/v2/session/renew', {});
  const j = json(r);
  if (r.status < 200 || r.status >= 300 || !j || typeof j.csrf !== 'string' || !j.csrf) return false;
  s.csrf = j.csrf;
  return true;
}

function recover(s, kind) {
  if (kind === 'expired') {
    if (!renew(s)) return false;
  } else {
    // session revoked: renew may fail, then obtain a fresh form/login
    if (!renew(s)) {
      if (!login(s, s.username).loginOk) return false;
    }
  }
  if (s.cartId) {
    const r = send(s, 'POST', '/v2/carts/' + s.cartId + '/recover', {});
    if (r.status < 200 || r.status >= 300) return false;
  }
  return true;
}

// ---------- login ----------

function login(s, username) {
  const r = { formOk: false, tokenOk: false, loginOk: false };

  const form = send(s, 'GET', '/v2/login-form', undefined, { anon: true });
  r.formOk = form.status === 200;
  if (!r.formOk) return r;

  const token = selectLoginToken(form.body);
  r.tokenOk = token !== null;
  if (!r.tokenOk) return r;

  let res = send(s, 'POST', '/v2/login', { username: username, password: PASSWORD, csrf: token }, { anon: true });
  if (res.status === 302 || res.status === 303) {
    const loc = header(res, 'location');
    if (!loc) return r;
    res = send(s, 'GET', loc, undefined, { anon: true }); // dynamic Location, exactly once
  }
  const j = json(res);
  r.loginOk = res.status >= 200 && res.status < 300 && !!j && typeof j.csrf === 'string' && j.csrf.length > 0;
  if (r.loginOk) {
    s.csrf = j.csrf;
    s.user = j.user || username;
  }
  return r;
}

// ---------- catalog ----------

function pickInStock(products) {
  if (!Array.isArray(products)) return null;
  for (const p of products) {
    if (!p || p.id === undefined || p.id === null || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.id !== undefined && v.id !== null && v.in_stock === true) {
        return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  return null;
}

function getJson(s, path) {
  const res = send(s, 'GET', path);
  const data = json(res);
  return { res: res, data: data, ok: res.status === 200 && data !== null };
}

function findVariant(s) {
  let out = runOp(s, 'catalog', () => getJson(s, '/v2/catalog'));
  if (!out.ok) return null;
  let pick = pickInStock(out.data && out.data.data && out.data.data.products);
  if (pick) return pick;

  // Paged traversal: at most 3 pages, following server-provided next links only.
  let next = '/v2/catalog/page';
  for (let page = 0; page < 3 && next; page++) {
    const target = next;
    out = runOp(s, 'catalog_page', () => getJson(s, target));
    if (!out.ok) return null;
    const d = out.data;
    let products = [];
    if (d.product) products = [d.product];
    else if (d.data && d.data.product) products = [d.data.product];
    else if (d.data && Array.isArray(d.data.products)) products = d.data.products;
    pick = pickInStock(products);
    if (pick) return pick;
    next = typeof d.next === 'string' && d.next.length > 0 ? d.next : null;
  }
  return null;
}

// ---------- challenge / grant ----------

function attemptChallenge(s) {
  const form = send(s, 'GET', '/v2/challenge-form');
  if (form.status !== 200) return { res: form, data: null, ok: false };

  const ch = selectChallenge(form.body);
  if (!ch) return { res: form, data: null, ok: false };

  const post = send(s, 'POST', ch.action, { challenge: ch.challenge });
  if (post.status !== 302 && post.status !== 303) return { res: post, data: null, ok: false };
  const loc = header(post, 'location');
  if (!loc) return { res: post, data: null, ok: false };

  const grant = send(s, 'GET', loc); // dynamic Location, exactly once
  const j = json(grant);
  const ok = grant.status === 200 && !!j && j.grant_id !== undefined && j.grant_id !== null;
  return { res: grant, data: j, ok: ok };
}

// ---------- cart ----------

function attemptCartCreate(s, pick, grantId) {
  const res = send(s, 'POST', '/v2/carts', {
    product_id: pick.product_id,
    variant_id: pick.variant_id,
    grant_id: grantId,
  });
  const j = json(res);
  const ok = res.status === 201 && !!j && j.id !== undefined && j.id !== null;
  if (ok) {
    s.cartId = j.id;
    s.etag = header(res, 'etag') || null;
    s.idem = 'order-' + j.id + '-' + __VU + '-' + __ITER + '-' + Date.now() + '-' +
      Math.random().toString(36).slice(2);
  }
  return { res: res, data: j, ok: ok };
}

function refreshEtag(s) {
  const g = send(s, 'GET', '/v2/carts/' + s.cartId);
  if (g.status === 200) s.etag = header(g, 'etag') || null;
  return g;
}

function attemptPatch(s, quantity) {
  if (!s.etag) {
    const g = refreshEtag(s);
    if (g.status !== 200) return { res: g, ok: false };
  }
  const path = '/v2/carts/' + s.cartId;
  let res = send(s, 'PATCH', path, { quantity: quantity }, { headers: { 'If-Match': s.etag } });
  if (res.status === 412) {
    // re-read and retry the same payload exactly once
    const g = refreshEtag(s);
    if (g.status !== 200) return { res: g, ok: false };
    res = send(s, 'PATCH', path, { quantity: quantity }, { headers: { 'If-Match': s.etag } });
  }
  const ok = res.status >= 200 && res.status < 300;
  if (ok) {
    const et = header(res, 'etag');
    if (et) s.etag = et;
  }
  return { res: res, ok: ok };
}

// ---------- reservation ----------

function attemptReservation(s) {
  const res = send(s, 'POST', '/v2/reservations', { cart_id: s.cartId });
  const j = json(res);
  const ok = res.status === 202 && !!j && typeof j.status_url === 'string' && j.status_url.length > 0;
  return { res: res, data: j, ok: ok };
}

function attemptPoll(s, url) {
  const res = send(s, 'GET', url);
  const j = json(res);
  return { res: res, data: j, ok: (res.status === 200 || res.status === 202) && !!j };
}

// Polls at most 5 times, >=50ms apart. Only status=ready yields a reservation_id.
function awaitReadyReservation(s, statusUrl) {
  for (let i = 1; i <= 5; i++) {
    if (i > 1) sleep(0.06);
    const p = runOp(s, 'reservation_poll', () => attemptPoll(s, statusUrl));
    if (!p.ok) return null;
    const st = p.data.status;
    if (st === 'ready') {
      let rid = null;
      if (p.data.reservation_id !== undefined && p.data.reservation_id !== null) {
        rid = p.data.reservation_id;
      } else if (p.data.reservation && p.data.reservation.id !== undefined && p.data.reservation.id !== null) {
        rid = p.data.reservation.id;
      }
      return rid;
    }
    if (st === 'failed') return null;
  }
  return null;
}

// ---------- order ----------

function attemptOrder(s, reservationId) {
  const g = refreshEtag(s);
  if (g.status !== 200) return { res: g, data: null, ok: false };

  const body = { cart_id: s.cartId };
  if (reservationId !== null && reservationId !== undefined) body.reservation_id = reservationId;

  const headers = { 'Idempotency-Key': s.idem };
  if (s.etag) headers['If-Match'] = s.etag;

  const res = send(s, 'POST', '/v2/orders', body, { headers: headers });
  const j = json(res);
  const ok = res.status === 201 && !!j && j.accepted === true && j.id !== undefined && j.id !== null;
  return { res: res, data: j, ok: ok };
}

// ---------- safety: two independent sessions with fresh form tokens ----------

function safetyCheck(primary, username) {
  const secondary = newSession(username);
  const r = login(secondary, username);
  const primaryRes = send(primary, 'GET', '/v2/catalog');
  const secondaryRes = r.loginOk ? send(secondary, 'GET', '/v2/catalog') : null;
  const ok = r.formOk && r.tokenOk && r.loginOk &&
    primaryRes.status === 200 &&
    secondaryRes !== null && secondaryRes.status === 200;
  expect('safety: fresh form tokens authorize two independent sessions', ok);
}

// ---------- journey ----------

export default function () {
  const username = accountFor(__VU);
  const s = newSession(username);

  const lr = login(s, username);
  expect('loads: login form served with 200', lr.formOk);
  expect('setup: hidden csrf input selected from /v2/login form', lr.tokenOk);
  expect('setup: login accepted with selected token and csrf issued', lr.loginOk);
  if (!lr.loginOk) return;

  const pick = findVariant(s);
  if (!expect('behavior: in-stock variant found via catalog', pick !== null)) return;

  const ch = runOp(s, 'challenge', () => attemptChallenge(s));
  if (!expect('behavior: challenge grant issued', ch.ok)) return;

  const cart = runOp(s, 'cart_create', () => attemptCartCreate(s, pick, ch.data.grant_id));
  if (!expect('behavior: cart created exactly once with grant', cart.ok)) return;

  const pa = runOp(s, 'cart_patch', () => attemptPatch(s, 2));
  if (!expect('behavior: cart quantity patched with If-Match', pa.ok)) return;

  const rs = runOp(s, 'reservation', () => attemptReservation(s));
  if (!expect('behavior: reservation accepted with 202 status_url', rs.ok)) return;

  const rid = awaitReadyReservation(s, rs.data.status_url);
  if (!expect('behavior: reservation ready before checkout', rid !== null)) return;

  const od = runOp(s, 'order', () => attemptOrder(s, rid));
  if (!expect('behavior: order accepted (201, accepted:true)', od.ok)) return;

  safetyCheck(s, username);
}
