import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE = String(__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const PROFILE = parseProfile(__ENV.PROFILE);
const MAX_CATALOG_PAGES = 3;
const MAX_POLLS = 5;
const POLL_GAP_S = 0.06;
const MAX_SCHEDULED_RETRIES = 4;
const CART_QTY = 2;

const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '15m',
    },
  },
  thresholds: {
    checks: ['rate>0.99'],
  },
};

function parseProfile(raw) {
  if (!raw) return {};
  try {
    const p = JSON.parse(raw);
    return p && typeof p === 'object' ? p : {};
  } catch (e) {
    return {};
  }
}

function url(path) {
  const p = String(path);
  const u = /^https?:\/\//i.test(p) ? p : BASE + (p.charAt(0) === '/' ? p : '/' + p);
  if (u !== BASE && u.indexOf(BASE + '/') !== 0) {
    throw new Error('refusing non-target URL: ' + u);
  }
  return u;
}

function hdr(res, name) {
  const h = res.headers || {};
  const want = name.toLowerCase();
  const keys = Object.keys(h);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return h[keys[i]];
  }
  return null;
}

function json(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function errorOf(res) {
  const b = json(res);
  return b && typeof b.error === 'string' ? b.error : null;
}

function absorb(st, body) {
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    st.csrf = body.csrf;
  }
}

function assertOk(label, cond) {
  const pass = !!cond;
  check(null, { [label]: () => pass });
  return pass;
}

function send(st, method, path, body, headers, anon) {
  const h = {};
  if (headers) {
    const ks = Object.keys(headers);
    for (let i = 0; i < ks.length; i++) {
      if (headers[ks[i]] !== null && headers[ks[i]] !== undefined) h[ks[i]] = headers[ks[i]];
    }
  }
  let payload = null;
  if (body !== undefined && body !== null) {
    payload = JSON.stringify(body);
    h['Content-Type'] = 'application/json';
  }
  if (method !== 'GET' && !anon && st.csrf) {
    h['X-CSRF-Token'] = st.csrf;
  }
  return http.request(method, url(path), payload, {
    headers: h,
    redirects: 0,
    jar: st.jar,
  });
}

function newState() {
  const n = ((__VU - 1) % 16) + 1;
  return {
    username: 'bench-' + n,
    jar: new http.CookieJar(),
    csrf: null,
    cartId: null,
    cartEtag: null,
    grantId: null,
    journey: __VU + '-' + __ITER + '-' + Date.now(),
  };
}

// Fresh login per journey. A 302 Location is fetched exactly once.
function login(st) {
  st.grantId = null;
  const form = send(st, 'GET', '/v2/login-form', undefined, null, true);
  if (form.status !== 200) return false;
  const token = form.html('input[name="csrf"]:not([value=""])').attr('value');
  if (!token) return false;

  const res = send(st, 'POST', '/v2/login',
    { username: st.username, password: PASSWORD, csrf: token }, null, true);

  if (res.status === 302) {
    const loc = hdr(res, 'Location');
    if (!loc) return false;
    const g = send(st, 'GET', loc, undefined, null, true);
    if (g.status < 200 || g.status >= 300) return false;
    const gb = json(g);
    st.csrf = gb && typeof gb.csrf === 'string' && gb.csrf.length ? gb.csrf : token;
    return true;
  }

  if (res.status !== 200) return false;
  const body = json(res);
  if (!body || typeof body.csrf !== 'string' || !body.csrf.length) return false;
  st.csrf = body.csrf;
  return true;
}

function renew(st) {
  const res = send(st, 'POST', '/v2/session/renew', {});
  if (res.status < 200 || res.status >= 300) return false;
  const body = json(res);
  if (!body || typeof body.csrf !== 'string' || !body.csrf.length) return false;
  st.csrf = body.csrf;
  return true;
}

function recoverCart(st) {
  if (st.cartId === null) return true;
  const res = send(st, 'POST', '/v2/carts/' + st.cartId + '/recover', {});
  if (res.status < 200 || res.status >= 300) return false;
  absorb(st, json(res));
  const etag = hdr(res, 'ETag');
  if (etag) st.cartEtag = etag;
  return true;
}

// Bounded recovery: at most one recovery + one retry per operation.
// expired -> renew, recover cart, retry once.
// session -> renew (may fail), fresh login, recover cart, retry once.
// denied / other -> return raw response so the assertion fails.
function call(st, fn, onRaw) {
  let res = fn();
  if (onRaw) onRaw(res);
  if (res.status !== 401) return res;

  const err = errorOf(res);
  if (err === 'expired') {
    if (!renew(st)) return res;
  } else if (err === 'session') {
    renew(st);
    if (!login(st)) return res;
  } else {
    return res;
  }

  if (!recoverCart(st)) return res;
  res = fn();
  if (onRaw) onRaw(res);
  return res;
}

function idCompare(a, b) {
  const sa = String(a);
  const sb = String(b);
  const na = Number(sa);
  const nb = Number(sb);
  if (sa !== '' && sb !== '' && !isNaN(na) && !isNaN(nb)) return na - nb;
  return sa < sb ? -1 : (sa > sb ? 1 : 0);
}

// Order-independent selection: lowest product id that has an in-stock
// variant belonging to that parent; lowest in-stock variant id under it.
function selectEligible(products, reverse) {
  const list = reverse ? products.slice().reverse() : products;
  const seen = {};
  const eligible = [];
  for (let i = 0; i < list.length; i++) {
    const p = list[i];
    if (!p || p.id === undefined || p.id === null) continue;
    const pk = String(p.id);
    if (seen[pk]) continue;
    seen[pk] = true;

    const variants = Array.isArray(p.variants) ? p.variants : [];
    const live = [];
    for (let j = 0; j < variants.length; j++) {
      const v = variants[j];
      if (!v || v.id === undefined || v.id === null) continue;
      if (v.product_id !== undefined && v.product_id !== null && String(v.product_id) !== pk) continue;
      if (!(v.in_stock === true || v.in_stock === 'true')) continue;
      live.push(v);
    }
    if (live.length === 0) continue;
    live.sort((a, b) => idCompare(a.id, b.id));
    eligible.push({ product: p, variant: live[0] });
  }
  if (eligible.length === 0) return null;
  eligible.sort((a, b) => idCompare(a.product.id, b.product.id));
  return eligible[0];
}

function findProduct(st) {
  let candidates = [];

  const listRes = call(st, () => send(st, 'GET', '/v2/catalog'));
  if (listRes.status === 200) {
    const b = json(listRes);
    if (b && b.data && Array.isArray(b.data.products)) {
      candidates = candidates.concat(b.data.products);
    }
  }
  const reverse = PROFILE.reverse_catalog === true;
  let found = selectEligible(candidates, reverse);
  if (found) return found;

  let next = '/v2/catalog/page';
  for (let page = 0; page < MAX_CATALOG_PAGES && next; page++) {
    const target = next;
    const r = call(st, () => send(st, 'GET', target));
    if (r.status !== 200) break;
    const b = json(r);
    if (!b || !b.data) break;
    if (b.data.product) {
      candidates.push(b.data.product);
    } else if (Array.isArray(b.data.products)) {
      candidates = candidates.concat(b.data.products);
    }
    next = typeof b.next === 'string' && b.next.length ? b.next : null;
  }
  found = selectEligible(candidates, reverse);
  return found;
}

// Challenge form -> POST action once (302) -> GET Location once -> grant_id.
function obtainGrant(st) {
  const formRes = call(st, () => send(st, 'GET', '/v2/challenge-form'));
  if (formRes.status !== 200) return null;

  const action = formRes.html('form[action^="/v2/challenges/"]').attr('action');
  const challenge = formRes.html('form[action^="/v2/challenges/"] input[name="challenge"]').attr('value');
  if (!action || !challenge) return null;

  const post = call(st, () => send(st, 'POST', action, { challenge: challenge }));
  if (post.status !== 302) return null;
  const loc = hdr(post, 'Location');
  if (!loc) return null;

  const g = send(st, 'GET', loc);
  if (g.status !== 200) return null;
  const body = json(g);
  if (!body || body.grant_id === undefined || body.grant_id === null) return null;
  absorb(st, body);
  return body.grant_id;
}

function createCart(st, sel) {
  const res = call(st, () => {
    const body = { product_id: sel.product.id, variant_id: sel.variant.id };
    if (st.grantId !== null && st.grantId !== undefined) body.grant_id = st.grantId;
    return send(st, 'POST', '/v2/carts', body);
  });
  if (res.status !== 201) return false;
  const body = json(res);
  if (!body || body.id === undefined || body.id === null) return false;
  absorb(st, body);
  st.cartId = body.id;
  st.cartEtag = hdr(res, 'ETag');
  st.grantId = null;
  return true;
}

function readCart(st) {
  const res = call(st, () => send(st, 'GET', '/v2/carts/' + st.cartId));
  if (res.status !== 200) return null;
  const etag = hdr(res, 'ETag');
  if (etag) st.cartEtag = etag;
  const body = json(res);
  absorb(st, body);
  return body;
}

// Cart must reference only the selected parent and variant, and be this cart.
function cartLinked(body, st, sel) {
  if (!body) return false;
  if (body.id !== undefined && body.id !== null && String(body.id) !== String(st.cartId)) return false;

  const wantV = String(sel.variant.id);
  const wantP = String(sel.product.id);
  const variants = [];
  const products = [];

  if (body.variant_id !== undefined && body.variant_id !== null) variants.push(String(body.variant_id));
  if (body.variant && body.variant.id !== undefined && body.variant.id !== null) variants.push(String(body.variant.id));
  if (body.product_id !== undefined && body.product_id !== null) products.push(String(body.product_id));

  const lines = Array.isArray(body.items) ? body.items : [];
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];
    if (!l) continue;
    if (l.variant_id !== undefined && l.variant_id !== null) variants.push(String(l.variant_id));
    if (l.product_id !== undefined && l.product_id !== null) products.push(String(l.product_id));
  }

  if (variants.length === 0) return false;
  for (let i = 0; i < variants.length; i++) {
    if (variants[i] !== wantV) return false;
  }
  for (let i = 0; i < products.length; i++) {
    if (products[i] !== wantP) return false;
  }
  return true;
}

function ifMatch(st) {
  return st.cartEtag ? { 'If-Match': st.cartEtag } : {};
}

function patchQuantity(st, qty) {
  const attempt = () => send(st, 'PATCH', '/v2/carts/' + st.cartId, { quantity: qty }, ifMatch(st));
  let res = call(st, attempt);
  if (res.status === 412) {
    if (!readCart(st)) return false;
    res = call(st, attempt);
  }
  if (res.status !== 200) return false;
  absorb(st, json(res));
  const etag = hdr(res, 'ETag');
  if (etag) st.cartEtag = etag;
  return true;
}

// Only status=ready yields a reservation_id. Pending/failed never reach checkout.
function reserveReady(st) {
  const res = call(st, () => send(st, 'POST', '/v2/reservations', { cart_id: st.cartId }));
  if (res.status !== 202) return null;
  const body = json(res);
  absorb(st, body);
  if (!body || !body.status_url) return null;

  for (let i = 0; i < MAX_POLLS; i++) {
    sleep(POLL_GAP_S);
    const p = send(st, 'GET', body.status_url);
    if (p.status !== 200) return null;
    const pb = json(p);
    if (!pb) return null;
    if (pb.status === 'ready') {
      if (pb.reservation_id !== undefined && pb.reservation_id !== null) return pb.reservation_id;
      if (pb.id !== undefined && pb.id !== null) return pb.id;
      return null;
    }
    if (pb.status === 'failed') return null;
  }
  return null;
}

function placeOrder(st, reservationId) {
  const key = 'order-' + st.journey + '-' + st.cartId;
  const attempt = () => {
    const h = { 'Idempotency-Key': key };
    if (st.cartEtag) h['If-Match'] = st.cartEtag;
    return send(st, 'POST', '/v2/orders',
      { cart_id: st.cartId, reservation_id: reservationId }, h);
  };
  let res = call(st, attempt);
  if (res.status === 412) {
    if (!readCart(st)) return res;
    res = call(st, attempt);
  }
  return res;
}

function orderAccepted(res) {
  if (res.status !== 201) return false;
  const b = json(res);
  return !!(b && b.accepted === true && b.id !== undefined && b.id !== null);
}

function isWorkOk(res) {
  if (res.status !== 200) return false;
  const b = json(res);
  return !!(b && b.ok === true);
}

function isUnexpectedWork(res) {
  if (res.status === 401 && errorOf(res) === 'expired') return false;
  if (res.status === 429 && hdr(res, 'Retry-After') !== null) return false;
  return !isWorkOk(res);
}

// One business_failure sample per raw /v2/work response (retries included).
function workCall(st) {
  let retries = 0;
  for (;;) {
    const res = call(st,
      () => send(st, 'POST', '/v2/work', {}),
      (raw) => businessFailure.add(isUnexpectedWork(raw)));
    if (res.status === 429 && hdr(res, 'Retry-After') !== null && retries < MAX_SCHEDULED_RETRIES) {
      retries++;
      sleep(1);
      continue;
    }
    return res;
  }
}

export default function journey() {
  const st = newState();

  if (!assertOk('login session established', login(st))) return;

  const sel = findProduct(st);
  if (!assertOk('correct eligible parent selected', sel !== null && sel.variant.in_stock !== false)) return;

  st.grantId = obtainGrant(st);
  if (!assertOk('challenge grant obtained', st.grantId !== null)) return;

  if (!assertOk('cart created with selected variant', createCart(st, sel))) return;

  let body = readCart(st);
  if (!assertOk('cart linked to selected variant', cartLinked(body, st, sel))) return;

  if (!assertOk('cart quantity patched', patchQuantity(st, CART_QTY))) return;

  body = readCart(st);
  if (!assertOk('cart linked after patch', cartLinked(body, st, sel))) return;

  const reservationId = reserveReady(st);
  if (!assertOk('reservation ready', reservationId !== null)) return;

  body = readCart(st);
  if (!assertOk('cart linked at checkout', cartLinked(body, st, sel))) return;

  const orderRes = placeOrder(st, reservationId);
  const accepted = orderAccepted(orderRes);
  if (accepted) absorb(st, json(orderRes));
  if (!assertOk('order accepted', accepted)) return;

  const work = workCall(st);
  assertOk('work ok', isWorkOk(work));
}
