            return False
        if out.etag:
            self.cart_etag = out.etag
        return True

    def _patch_check(self, qty):
        def check(data, resp):
            problem = self._link_problem(data, self.cart_id)
            if problem:
                return problem
            if isinstance(data, dict) and "quantity" in data and data["quantity"] != qty:
                return "quantity mismatch"
            return None
        return check

    def _patch_cart(self):
        qty = 1 + (self.seq % 3)
        path = f"/v2/carts/{self.cart_id}"
        body = {"quantity": qty}
        out = self._call("PATCH", path, "/v2/carts/[id]", (200,), body=body,
                         headers=self._ifmatch(), validate=self._patch_check(qty),
                         expect412=True)
        if out.status == 412:
            if not self._reread_cart():
                return False
            out = self._call("PATCH", path, "/v2/carts/[id]", (200,), body=body,
                             headers=self._ifmatch(), validate=self._patch_check(qty))
        if not out.ok:
            return False
        return self._reread_cart()

