    def _link_problem(self, data, cid):
        if not isinstance(data, dict):
            return "cart body is not an object"
        if "id" in data and str(data["id"]) != str(cid):
            return "cart id mismatch"
        if "product_id" in data and str(data["product_id"]) != str(self.sel_pid):
            return "cart product mismatch"
        if "variant_id" in data and str(data["variant_id"]) != str(self.sel_vid):
            return "cart variant mismatch"
        return None

    def _create_check(self, data, resp):
        if not isinstance(data, dict) or data.get("id") in (None, ""):
            return "cart id missing"
        return self._link_problem(data, data["id"])

    def _create_cart(self, pid, vid, grant):
        body = {"product_id": pid, "variant_id": vid, "grant_id": grant}
        out = self._call("POST", "/v2/carts", "/v2/carts", (201,), body=body,
                         validate=self._create_check)
        if not out.ok:
            return False
        self.cart_id = out.data["id"]
        self.idem_key = str(uuid.uuid4())
        self.cart_etag = out.etag
        return self._reread_cart()

    def _reread_cart(self):
        out = self._call("GET", f"/v2/carts/{self.cart_id}", "/v2/carts/[id]", (200,),
                         validate=lambda data, resp: self._link_problem(data, self.cart_id))
        if not out.ok:
            return False
        if out.etag:
            self.cart_etag = out.etag
        return True

    def _patch_check(self, qty):
        def check(data, resp):
            problem = self._link_problem(data, self.cart_id)
            if problem:
                return problem
            if isinstance(data, dict) and "quantity" in data and data["quantity"] != qty:
                return "quantity mismatch"
            return None
        return check

    def _patch_cart(self):
        qty = 1 + (self.seq % 3)
        path = f"/v2/carts/{self.cart_id}"
        body = {"quantity": qty}
        out = self._call("PATCH", path, "/v2/carts/[id]", (200,), body=body,
                         headers=self._ifmatch(), validate=self._patch_check(qty),
                         expect412=True)
        if out.status == 412:
            if not self._reread_cart():
                return False
            out = self._call("PATCH", path, "/v2/carts/[id]", (200,), body=body,
                             headers=self._ifmatch(), validate=self._patch_check(qty))
        if not out.ok:
            return False
        return self._reread_cart()

    # ---------- reservation ----------

    def _reservation_created(self, data, resp):
        if not isinstance(data, dict) or not isinstance(data.get("status_url"), str):
            return "status_url missing"
        if self._to_path(data["status_url"]) is None:
            return "foreign status_url"
        return None

    def _poll_check(self, last):
        def check(data, resp):
            if not isinstance(data, dict):
                return "status body is not an object"
            st = data.get("status")
            if st == "ready":
                if data.get("reservation_id") in (None, ""):
                    return "ready without reservation_id"
                return None
            if st == "pending":
                return "reservation still pending" if last else None
            if st == "failed":
                return "reservation failed"
            return f"unknown reservation status {st!r}"
        return check

    def _reserve(self):
        out = self._call("POST", "/v2/reservations", "/v2/reservations", (202,),
                         body={"cart_id": self.cart_id}, validate=self._reservation_created)
        if not out.ok:
            return None
        status_path = self._to_path(out.data["status_url"])
        for attempt in range(1, MAX_POLLS + 1):
            time.sleep(POLL_GAP_S)
            last = attempt == MAX_POLLS
            out = self._attempt("GET", status_path, "/v2/reservations/[status]", (200,),
                                validate=self._poll_check(last))
            if not out.ok:
                return None
            if out.data.get("status") == "ready":
                return out.data["reservation_id"]
        return None

    # ---------- order ----------

    def _order_check(self, data, resp):
        if not isinstance(data, dict):
            return "order body is not an object"
        if data.get("accepted") is not True:
            return "order not accepted"
        if data.get("id") in (None, ""):
            return "order id missing"
        if "cart_id" in data and str(data["cart_id"]) != str(self.cart_id):
            return "order cart mismatch"
        return None

    def _order_headers(self):
        h = {"Idempotency-Key": self.idem_key}
        h.update(self._ifmatch())
        return h

    def _place_order(self, reservation_id):
        body = {"cart_id": self.cart_id}
        if reservation_id is not None:
            body["reservation_id"] = reservation_id
        out = self._call("POST", "/v2/orders", "/v2/orders", (201,), body=body,
                         headers=self._order_headers(), validate=self._order_check,
                         expect412=True)
        if out.status == 412:
            if not self._reread_cart():
                return False
            out = self._call("POST", "/v2/orders", "/v2/orders", (201,), body=body,
                             headers=self._order_headers(), validate=self._order_check)
        return out.ok

    # ---------- work ----------

    def _work(self):
        self._call("POST", "/v2/work", "/v2/work", (200,), body={},
                   validate=_check_work, work=True)

    # ---------- journey ----------

    def _journey(self):
        self._reset_cart()
        if not self._login():
            return
        self._work()
        products = self._catalog()
        if products is None:
            return
        pick = self._select(products)
        if pick is None:
            return
        pid, vid = pick
        grant = self._challenge()
        if grant is None:
            return
        if not self._create_cart(pid, vid, grant):
            return
        if not self._patch_cart():
            return
        reservation_id = self._reserve()
        if reservation_id is None:
            return
        self._place_order(reservation_id)

    @task
    def shop_journey(self):
        if self.journeys >= ITERATIONS or _STATE["started"] >= TOTAL_JOURNEYS:
            raise StopUser()
        _STATE["started"] += 1
        try:
            self._journey()
        finally:
            _STATE["finished"] += 1
            self.journeys += 1
        if self.journeys >= ITERATIONS:
            raise StopUser()


class ShopLoadShape(LoadTestShape):
