  let out;
  if (/^https?:\/\//i.test(ref)) out = ref;
  else if (ref.indexOf('//') === 0) return null;
  else if (ref.charAt(0) === '/') out = ORIGIN + ref;
  else if (ref.charAt(0) === '?') out = base.replace(/[?#].*$/, '') + ref;
  else out = base.replace(/[?#].*$/, '').replace(/[^\/]*$/, '') + ref;
