    const seg = segments[s];
    const ft = seg.match(/<form\b[^>]*>/i);
    if (!ft) continue;
    const fa = parseAttrs(ft[0]);
    if (!fa.action || fa.action.indexOf('/v2/challenges/') < 0) continue;
    const inputs = findInputs(seg);
    for (let i = 0; i < inputs.length; i++) {
