// Catalog pagination (follow next cursors, max MAX_PAGES, no guessing)
// ---------------------------------------------------------------------------
function pageProducts(body) {
  const out = [];
  if (body.product && typeof body.product === 'object') out.push(body.product);
  if (Array.isArray(body.products)) {
    for (let i = 0; i < body.products.length; i++) out.push(body.products[i]);
