    const next = nextCursor(body);
    if (next === null) return { ok: false }; // last page reached, nothing eligible
    if (page === MAX_PAGES) break;           // bounded traversal

    const nextUrl = resolveRef(next, url);
    if (!assertOk(!!nextUrl && !visited[nextUrl], 'catalog: cursor on target and not looping')) {
