// ---------------------------------------------------------------------------
// Reservation (only status=ready yields reservation_id)
// ---------------------------------------------------------------------------
function awaitReservation(st, statusUrl) {
  for (let poll = 1; poll <= POLL_LIMIT; poll++) {
    sleep(POLL_GAP_S);
    const r = step(st, () => http.get(statusUrl, P(st, {}, 'reservation-status')));
    if (r.status !== 200 && r.status !== 202) return { ok: false };
    const b = jsonOf(r) || {};
