}

// ---------------------------------------------------------------------------
// Order (stable Idempotency-Key per cart; 412 re-read once)
// ---------------------------------------------------------------------------
function postOrder(st) {
  const body = { cart_id: st.cartId };
  if (st.reservationId !== null) body.reservation_id = st.reservationId;
  const h = jsonHeaders(st, { 'Idempotency-Key': st.idemKey, 'If-Match': st.etag });
  return http.post(ORIGIN + '/v2/orders', JSON.stringify(body), P(st, h, 'order'));
