function orderWithRetry(st) {
  return step(st, () => {
    let r = postOrder(st);
    if (r.status === 412) {
      const g = getCart(st);
      if (g.status !== 200) return g;
      r = postOrder(st);
    }
    return r;
  });
}

// ---------------------------------------------------------------------------
// Journey
// ---------------------------------------------------------------------------
export default function () {
  const st = newState(
    ACCOUNTS[((__VU - 1) * ITERATIONS + __ITER) % ACCOUNTS.length],
    __VU,
