    )
  );
  const rb = jsonOf(rr) || {};
  if (!assertOk(rr.status === 202 && typeof rb.status_url === 'string', 'reservation: 202 with status_url')) return;
  updateCsrf(st, rb);

  const statusUrl = resolveRef(rb.status_url, ORIGIN + '/v2/reservations');
  if (!assertOk(!!statusUrl, 'reservation: status_url on target origin')) return;

  const rd = awaitReservation(st, statusUrl);
  if (!assertOk(rd.ok, 'reservation: status=ready within poll budget')) return;
  st.reservationId = rd.reservationId;

  // 6. Order (single committed order per cart)
  st.idemKey = 'idem-' + String(st.cartId) + '-' + st.vu + '-' + st.iter + '-' +
    Date.now() + '-' + Math.floor(Math.random() * 1e9);

  const or = orderWithRetry(st);
  const ob = jsonOf(or) || {};
  if (!assertOk(
    or.status === 201 && ob.accepted === true && ob.id !== undefined && ob.id !== null,
    'order: 201 accepted with id'
  )) return;
  updateCsrf(st, ob);

  console.log(JSON.stringify({
    vu: st.vu,
    iter: st.iter,
    user: st.user,
    product_id: st.productId,
    variant_id: st.variantId,
    cart_id: st.cartId,
    reservation_id: st.reservationId,
    order_id: ob.id,
  }));
}
