"""Locust 2.47 locustfile: cursor-driven eligible-item discovery and one-order checkout journeys."""
import html.parser
import os
import re
import time
import uuid
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, constant, task
from locust.exception import StopUser
from locust.shape import LoadTestShape

BASE_URL = os.environ["BASE_URL"].rstrip("/")
_BASE = urlsplit(BASE_URL)
if _BASE.scheme != "http" or _BASE.netloc != "127.0.0.1:8000":
    raise RuntimeError("only http://127.0.0.1:8000 is in scope")

PASSWORD = "bench"
ACCOUNTS = ["bench-%d" % i for i in range(1, 17)] + ["bench"]
USERS = 2
ITERATIONS = 2
MAX_CATALOG_PAGES = 3
MAX_RESERVATION_POLLS = 5
RESERVATION_POLL_GAP = 0.06
MAX_WORK_RETRIES = 4
MAX_RUN_SECONDS = 900
CHALLENGE_PATH_RE = re.compile(r"^/v2/challenges/[^/]+$")
REDIRECT_CODES = (301, 302, 303, 307, 308)

_STATE = {"slots": 0, "done": 0}


# ---------------------------------------------------------------- HTML parsing

class _Scan(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inputs = []
        self.forms = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        a = {}
        for k, v in attrs:
            if k and k.lower() not in a:
                a[k.lower()] = v if v is not None else ""
        if tag == "form":
            self._form = {"action": a.get("action", ""), "inputs": []}
            self.forms.append(self._form)
        elif tag == "input":
            self.inputs.append(a)
            if self._form is not None:
                self._form["inputs"].append(a)

    def handle_endtag(self, tag):
        if tag == "form":
            self._form = None


def _scan(text):
    s = _Scan()
    try:
        s.feed(text or "")
        s.close()
    except Exception:
        pass
    return s


def _login_csrf(text):
    scan = _scan(text)
    groups = [f["inputs"] for f in scan.forms
              if urlsplit(f["action"]).path.rstrip("/") == "/v2/login"]
    groups.append(scan.inputs)
    fallback = None
    for group in groups:
        for attrs in group:
            if attrs.get("name") != "csrf" or "disabled" in attrs:
                continue
            value = attrs.get("value", "").strip()
            if not value:
                continue
            if attrs.get("type", "hidden").strip().lower() == "hidden":
                return value
            if fallback is None:
                fallback = value
    return fallback


def _challenge_target(text):
    for form in _scan(text).forms:
        if not CHALLENGE_PATH_RE.match(urlsplit(form["action"]).path or ""):
            continue
        for attrs in form["inputs"]:
            if attrs.get("name") == "challenge" and attrs.get("value", "").strip():
                return form["action"], attrs["value"].strip()
    return None


# ---------------------------------------------------------------- URL helpers

def _absolute(base, ref):
    """Resolve ref against base; only same-origin http URLs are allowed."""
    if not isinstance(ref, str) or not ref.strip():
        return None
    full = urljoin(base, ref.strip())
    p = urlsplit(full)
    if p.scheme != _BASE.scheme or p.netloc != _BASE.netloc:
        return None
    return full


def _path(full):
    p = urlsplit(full)
    out = p.path or "/"
    if p.query:
        out += "?" + p.query
    return out


def _hdr(headers, key):
    if headers is None:
        return None
    try:
        v = headers.get(key)
    except Exception:
        v = None
    if v is not None:
        return v
    low = key.lower()
    try:
        for k, val in headers.items():
            if str(k).lower() == low:
                return val
    except Exception:
        pass
    return None


def _retry_after(headers):
    try:
        return max(1.0, float(_hdr(headers, "Retry-After") or 1))
    except (TypeError, ValueError):
        return 1.0


# ---------------------------------------------------------------- catalog helpers

def _products(body):
    if not isinstance(body, dict):
        return []
    scopes = [body]
    data = body.get("data")
    if isinstance(data, dict):
        scopes.append(data)
    found = []
    for scope in scopes:
        items = scope.get("products")
        if isinstance(items, list):
            found.extend(p for p in items if isinstance(p, dict))
        for key in ("product", "item"):
            single = scope.get(key)
            if isinstance(single, dict):
                found.append(single)
    if isinstance(data, list):
        found.extend(p for p in data if isinstance(p, dict))
    return found


def _eligible(body):
    for product in _products(body):
        pid = product.get("id")
        variants = product.get("variants")
        if pid is None or not isinstance(variants, list):
            continue
        for variant in variants:
            if (isinstance(variant, dict)
                    and variant.get("in_stock") is True
                    and variant.get("id") is not None):
                return pid, variant["id"]
    return None


def _next_link(body):
    if not isinstance(body, dict):
        return None
    candidates = [body.get("next")]
    data = body.get("data")
    if isinstance(data, dict):
        candidates.append(data.get("next"))
    for c in candidates:
        if isinstance(c, str) and c.strip():
            return c.strip()
    return None


# ---------------------------------------------------------------- result carrier

class _Res(object):
    def __init__(self):
        self.status = None
        self.data = None
        self.text = ""
        self.headers = None
        self.ok = False
        self.auth = None
        self.throttled = False
        self.soft = False


# ---------------------------------------------------------------- virtual user

class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0.1)

    def on_start(self):
        self.slot = _STATE["slots"]
        _STATE["slots"] += 1
        self.account = ACCOUNTS[self.slot % len(ACCOUNTS)]
        self.journeys = 0
        self.reset_journey()

    def reset_journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.idem_key = None
        self.order_id = None

    @task
    def journey(self):
        if self.slot >= USERS:
            raise StopUser()
        if self.journeys >= ITERATIONS:
            _STATE["done"] += 1
            raise StopUser()
        self.journeys += 1
        self.reset_journey()
        try:
            self.run_journey()
        except Exception:
            pass

    # ------------------------------------------------------------ journey

    def run_journey(self):
        if not self.login_user():
            return
        if not self.browse_work():
            return
        item = self.find_eligible_item()
        if item is None:
            return
        grant = self.claim_grant()
        if grant is None:
            return
        if not self.create_cart(item[0], item[1], grant):
            return
        if not self.set_quantity(1):
            return
        reservation_id = self.reserve()
        if reservation_id is None:
            return
        self.checkout(reservation_id)

    # ------------------------------------------------------------ transport

    def call_api(self, method, path, name, body=None, headers=None, ok=(200,),
                 check=None, csrf=True, soft=(), throttle=False):
        res = _Res()
        hdrs = dict(headers or {})
        if csrf and method != "GET" and self.csrf and "X-CSRF-Token" not in hdrs:
            hdrs["X-CSRF-Token"] = self.csrf
        with self.client.request(method, path, name=name, json=body, headers=hdrs,
                                 allow_redirects=False, catch_response=True) as resp:
            res.status = resp.status_code
            res.headers = resp.headers
            res.text = resp.text or ""
            try:
                res.data = resp.json()
            except Exception:
                res.data = None
            err = res.data.get("error") if isinstance(res.data, dict) else None
            passed = res.status in ok and (check is None or bool(check(res.data)))
            if passed:
                res.ok = True
                token = res.data.get("csrf") if isinstance(res.data, dict) else None
                if isinstance(token, str) and token:
                    self.csrf = token
                resp.success()
            elif res.status == 401 and err in ("expired", "session"):
                res.auth = err
                resp.success()  # expected expiry; handled by recovery
            elif throttle and res.status == 429:
                res.throttled = True
                resp.success()  # scheduled 429; not a failure
            elif res.status in soft:
                res.soft = True
                resp.success()  # protocol-defined precondition conflict; handled by caller
            else:
                resp.failure("%s %s -> %s error=%s" % (method, name, res.status, err))
        return res

    def op(self, method, path, name, body=None, headers=None, ok=(200,), check=None,
           soft=(), throttle=False, max_throttle=0):
        """One logical operation: bounded throttle retries and one auth recovery."""
        recovered = False
        throttles = 0
        while True:
            r = self.call_api(method, path, name, body=body, headers=headers, ok=ok,
                              check=check, soft=soft, throttle=throttle)
            if r.throttled and throttles < max_throttle:
                throttles += 1
                time.sleep(_retry_after(r.headers))
                continue
            if r.auth is not None and not recovered:
                recovered = True
                if not self.recover_session(r.auth):
                    return None
                continue
            return r

    def recover_session(self, kind):
        renew = self.call_api("POST", "/v2/session/renew", "/v2/session/renew",
                              body={}, ok=(200,))
        if not renew.ok:
            if kind == "expired":
                return False
            if not self.login_user():
                return False
        if self.cart_id is not None:
            rec = self.call_api("POST", "/v2/carts/%s/recover" % self.cart_id,
                                "/v2/carts/[id]/recover", body={}, ok=(200, 201, 202))
            if not rec.ok:
                return False
        return True

    # ------------------------------------------------------------ steps

    def login_user(self):
        self.csrf = None
        form = self.op("GET", "/v2/login-form", "/v2/login-form", ok=(200,))
        if form is None or not form.ok:
            return False
        token = _login_csrf(form.text)
        if not token:
            return False
        creds = {"username": self.account, "password": PASSWORD, "csrf": token}
        r = self.call_api("POST", "/v2/login", "/v2/login", body=creds,
                          ok=(200,) + REDIRECT_CODES, csrf=False)
        if not r.ok:
            return False
        if r.status in REDIRECT_CODES:
            full = _absolute(BASE_URL + "/", _hdr(r.headers, "Location"))
            if full is None:
                return False
            g = self.call_api("GET", _path(full), "/v2/login/[location]", ok=(200,))
            if not g.ok:
                return False
        return bool(self.csrf)

    def browse_work(self):
        def is_ok(d):
            return isinstance(d, dict) and d.get("ok") is True
        r = self.op("POST", "/v2/work", "/v2/work", body={}, ok=(200,), check=is_ok,
                    throttle=True, max_throttle=MAX_WORK_RETRIES)
        return r is not None and r.ok

    def find_eligible_item(self):
        cur = BASE_URL + "/v2/catalog"
        name = "/v2/catalog"
        seen = set()
        for _ in range(MAX_CATALOG_PAGES):
            seen.add(cur)
            r = self.op("GET", _path(cur), name, ok=(200,))
            if r is None or not r.ok:
                return None
            hit = _eligible(r.data)
            if hit is not None:
                return hit
            link = _next_link(r.data)
            if link is None:  # last page reached with no eligible item
                return None
            cur = _absolute(cur, link)
            if cur is None or cur in seen:
                return None
            name = "/v2/catalog/page"
        return None

    def claim_grant(self):
        form = self.op("GET", "/v2/challenge-form", "/v2/challenge-form", ok=(200,))
        if form is None or not form.ok:
            return None
        target = _challenge_target(form.text)
        if target is None:
            return None
        action, token = target
        full = _absolute(BASE_URL + "/", action)
        if full is None:
            return None
        post = self.op("POST", _path(full), "/v2/challenges/[id]",
                       body={"challenge": token}, ok=REDIRECT_CODES)
        if post is None or not post.ok:
            return None
        location = _absolute(full, _hdr(post.headers, "Location"))
        if location is None:
            return None
        got = self.call_api("GET", _path(location), "/v2/claims/[location]", ok=(200,))
        if not got.ok or not isinstance(got.data, dict):
            return None
        grant = got.data.get("grant_id")
        return grant if grant not in (None, "") else None

    def create_cart(self, product_id, variant_id, grant):
        body = {"product_id": product_id, "variant_id": variant_id, "grant_id": grant}

        def check(d):
            return (isinstance(d, dict)
                    and d.get("id") is not None
                    and d.get("product_id", product_id) == product_id
                    and d.get("variant_id", variant_id) == variant_id)

        r = self.op("POST", "/v2/carts", "/v2/carts", body=body, ok=(201,), check=check)
        if r is None or not r.ok:
            return False
        self.cart_id = r.data["id"]
        self.idem_key = str(uuid.uuid4())
        self.cart_etag = _hdr(r.headers, "ETag")
        if not self.cart_etag:
            return self.refresh_cart()
        return True

    def refresh_cart(self):
        cid = self.cart_id

        def check(d):
            return d is None or (isinstance(d, dict) and d.get("id", cid) == cid)

        r = self.op("GET", "/v2/carts/%s" % cid, "/v2/carts/[id]", ok=(200,), check=check)
        if r is None or not r.ok:
            return False
        etag = _hdr(r.headers, "ETag")
        if not etag:
            return False
        self.cart_etag = etag
        return True

    def set_quantity(self, qty):
        cid = self.cart_id
        body = {"quantity": qty}

        def check(d):
            return d is None or (isinstance(d, dict)
                                 and d.get("quantity", qty) == qty
                                 and d.get("id", cid) == cid)

        for attempt in range(2):
            r = self.op("PATCH", "/v2/carts/%s" % cid, "/v2/carts/[id]", body=body,
                        headers={"If-Match": self.cart_etag}, ok=(200, 204),
                        check=check, soft=(412,))
            if r is None:
                return False
            if r.ok:
                etag = _hdr(r.headers, "ETag")
                if etag:
                    self.cart_etag = etag
                    return True
                return self.refresh_cart()
            if r.soft and attempt == 0:
                if not self.refresh_cart():
                    return False
                continue
            return False
        return False

    def reserve(self):
        cid = self.cart_id

        def has_status_url(d):
            return isinstance(d, dict) and bool(d.get("status_url"))

        r = self.op("POST", "/v2/reservations", "/v2/reservations",
                    body={"cart_id": cid}, ok=(202,), check=has_status_url)
        if r is None or not r.ok:
            return None
        status_url = _absolute(BASE_URL + "/", r.data["status_url"])
        if status_url is None:
            return None

        def is_known_status(d):
            return isinstance(d, dict) and d.get("status") in ("pending", "ready")

        for _ in range(MAX_RESERVATION_POLLS):
            time.sleep(RESERVATION_POLL_GAP)
            s = self.op("GET", _path(status_url), "/v2/reservations/[status]",
                        ok=(200,), check=is_known_status)
            if s is None or not s.ok:
                return None  # failed or unexpected status: never reach checkout
            if s.data.get("status") == "ready":
                rid = s.data.get("reservation_id")
                if rid in (None, "") or s.data.get("cart_id", cid) != cid:
                    return None
                return rid
        return None  # still pending after the poll budget

    def checkout(self, reservation_id):
        cid = self.cart_id
        body = {"cart_id": cid, "reservation_id": reservation_id}

        def accepted(d):
            return (isinstance(d, dict)
                    and d.get("accepted") is True
                    and d.get("id") is not None
                    and d.get("cart_id", cid) == cid)

        for attempt in range(2):
            headers = {"Idempotency-Key": self.idem_key}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            r = self.op("POST", "/v2/orders", "/v2/orders", body=body, headers=headers,
                        ok=(200, 201), check=accepted, soft=(412,))
            if r is None:
                return False
            if r.ok:
                self.order_id = r.data["id"]
                return True
            if r.soft and attempt == 0:
                if not self.refresh_cart():
                    return False
                continue
            return False
        return False


# ---------------------------------------------------------------- load shape

class ShopShape(LoadTestShape):
    def tick(self):
        if _STATE["done"] >= USERS or self.get_run_time() > MAX_RUN_SECONDS:
            return None
        return USERS, USERS
