import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL =
            System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";
    private static final String PASSWORD = "bench";
    private static final int QTY = 2;

    private static final HttpProtocolBuilder PROTOCOL =
            http.baseUrl(BASE_URL).disableFollowRedirect();

    private static String absolute(String location) {
        return location.startsWith("http") ? location : BASE_URL + location;
    }

    private static Session pickInStock(Session session) {
        try {
            String[] pick = findInStock(session.getString("catalogBody"));
            if (pick == null) {
                return session.markAsFailed();
            }
            return session.set("productId", pick[0]).set("variantId", pick[1]);
        } catch (RuntimeException e) {
            return session.markAsFailed();
        }
    }

    @SuppressWarnings("unchecked")
    private static String[] findInStock(String body) {
        Map<String, Object> root = (Map<String, Object>) new JsonReader(body).read();
        Map<String, Object> data = (Map<String, Object>) root.get("data");
        List<Object> products = (List<Object>) data.get("products");
        for (Object po : products) {
            Map<String, Object> product = (Map<String, Object>) po;
            Object productId = product.get("id");
            Object variantsObj = product.get("variants");
            if (productId == null || !(variantsObj instanceof List)) {
                continue;
            }
            for (Object vo : (List<Object>) variantsObj) {
                Map<String, Object> variant = (Map<String, Object>) vo;
                if (Boolean.TRUE.equals(variant.get("in_stock")) && variant.get("id") != null) {
                    return new String[] {String.valueOf(productId), String.valueOf(variant.get("id"))};
                }
            }
        }
        return null;
    }

    static final class JsonReader {
        private final String s;
        private int i;

        JsonReader(String s) {
            this.s = s;
        }

        Object read() {
            return value();
        }

        private void ws() {
            while (i < s.length() && Character.isWhitespace(s.charAt(i))) {
                i++;
            }
        }

        private Object value() {
            ws();
            char c = s.charAt(i);
            switch (c) {
                case '{':
                    return object();
                case '[':
                    return array();
                case '"':
                    return string();
                case 't':
                    i += 4;
                    return Boolean.TRUE;
                case 'f':
                    i += 5;
                    return Boolean.FALSE;
                case 'n':
                    i += 4;
                    return null;
                default:
                    return number();
            }
        }

        private Map<String, Object> object() {
            Map<String, Object> m = new LinkedHashMap<>();
            i++;
            ws();
            if (s.charAt(i) == '}') {
                i++;
                return m;
            }
            while (true) {
                ws();
                String key = string();
                ws();
                i++; // ':'
                m.put(key, value());
                ws();
                char c = s.charAt(i++);
                if (c == '}') {
                    return m;
                }
            }
        }

        private List<Object> array() {
            List<Object> l = new ArrayList<>();
            i++;
            ws();
            if (s.charAt(i) == ']') {
                i++;
                return l;
            }
            while (true) {
                l.add(value());
                ws();
                char c = s.charAt(i++);
                if (c == ']') {
                    return l;
                }
            }
        }

        private String string() {
            StringBuilder b = new StringBuilder();
            i++; // opening quote
            while (true) {
                char c = s.charAt(i++);
                if (c == '"') {
                    return b.toString();
                }
                if (c == '\\') {
                    char e = s.charAt(i++);
                    switch (e) {
                        case 'n': b.append('\n'); break;
                        case 't': b.append('\t'); break;
                        case 'r': b.append('\r'); break;
                        case 'b': b.append('\b'); break;
                        case 'f': b.append('\f'); break;
                        case 'u':
                            b.append((char) Integer.parseInt(s.substring(i, i + 4), 16));
                            i += 4;
                            break;
                        default: b.append(e);
                    }
                } else {
                    b.append(c);
                }
            }
        }

        private String number() {
            int start = i;
            while (i < s.length() && "+-0123456789.eE".indexOf(s.charAt(i)) >= 0) {
                i++;
            }
            return s.substring(start, i);
        }
    }

    private static final ChainBuilder JOURNEY =
            exec(session -> session
                    .remove("loginLocation")
                    .remove("grantLocation")
                    .set("username", "bench-" + (session.userId() % 16 + 1)))

            // Login form and login (302 Location is GET-ed exactly once if present)
            .exec(http("login form")
                    .get("/v2/login-form")
                    .check(css("input[name=csrf]", "value").saveAs("formCsrf")))
            .exec(http("login")
                    .post("/v2/login")
                    .header("Content-Type", "application/json")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"" + PASSWORD
                            + "\",\"csrf\":\"#{formCsrf}\"}"))
                    .check(status().in(200, 302))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                    .check(header("Location").optional().saveAs("loginLocation")))
            .doIf("#{loginLocation.exists()}").then(
                    exec(http("login redirect")
                            .get(session -> absolute(session.getString("loginLocation")))
                            .check(status().is(200))
                            .check(jsonPath("$.csrf").optional().saveAs("csrf"))))

            // Catalog extraction (no guessed IDs)
            .exec(http("catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(bodyString().saveAs("catalogBody")))
            .exec(session -> pickInStock(session))
            .exitHereIfFailed()

            // Challenge -> grant (single use, expires after 2s)
            .exec(http("challenge form")
                    .get("/v2/challenge-form")
                    .check(css("form[action^='/v2/challenges/']", "action").saveAs("challengeAction"))
                    .check(css("input[name=challenge]", "value").saveAs("challenge")))
            .exec(http("challenge submit")
                    .post(session -> absolute(session.getString("challengeAction")))
                    .header("X-CSRF-Token", "#{csrf}")
                    .formParam("challenge", "#{challenge}")
                    .check(status().is(302))
                    .check(header("Location").saveAs("grantLocation")))
            .exec(http("challenge grant")
                    .get(session -> absolute(session.getString("grantLocation")))
                    .check(status().is(200))
                    .check(jsonPath("$.grant_id").saveAs("grantId"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf")))

            // Cart creation (exactly one cart per journey, grant passed once)
            .exec(http("cart create")
                    .post("/v2/carts")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\","
                            + "\"grant_id\":\"#{grantId}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs("cartId"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf")))

            // Initial revision extraction
            .exec(http("cart read initial")
                    .get("/v2/carts/#{cartId}")
                    .check(status().is(200))
                    .check(header("ETag").saveAs("etag")))

            // Conditional update; the scheduled conflict may answer 412 once
            .exec(http("cart update")
                    .patch("/v2/carts/#{cartId}")
                    .header("Content-Type", "application/json")
                    .header("If-Match", "#{etag}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"quantity\":" + QTY + "}"))
                    .check(status().in(200, 412))
                    .check(status().saveAs("patchStatus")))
            .doIfEquals("#{patchStatus}", 412).then(
                    exec(http("cart re-read after 412")
                            .get("/v2/carts/#{cartId}")
                            .check(status().is(200))
                            .check(header("ETag").saveAs("etag")))
                    .exec(http("cart update retry")
                            .patch("/v2/carts/#{cartId}")
                            .header("Content-Type", "application/json")
                            .header("If-Match", "#{etag}")
                            .header("X-CSRF-Token", "#{csrf}")
                            .body(StringBody("{\"quantity\":" + QTY + "}"))
                            .check(status().is(200))
                            .check(jsonPath("$.csrf").optional().saveAs("csrf"))))

            // Final revision and payload verification
            .exec(http("cart read final")
                    .get("/v2/carts/#{cartId}")
                    .check(status().is(200))
                    .check(header("ETag").saveAs("etag"))
                    .check(regex("\"quantity\"\\s*:\\s*" + QTY + "(?![0-9])").exists()))

            // Order commit with If-Match and stable idempotency key per cart
            .exec(http("order create")
                    .post("/v2/orders")
                    .header("Content-Type", "application/json")
                    .header("Idempotency-Key", "order-#{cartId}")
                    .header("If-Match", "#{etag}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                    .check(status().is(201))
                    .check(regex("\"accepted\"\\s*:\\s*true").exists())
                    .check(jsonPath("$.id").saveAs("orderId"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf")));

    private static final ScenarioBuilder SCENARIO =
            scenario("ModelSimulation")
                    .exec(JOURNEY)
                    .exec(JOURNEY);

    public ModelSimulation() {
        setUp(SCENARIO.injectOpen(atOnceUsers(2))).protocols(PROTOCOL);
    }
}
