import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = String(__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const QTY = 2;
const JSON_CT = 'application/json';
const EXPECTED = http.expectedStatuses(200, 201, 202, 204, 302, 401, 412, 429);

const conflictRecovered = new Counter('etag_conflict_recovered');
const journeyCommitted = new Rate('journey_committed');

export const options = {
  scenarios: {
    etag_journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

// ---------- URL handling (target only BASE) ----------

function resolveUrl(u) {
  const s = String(u);
  if (/^https?:\/\//i.test(s)) {
    if (s !== BASE && s.indexOf(BASE + '/') !== 0) {
      throw new Error('off-target URL refused: ' + s);
    }
    return s;
  }
  return BASE + (s.charAt(0) === '/' ? s : '/' + s);
}

// ---------- Response helpers ----------

function json(res) {
  if (!res) return null;
  try {
    const v = res.json();
    return v && typeof v === 'object' ? v : null;
  } catch (e) {
    return null;
  }
}

function hdr(res, name) {
  if (!res || !res.headers) return null;
  const want = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) {
      const v = res.headers[keys[i]];
      return Array.isArray(v) ? v[0] : v;
    }
  }
  return null;
}

function errorOf(res) {
  const j = json(res);
  if (j && typeof j.error === 'string') return j.error;
  const body = String(res && res.body ? res.body : '');
  let m = /"error"\s*:\s*"([a-z_]+)"/i.exec(body);
  if (m) return m[1];
  m = /error\s*[=:]\s*"?([a-z_]+)/i.exec(body);
  return m ? m[1] : '';
}

function adoptCsrf(sess, res) {
  const j = json(res);
  if (j && typeof j.csrf === 'string' && j.csrf.length > 0) {
    sess.csrf = j.csrf;
  }
}

function csrfHeaders(sess) {
  return sess.csrf ? { 'X-CSRF-Token': sess.csrf } : {};
}

function pass(name, cond) {
  const v = cond === true;
  check(v, { [name]: (x) => x === true });
  return v;
}

// ---------- HTML parsing (tolerant of attribute order/quoting, decoys) ----------

function unescapeHtml(s) {
  return String(s)
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&#x27;/g, "'")
    .replace(/&amp;/g, '&');
}

function cleanHtml(html) {
  let s = String(html || '');
  s = s.replace(/<!--[\s\S]*?-->/g, '');
  s = s.replace(/<(script|style|template|noscript|textarea|title)\b[\s\S]*?<\/\1\s*>/gi, '');
  return s;
}

function parseAttrs(s) {
  const out = {};
  const re = /([^\s"'<>\/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let m;
  while ((m = re.exec(String(s))) !== null) {
    const key = m[1].toLowerCase();
    if (out[key] !== undefined) continue;
    let val = '';
    if (m[2] !== undefined) val = m[2];
    else if (m[3] !== undefined) val = m[3];
    else if (m[4] !== undefined) val = m[4];
    out[key] = unescapeHtml(val);
  }
  return out;
}

function inputsIn(html) {
  const out = [];
  const re = /<input\b((?:[^>"']|"[^"]*"|'[^']*')*)>/gi;
  let m;
  while ((m = re.exec(String(html))) !== null) {
    out.push(parseAttrs(m[1]));
  }
  return out;
}

function loginCsrf(html) {
  const cands = inputsIn(cleanHtml(html)).filter(
    (a) => a.name === 'csrf' && !('disabled' in a) && a.value
  );
  if (cands.length === 0) return null;
  const hidden = cands.find((a) => (a.type || '').toLowerCase() === 'hidden');
  return (hidden || cands[0]).value;
}

function parseChallenge(html) {
  const clean = cleanHtml(html);
  const re = /<form\b((?:[^>"']|"[^"]*"|'[^']*')*)>([\s\S]*?)<\/form\s*>/gi;
  let m;
  while ((m = re.exec(clean)) !== null) {
    const action = parseAttrs(m[1]).action || '';
    const pm = /\/v2\/challenges\/[^\/?#\s"']+/.exec(action);
    if (!pm) continue;
    const input = inputsIn(m[2]).find(
      (a) => a.name === 'challenge' && !('disabled' in a) && a.value
    );
    if (input) return { action: pm[0], challenge: input.value };
  }
  return null;
}

// ---------- Catalog helpers ----------

function productsFrom(j) {
  if (!j) return [];
  if (j.data && Array.isArray(j.data.products)) return j.data.products;
  if (Array.isArray(j.products)) return j.products;
  if (j.data && j.data.product) return [j.data.product];
  if (j.product) return [j.product];
  return [];
}

function pickVariant(products) {
  for (const p of products) {
    if (!p || p.id === undefined || p.id === null) continue;
    const variants = Array.isArray(p.variants) ? p.variants : [];
    for (const v of variants) {
      if (
        v &&
        v.id !== undefined &&
        v.id !== null &&
        (v.in_stock === true || v.in_stock === 'true')
      ) {
        return { productId: p.id, variantId: v.id };
      }
    }
  }
  return null;
}

function cartQuantity(b) {
  if (!b || typeof b !== 'object') return null;
  if (b.quantity !== undefined) return b.quantity;
  if (b.cart && b.cart.quantity !== undefined) return b.cart.quantity;
  return null;
}

// ---------- Raw and protocol-aware requests ----------

function raw(sess, label, method, path, body, headers) {
  const h = Object.assign({}, headers || {});
  let payload = null;
  if (body !== undefined && body !== null) {
    payload = typeof body === 'string' ? body : JSON.stringify(body);
    if (!h['Content-Type']) h['Content-Type'] = JSON_CT;
  }
  return http.request(method, resolveUrl(path), payload, {
    headers: h,
    jar: sess.jar,
    redirects: 0,
    responseCallback: EXPECTED,
    tags: { op: label },
  });
}

function newSession(username) {
  return {
    username: username,
    jar: http.cookieJar(),
    csrf: null,
    cartId: null,
    etag: null,
    cartBody: null,
    idem: null,
  };
}

function login(sess) {
  const form = raw(sess, 'login-form', 'GET', '/v2/login-form', null, {});
  if (form.status !== 200) return false;
  const csrf = loginCsrf(form.body);
  if (!csrf) return false;

  let r = raw(sess, 'login', 'POST', '/v2/login',
    { username: sess.username, password: PASSWORD, csrf: csrf }, {});
  if (r.status === 302) {
    const loc = hdr(r, 'Location');
    if (!loc) return false;
    // Dynamic Location is fetched exactly once.
    r = raw(sess, 'login-redirect', 'GET', loc, null, {});
  }
  if (r.status !== 200 && r.status !== 201) return false;
  const j = json(r);
  if (!j || typeof j.csrf !== 'string' || j.csrf.length === 0) return false;
  sess.csrf = j.csrf;
  return true;
}

// Recovery is bounded: called at most once per protocol operation.
function recoverSession(sess, kind) {
  const renew = raw(sess, 'session-renew', 'POST', '/v2/session/renew', {}, csrfHeaders(sess));
  if (renew.status === 200 || renew.status === 201) {
    adoptCsrf(sess, renew);
  } else if (kind === 'session') {
    // Revoked session: renew failed, so obtain a fresh form/login.
    if (!login(sess)) return false;
  } else {
    return false;
  }

  if (sess.cartId !== null && sess.cartId !== undefined) {
    const rc = raw(sess, 'cart-recover', 'POST',
      '/v2/carts/' + sess.cartId + '/recover', {}, csrfHeaders(sess));
    if (rc.status !== 200 && rc.status !== 201 && rc.status !== 204) return false;
    adoptCsrf(sess, rc);
  }
  return true;
}

// Authenticated call with one bounded recovery and retry of the same operation.
function call(sess, label, method, path, opts) {
  const o = opts || {};
  let recovered = false;
  for (;;) {
    const headers = Object.assign({},
      typeof o.headers === 'function' ? o.headers() : (o.headers || {}));
    if (method !== 'GET' && sess.csrf && headers['X-CSRF-Token'] === undefined) {
      headers['X-CSRF-Token'] = sess.csrf;
    }
    const res = raw(sess, label, method, path, o.body, headers);
    if (method !== 'GET' && res.status >= 200 && res.status < 300) {
      adoptCsrf(sess, res);
    }
    if (res.status !== 401 || recovered) return res;
    const kind = errorOf(res);
    if (kind !== 'expired' && kind !== 'session') return res; // denied: not expiry
    recovered = true;
    if (!recoverSession(sess, kind)) return res;
    if (typeof o.beforeRetry === 'function') o.beforeRetry();
  }
}

// ---------- Journey steps ----------

function findInStockVariant(sess) {
  const first = call(sess, 'catalog', 'GET', '/v2/catalog', {});
  if (first.status === 200) {
    const v = pickVariant(productsFrom(json(first)));
    if (v) return v;
  }
  let next = '/v2/catalog/page';
  for (let page = 0; page < 3 && next; page++) {
    const r = call(sess, 'catalog-page', 'GET', next, {});
    if (r.status !== 200) return null;
    const j = json(r);
    const v = pickVariant(productsFrom(j));
    if (v) return v;
    next = j && typeof j.next === 'string' && j.next.length > 0 ? j.next : null;
  }
  return null;
}

function claimGrant(sess) {
  const form = call(sess, 'challenge-form', 'GET', '/v2/challenge-form', {});
  if (form.status !== 200) return null;
  const ch = parseChallenge(form.body);
  if (!ch) return null;

  const submit = call(sess, 'challenge-submit', 'POST', ch.action,
    { body: { challenge: ch.challenge }, headers: {} });
  if (submit.status !== 302) return null;
  const loc = hdr(submit, 'Location');
  if (!loc) return null;

  const claim = call(sess, 'challenge-claim', 'GET', loc, {});
  if (claim.status !== 200) return null;
  const cj = json(claim);
  if (!cj || cj.grant_id === undefined || cj.grant_id === null) return null;
  if (typeof cj.csrf === 'string' && cj.csrf.length > 0) sess.csrf = cj.csrf;
  return cj.grant_id;
}

function readCart(sess, label) {
  const r = call(sess, label, 'GET', '/v2/carts/' + sess.cartId, {});
  const et = hdr(r, 'ETag');
  if (r.status !== 200 || !et) return false;
  sess.etag = et;
  sess.cartBody = json(r);
  return true;
}

function reserve(sess) {
  const r = call(sess, 'reservation-create', 'POST', '/v2/reservations',
    { body: { cart_id: sess.cartId }, headers: {} });
  const j = json(r);
  if (r.status !== 202 || !j || typeof j.status_url !== 'string' || !j.status_url) {
    return null;
  }
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const p = call(sess, 'reservation-poll', 'GET', j.status_url, {});
    const pj = json(p);
    if (p.status !== 200 || !pj) return null;
    if (pj.status === 'ready') {
      return pj.reservation_id !== undefined && pj.reservation_id !== null
        ? pj.reservation_id
        : null;
    }
    if (pj.status === 'failed') return null;
    // pending: keep polling
  }
  return null;
}

function runJourney(sess) {
  if (!pass('login established session', login(sess))) return false;

  const variant = findInStockVariant(sess);
  if (!pass('in-stock variant found in catalog', variant !== null)) return false;

  const grantId = claimGrant(sess);
  if (!pass('challenge grant claimed', grantId !== null)) return false;

  const created = call(sess, 'cart-create', 'POST', '/v2/carts', {
    body: {
      product_id: variant.productId,
      variant_id: variant.variantId,
      grant_id: grantId,
    },
    headers: {},
  });
  const cj = json(created);
  if (!pass('cart created with 201 and id',
    created.status === 201 && cj !== null && cj.id !== undefined && cj.id !== null)) {
    return false;
  }
  sess.cartId = cj.id;
  sess.idem = 'order-' + sess.cartId + '-' + __VU + '-' + __ITER + '-' +
    Date.now() + '-' + Math.floor(Math.random() * 1e9);

  // Setup: initial revision extracted from the cart.
  if (!pass('initial cart ETag extracted', readCart(sess, 'cart-read-initial'))) return false;

  // Conditional update with If-Match.
  const patchHeaders = () => ({ 'If-Match': sess.etag || '', 'Content-Type': JSON_CT });
  const patchOpts = () => ({
    body: { quantity: QTY },
    headers: patchHeaders,
    beforeRetry: () => { readCart(sess, 'cart-reread-after-expiry'); },
  });

  let patch = call(sess, 'cart-patch', 'PATCH', '/v2/carts/' + sess.cartId, patchOpts());
  if (patch.status === 412) {
    // Stale revision: re-read the cart and retry the same payload once.
    if (!pass('re-read after 412 succeeded', readCart(sess, 'cart-reread-412'))) return false;
    patch = call(sess, 'cart-patch-retry', 'PATCH', '/v2/carts/' + sess.cartId, patchOpts());
    if (patch.status === 200) conflictRecovered.add(1);
  }
  if (!pass('conditional PATCH committed with 200', patch.status === 200)) return false;

  const reservationId = reserve(sess);
  if (!pass('reservation ready (status=ready)', reservationId !== null)) return false;

  if (!pass('cart re-read before checkout', readCart(sess, 'cart-read-precheckout'))) {
    return false;
  }
  if (!pass('cart quantity preserved after PATCH', cartQuantity(sess.cartBody) === QTY)) {
    return false;
  }

  // Single checkout with stable Idempotency-Key.
  const orderBody = { cart_id: sess.cartId, reservation_id: reservationId };
  const orderHeaders = () => ({
    'If-Match': sess.etag || '',
    'Idempotency-Key': sess.idem,
    'Content-Type': JSON_CT,
  });
  const orderOpts = () => ({
    body: orderBody,
    headers: orderHeaders,
    beforeRetry: () => { readCart(sess, 'cart-reread-order-expiry'); },
  });

  let order = call(sess, 'order-create', 'POST', '/v2/orders', orderOpts());
  if (order.status === 412) {
    if (!pass('order precondition re-read succeeded', readCart(sess, 'cart-reread-order-412'))) {
      return false;
    }
    order = call(sess, 'order-create-retry', 'POST', '/v2/orders', orderOpts());
  }
  const oj = json(order);
  if (!pass('order accepted with 201 and accepted=true',
    order.status === 201 && oj !== null && oj.accepted === true)) {
    return false;
  }
  return pass('order id returned', oj.id !== undefined && oj.id !== null);
}

export default function () {
  const username = 'bench-' + (((__VU - 1) % 16) + 1);
  const sess = newSession(username);
  journeyCommitted.add(runJourney(sess));
}
