"""Locust 2.47 locustfile: public shop ETag/If-Match cart update with one scheduled 412 conflict."""

import functools
import itertools
import os
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

HOST = os.environ["BASE_URL"].rstrip("/")
if urlsplit(HOST).hostname != "127.0.0.1":
    raise RuntimeError("BASE_URL must target 127.0.0.1 only")

PASSWORD = "bench"
USERS = 2
ITERATIONS = 2
QUANTITY = 2
CATALOG_MAX_PAGES = 3
SPAWN_RATE = 2
MAX_RUN_SECONDS = 900
RECOVERABLE_ERRORS = ("expired", "session")

CATALOG_PATH = "/v2/catalog"
CATALOG_PAGE_PATH = "/v2/catalog/page"
LOGIN_FORM_NAME = "/v2/login-form"
LOGIN_NAME = "/v2/login"
LOGIN_REDIRECT_NAME = "/v2/login [redirect]"
CATALOG_NAME = "/v2/catalog"
CATALOG_PAGE_NAME = "/v2/catalog/page"
CHALLENGE_FORM_NAME = "/v2/challenge-form"
CHALLENGE_POST_NAME = "/v2/challenges/[id]"
CHALLENGE_GRANT_NAME = "/v2/challenges/[id] [location]"
CART_CREATE_NAME = "/v2/carts"
CART_NAME = "/v2/carts/[id]"
CART_RECOVER_NAME = "/v2/carts/[id]/recover"
RENEW_NAME = "/v2/session/renew"
ORDER_NAME = "/v2/orders"

_VU_IDS = itertools.count()
_FINISHED_VUS = set()


# ---------------------------------------------------------------- helpers

def _resolve(ref):
    """Resolve a server-provided reference; refuse anything off the target origin."""
    url = urljoin(HOST + "/", ref)
    target, base = urlsplit(url), urlsplit(HOST)
    if target.scheme != base.scheme or target.netloc != base.netloc:
        raise ValueError("off-origin reference refused")
    return url


class _FormScanner(HTMLParser):
    """Collects login csrf inputs and challenge inputs, ignoring comments, disabled inputs and decoys."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._form_action = None
        self._csrf_hidden = None
        self._csrf_any = None
        self.challenges = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        values = {}
        disabled = False
        for key, value in attrs:
            key = (key or "").lower()
            if key == "disabled":
                disabled = True
            values.setdefault(key, value or "")
        if tag == "form":
            self._form_action = values.get("action", "")
        elif tag == "input" and not disabled:
            name = values.get("name", "")
            value = values.get("value", "")
            kind = values.get("type", "text").lower()
            if name == "csrf" and value:
                if kind == "hidden":
                    if self._csrf_hidden is None:
                        self._csrf_hidden = value
                elif self._csrf_any is None:
                    self._csrf_any = value
            elif name == "challenge" and value:
                self.challenges.append((self._form_action or "", value))

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form_action = None

    @property
    def csrf(self):
        return self._csrf_hidden or self._csrf_any


def _scan(html):
    scanner = _FormScanner()
    try:
        scanner.feed(html or "")
        scanner.close()
    except Exception:
        pass
    return scanner


def _challenge_of(html):
    for action, token in _scan(html).challenges:
        if "/v2/challenges/" in action:
            return action, token
    return None


def _as_json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def _run_check(check, resp, data):
    try:
        return bool(check(resp, data))
    except Exception:
        return False


class _Sample:
    __slots__ = ("status", "data", "resp", "err", "ok")

    def __init__(self, status, data, resp, err, ok):
        self.status = status
        self.data = data
        self.resp = resp
        self.err = err
        self.ok = ok


def _token_from(resp, data):
    if isinstance(data, dict):
        token = data.get("csrf")
        if isinstance(token, str) and token:
            return token
    return _scan(resp.text).csrf


def _has_token(resp, data):
    return _token_from(resp, data) is not None


def _login_form_ok(resp, data):
    return _scan(resp.text).csrf is not None


def _login_post_ok(resp, data):
    if resp.status_code == 302:
