import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
if (BASE !== 'http://127.0.0.1:8000') {
  throw new Error('target refused: only http://127.0.0.1:8000 is permitted, got ' + BASE);
}

const PASSWORD = 'bench';
const ORDER_QTY = 2;
const MAX_FRESH_LOGINS = 1;
const MAX_SCHEDULED_RETRIES = 4;
const POLL_LIMIT = 5;
const POLL_GAP_MS = 50;
const CATALOG_PAGE_LIMIT = 3;
const RUN_SEED = __ENV.RUN_SEED ||
  (Date.now().toString(36) + '-' + Math.floor(Math.random() * 1e9).toString(36));

const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    expiry_journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
    business_failure: ['rate==0'],
  },
};

// ---------- generic helpers ----------

function must(cond, label) {
  const ok = check(cond ? true : false, { [label]: (v) => v === true });
  if (!ok) {
    throw new Error('journey aborted: ' + label);
  }
}

function withHeaders(base, extra) {
  const out = {};
  for (const k in base) {
    out[k] = base[k];
  }
  if (extra) {
    for (const k2 in extra) {
      out[k2] = extra[k2];
    }
  }
  return out;
}

function paramsPlain() {
  return { redirects: 0 };
}

function paramsJson() {
  return { headers: { 'Content-Type': 'application/json' }, redirects: 0 };
}

function paramsAuth(st, extra) {
  return {
    headers: withHeaders(
      { 'Content-Type': 'application/json', 'X-CSRF-Token': st.csrf },
      extra
    ),
    redirects: 0,
  };
}

function fakeRes(status, body) {
  return { status: status, body: body || '', headers: {} };
}

function parseBody(res) {
  if (!res || typeof res.body !== 'string') {
    return null;
  }
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function hdr(res, name) {
  if (!res || !res.headers) {
    return null;
  }
  const want = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === want) {
      return res.headers[k];
    }
  }
  return null;
}

function absUrl(u) {
  if (/^https?:\/\//i.test(u)) {
    if (u === BASE || u.indexOf(BASE + '/') === 0) {
      return u;
    }
    throw new Error('refusing non-target origin: ' + u);
  }
  let p = u;
  if (p.charAt(0) !== '/') {
    p = '/' + p;
  }
  return BASE + p;
}

function absorbCsrf(st, body) {
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    st.csrf = body.csrf;
  }
}

function expiryKind(res) {
  if (!res || res.status !== 401) {
    return null;
  }
  const b = parseBody(res);
  const e = b ? b.error : null;
  if (e === 'expired') {
    return 'expired';
  }
  if (e === 'session') {
    return 'session';
  }
  return 'denied';
}

function isScheduled429(res) {
  if (!res || res.status !== 429) {
    return false;
  }
  const ra = String(hdr(res, 'Retry-After') || '').trim().toLowerCase().replace(/s$/, '');
  return ra === '1';
}

function accountFor(vu) {
  return 'bench-' + (((vu - 1) % 16) + 1);
}

function newState(user, iter) {
  return {
    user: user,
    csrf: null,
    cartId: null,
    etag: null,
    idemKey: null,
    reservationId: null,
    freshLogins: 0,
    recoveries: 0,
    carts: 0,
    orders: 0,
    seed: RUN_SEED + '-' + user + '-' + iter,
  };
}

// ---------- HTML parsing (tolerant of attribute/layout variants and decoys) ----------

function decodeEntities(s) {
  return s
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function stripNoise(html) {
  return String(html || '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<script\b[\s\S]*?<\/script\s*>/gi, '')
    .replace(/<style\b[\s\S]*?<\/style\s*>/gi, '')
    .replace(/<template\b[\s\S]*?<\/template\s*>/gi, '');
}

function parseAttrs(tag) {
  const attrs = {};
  const inner = tag.replace(/^<\s*[a-zA-Z][a-zA-Z0-9:-]*/, '').replace(/\/?>$/, '');
  const re = /([^\s"'<>\/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let m;
  while ((m = re.exec(inner)) !== null) {
    const key = m[1].toLowerCase();
    if (Object.prototype.hasOwnProperty.call(attrs, key)) {
      continue;
    }
    let val = '';
    if (m[2] !== undefined) {
      val = m[2];
    } else if (m[3] !== undefined) {
      val = m[3];
    } else if (m[4] !== undefined) {
      val = m[4];
    }
    attrs[key] = decodeEntities(val);
  }
  return attrs;
}

function findInputValue(html, name) {
  const clean = stripNoise(html);
  const tags = clean.match(/<input\b[^>]*>/gi) || [];
  let fallback = null;
  for (let i = 0; i < tags.length; i++) {
    const a = parseAttrs(tags[i]);
    if (a.name !== name) {
      continue;
    }
    if (Object.prototype.hasOwnProperty.call(a, 'disabled')) {
      continue;
    }
    if (!a.value) {
      continue;
    }
    if (String(a.type || '').toLowerCase() === 'hidden') {
      return a.value;
    }
    if (fallback === null) {
      fallback = a.value;
    }
  }
  return fallback;
}

function parseChallengeForm(html) {
  const clean = stripNoise(html);
  const forms = clean.match(/<form\b[^>]*>/gi) || [];
  for (let i = 0; i < forms.length; i++) {
    const a = parseAttrs(forms[i]);
    const action = a.action || '';
    if (!/\/v2\/challenges\/[^\/?#\s]+/.test(action)) {
      continue;
    }
    const start = clean.indexOf(forms[i]);
    const endIdx = clean.toLowerCase().indexOf('</form', start);
    const inner = clean.slice(start, endIdx > start ? endIdx : clean.length);
    const challenge = findInputValue(inner, 'challenge');
    if (challenge) {
      return { action: action, challenge: challenge };
    }
  }
  return null;
}

// ---------- session lifecycle ----------

function login(st) {
  const form = http.get(absUrl('/v2/login-form'), paramsPlain());
  must(form.status === 200, 'login form served');
  const formToken = findInputValue(form.body, 'csrf');
  must(!!formToken, 'login form csrf input found');

  const res = http.post(
    absUrl('/v2/login'),
    JSON.stringify({ username: st.user, password: PASSWORD, csrf: formToken }),
    paramsJson()
  );

  let body = null;
  if (res.status === 302) {
    const loc = hdr(res, 'Location');
    must(!!loc, 'login 302 carries Location');
    // GET the dynamic Location exactly once.
    const follow = http.get(absUrl(loc), paramsPlain());
    body = parseBody(follow);
    if (!body || !body.csrf) {
      body = parseBody(res);
    }
  } else {
    must(res.status === 200 || res.status === 201, 'login accepted');
    body = parseBody(res);
  }
  must(!!(body && typeof body.csrf === 'string' && body.csrf.length > 0), 'login returned csrf');
  st.csrf = body.csrf;
}

function reauthenticate(st) {
  must(st.freshLogins < MAX_FRESH_LOGINS, 'fresh login within reauthentication bound');
  st.freshLogins += 1;
  login(st);
}

function renewSession(st) {
  const res = http.post(absUrl('/v2/session/renew'), '{}', paramsAuth(st));
  if (res.status >= 200 && res.status < 300) {
    absorbCsrf(st, parseBody(res));
    return true;
  }
  must(expiryKind(res) !== 'denied', 'renew not denied (denied is not expiry)');
  return false;
}

function recoverCart(st) {
  const res = http.post(absUrl('/v2/carts/' + st.cartId + '/recover'), '{}', paramsAuth(st));
  must(res.status >= 200 && res.status < 300, 'cart recovered after session recovery');
  absorbCsrf(st, parseBody(res));
  const read = http.get(absUrl('/v2/carts/' + st.cartId), paramsPlain());
  must(read.status === 200, 'cart re-read after recovery');
  const e = hdr(read, 'ETag');
  must(!!e, 'cart ETag after recovery');
  st.etag = e;
}

function recoverSession(st, kind) {
  let renewed = false;
  if (kind === 'expired') {
    renewed = renewSession(st);
  }
  // Revoked sessions go straight to a fresh form/login.
  if (!renewed) {
    reauthenticate(st);
  }
  if (st.cartId !== null) {
    recoverCart(st);
  }
}

// Runs fn once; on expired/revoked session, recovers and retries fn exactly once.
// Denied (non-expiry) 401s are returned to the caller for assertion failure.
function withRecovery(st, op, fn) {
  const first = fn();
  const kind = expiryKind(first);
  if (kind !== 'expired' && kind !== 'session') {
    return first;
  }
  check(first, { [op + ': expiry recognized as ' + kind]: (r) => expiryKind(r) === kind });
  st.recoveries += 1;
  recoverSession(st, kind);
  return fn();
}

// ---------- business steps ----------

function recordBusiness(res) {
  const kind = expiryKind(res);
  const expectedExpiry = kind === 'expired' || kind === 'session';
  const ok = res.status === 200 && (parseBody(res) || {}).ok === true;
  const unexpected = !(ok || expectedExpiry || isScheduled429(res));
  businessFailure.add(unexpected);
}

function workRaw(st) {
  const res = http.post(absUrl('/v2/work'), '{}', paramsAuth(st));
  recordBusiness(res);
  if (res.status >= 200 && res.status < 300) {
    absorbCsrf(st, parseBody(res));
  }
  return res;
}

function doWork(st) {
  let retries = 0;
  for (;;) {
    const res = withRecovery(st, 'work', () => workRaw(st));
    if (isScheduled429(res) && retries < MAX_SCHEDULED_RETRIES) {
      retries += 1;
      sleep(1);
      continue;
    }
    must(res.status === 200 && (parseBody(res) || {}).ok === true, 'work returned ok:true');
    return;
  }
}

function pickVariant(st) {
  let path = '/v2/catalog';
  for (let page = 0; page < CATALOG_PAGE_LIMIT && path; page++) {
    const res = withRecovery(st, 'catalog', () => http.get(absUrl(path), paramsPlain()));
    must(res.status === 200, 'catalog page served');
    const b = parseBody(res);
    must(!!b, 'catalog page is JSON');
    const products = collectProducts(b);
    for (let i = 0; i < products.length; i++) {
      const p = products[i];
      const variants = (p && p.variants) || [];
      for (let j = 0; j < variants.length; j++) {
        if (variants[j] && variants[j].in_stock === true) {
          return { product_id: p.id, variant_id: variants[j].id };
        }
      }
    }
    path = (typeof b.next === 'string' && b.next.length > 0) ? b.next : null;
  }
  must(false, 'in-stock variant found within catalog page limit');
  return null;
}

function collectProducts(b) {
  const d = b.data || {};
  if (Array.isArray(d.products)) {
    return d.products;
  }
  if (d.product && typeof d.product === 'object') {
    return [d.product];
  }
  if (b.product && typeof b.product === 'object') {
    return [b.product];
  }
  if (Array.isArray(b.products)) {
    return b.products;
  }
  return [];
}

// Fetches a grant: challenge-form -> POST action -> 302 -> GET Location once.
// Returns the last response in the chain (401s are surfaced for recovery).
function obtainGrant(st) {
  const form = http.get(absUrl('/v2/challenge-form'), paramsPlain());
  if (form.status !== 200) {
    return form;
  }
  const ch = parseChallengeForm(form.body);
  if (!ch) {
    return fakeRes(0, '');
  }
  const post = http.post(
    absUrl(ch.action),
    JSON.stringify({ challenge: ch.challenge }),
    paramsAuth(st)
  );
  if (post.status !== 302) {
    return post;
  }
  const loc = hdr(post, 'Location');
  if (!loc) {
    return fakeRes(0, '');
  }
  return http.get(absUrl(loc), paramsPlain());
}

function createCartAttempt(st, pick) {
  const grantRes = obtainGrant(st);
  if (grantRes.status !== 200) {
    return grantRes;
  }
  const g = parseBody(grantRes);
  if (!g || g.grant_id === undefined || g.grant_id === null) {
    return fakeRes(0, '');
  }
  absorbCsrf(st, g);
  return http.post(
    absUrl('/v2/carts'),
    JSON.stringify({
      product_id: pick.product_id,
      variant_id: pick.variant_id,
      grant_id: g.grant_id,
    }),
    paramsAuth(st)
  );
}

function createCart(st, pick) {
  const res = withRecovery(st, 'cart-create', () => createCartAttempt(st, pick));
  must(res.status === 201, 'cart created with 201');
  const b = parseBody(res);
  must(!!(b && b.id !== undefined && b.id !== null), 'cart id returned');
  st.cartId = String(b.id);
  st.carts += 1;
  absorbCsrf(st, b);
  const e = hdr(res, 'ETag');
  must(!!e, 'cart ETag returned');
  st.etag = e;
  st.idemKey = 'order-' + st.cartId + '-' + st.seed;
}

function patchRaw(st, qty) {
  return http.patch(
    absUrl('/v2/carts/' + st.cartId),
    JSON.stringify({ quantity: qty }),
    paramsAuth(st, { 'If-Match': st.etag })
  );
}

function getCartRaw(st) {
  return http.get(absUrl('/v2/carts/' + st.cartId), paramsPlain());
}

function patchQuantity(st, qty) {
  let res = withRecovery(st, 'cart-patch', () => patchRaw(st, qty));
  if (res.status === 412) {
    const reread = withRecovery(st, 'cart-reread', () => getCartRaw(st));
    must(reread.status === 200, 'cart re-read after 412');
    const e = hdr(reread, 'ETag');
    must(!!e, 'cart ETag after 412 re-read');
    st.etag = e;
    res = withRecovery(st, 'cart-patch-retry', () => patchRaw(st, qty));
  }
  must(res.status === 200 || res.status === 204, 'cart quantity patched');
  absorbCsrf(st, parseBody(res));
  const newEtag = hdr(res, 'ETag');
  if (newEtag) {
    st.etag = newEtag;
  }
}

function pollRaw(url, budget) {
  if (budget.left <= 0) {
    throw new Error('reservation poll budget exhausted');
  }
  if (budget.last > 0) {
    const wait = POLL_GAP_MS - (Date.now() - budget.last);
    if (wait > 0) {
      sleep(wait / 1000);
    }
  }
  budget.left -= 1;
  budget.last = Date.now();
  return http.get(url, paramsPlain());
}

function reserve(st) {
  const res = withRecovery(st, 'reservation-create', () =>
    http.post(
      absUrl('/v2/reservations'),
      JSON.stringify({ cart_id: st.cartId }),
      paramsAuth(st)
    )
  );
  must(res.status === 202, 'reservation accepted with 202');
  const rb = parseBody(res);
  absorbCsrf(st, rb);
  must(!!(rb && typeof rb.status_url === 'string' && rb.status_url.length > 0), 'reservation status_url returned');
  const statusUrl = absUrl(rb.status_url);

  const budget = { left: POLL_LIMIT, last: 0 };
  for (;;) {
    must(budget.left > 0, 'reservation ready within poll limit');
    const pr = withRecovery(st, 'reservation-poll', () => pollRaw(statusUrl, budget));
    must(pr.status === 200, 'reservation poll returned 200');
    const pb = parseBody(pr) || {};
    if (pb.status === 'ready') {
      must(pb.reservation_id !== undefined && pb.reservation_id !== null, 'ready reservation carries reservation_id');
      st.reservationId = pb.reservation_id;
      return;
    }
    must(pb.status !== 'failed', 'reservation not failed');
  }
}

function checkout(st) {
  const read = withRecovery(st, 'cart-read-before-order', () => getCartRaw(st));
  must(read.status === 200, 'cart re-read before checkout');
  const e = hdr(read, 'ETag');
  must(!!e, 'cart ETag before checkout');
  st.etag = e;

  must(st.reservationId !== null, 'checkout reached only with ready reservation');

  const res = withRecovery(st, 'order', () =>
    http.post(
      absUrl('/v2/orders'),
      JSON.stringify({ cart_id: st.cartId, reservation_id: st.reservationId }),
      paramsAuth(st, { 'Idempotency-Key': st.idemKey, 'If-Match': st.etag })
    )
  );
  must(res.status === 201, 'order created with 201');
  const ob = parseBody(res);
  must(!!(ob && ob.accepted === true && ob.id !== undefined && ob.id !== null), 'order accepted (not accepted:false)');
  st.orders += 1;
  absorbCsrf(st, ob);
}

// ---------- journey ----------

export default function () {
  http.cookieJar().clear(BASE);

  const st = newState(accountFor(__VU), __ITER);

  login(st);
  doWork(st);
  const pick = pickVariant(st);
  createCart(st, pick);
  patchQuantity(st, ORDER_QTY);
  reserve(st);
  checkout(st);

  must(st.orders === 1, 'exactly one committed order per journey');
  must(st.carts === 1, 'exactly one cart per journey');
  must(st.freshLogins <= MAX_FRESH_LOGINS, 'reauthentication bounded');
}
