from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, StopUser, constant, task

_BASE = os.environ["BASE_URL"].rstrip("/")
_BASE_PARTS = urlsplit(_BASE)
if _BASE_PARTS.scheme != "http" or _BASE_PARTS.hostname != "127.0.0.1":
    raise RuntimeError("BASE_URL must target http://127.0.0.1")
_ORIGIN = (_BASE_PARTS.scheme, _BASE_PARTS.netloc)

PASSWORD = "bench"
ACCOUNTS = tuple(["bench-%d" % i for i in range(1, 17)] + ["bench"])
USERS = 2
SPAWN_RATE = 2
ITERATIONS = 2
MAX_RUN_SECONDS = 900
MAX_REAUTHS_PER_JOURNEY = 2
MAX_CATALOG_PAGES = 3
MAX_RESERVATION_POLLS = 5
RESERVATION_POLL_GAP = 0.05
QUANTITY = 1

_ACCOUNT_SEQ = itertools.count()
_EXPIRY_ERRORS = ("expired", "session")
_SKIP_TAGS = ("textarea", "template", "noscript", "title")
_CHALLENGE_ACTION = re.compile(r"^(?:https?://[^/\s]+)?/v2/challenges/[^/?#\s\"'<>]+$")


class JourneyError(Exception):
    """Ends the current journey. The failing sample has already been marked."""


class ExpiredError(Exception):
    """Expected 401 expiry (error=expired|session). Triggers one bounded recovery per operation."""

    def __init__(self, kind):
        super().__init__(kind)
        self.kind = kind


class _FormScanner(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.inputs = []  # (input attrs, enclosing form or None)
        self._form = None
        self._skip = 0

    def handle_starttag(self, tag, attrs):
        if tag in _SKIP_TAGS:
            self._skip += 1
            return
        if self._skip:
            return
        attr = {}
        for key, value in attrs:
            attr.setdefault((key or "").lower(), value if value is not None else "")
        if tag == "form":
            self._form = {"attrs": attr, "inputs": []}
            self.forms.append(self._form)
        elif tag == "input":
            self.inputs.append((attr, self._form))
            if self._form is not None:
                self._form["inputs"].append(attr)

    def handle_endtag(self, tag):
        if tag in _SKIP_TAGS:
            self._skip = max(0, self._skip - 1)
            return
        if not self._skip and tag == "form":
            self._form = None


def _scan(text):
    scanner = _FormScanner()
    scanner.feed(text or "")
    scanner.close()
    return scanner


def _is_hidden_csrf(attr):
    return (
        attr.get("name") == "csrf"
        and "disabled" not in attr
        and attr.get("type", "hidden").strip().lower() == "hidden"
        and attr.get("value", "") != ""
    )


def _login_csrf(text):
    fallback = None
    for attr, form in _scan(text).inputs:
        if not _is_hidden_csrf(attr):
            continue
        action = form["attrs"].get("action", "") if form else ""
        if "login" in action.lower():
            return attr["value"]
        if fallback is None:
            fallback = attr["value"]
    return fallback


def _challenge_form(text):
    for form in _scan(text).forms:
        action = form["attrs"].get("action", "").strip()
        if not _CHALLENGE_ACTION.match(action):
            continue
        for attr in form["inputs"]:
            if attr.get("name") == "challenge" and "disabled" not in attr and attr.get("value", ""):
                return action, attr["value"]
    return None, None


def _safe_json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def _resolve(target):
