            return
        attr = {}
        for key, value in attrs:
            attr.setdefault((key or "").lower(), value if value is not None else "")
        if tag == "form":
            self._form = {"attrs": attr, "inputs": []}
            self.forms.append(self._form)
        elif tag == "input":
            self.inputs.append((attr, self._form))
            if self._form is not None:
                self._form["inputs"].append(attr)

    def handle_endtag(self, tag):
        if tag in _SKIP_TAGS:
            self._skip = max(0, self._skip - 1)
            return
        if not self._skip and tag == "form":
            self._form = None


