// k6 1.0.0 reservation journey for the public shop protocol.
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const ORIGIN = 'http://127.0.0.1:8000';
const BASE = (__ENV.BASE_URL || ORIGIN).replace(/\/+$/, '');
if (BASE !== ORIGIN) {
  throw new Error('target is restricted to ' + ORIGIN + ', got ' + BASE);
}

const PASSWORD = 'bench';
const ACCOUNTS = [];
for (let i = 1; i <= 16; i++) ACCOUNTS.push('bench-' + i);
ACCOUNTS.push('bench');

const PROFILE = Object.assign(
  { job_polls: 2, poll_interval: 0.02, html_layout: 0, reverse_catalog: false, job_fails: false },
  JSON.parse(__ENV.PROFILE || '{}')
);

const MAX_POLLS = 5;
// Protocol floor is 50 ms between status polls; a shorter profile interval is raised to that floor.
const POLL_GAP_S = Math.max(0.05, Number(PROFILE.poll_interval) || 0);

const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    reservation_journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
  },
};

const JSON_HDR = { 'Content-Type': 'application/json' };

function assertThat(name, cond) {
  const ok = !!cond;
  check(true, { [name]: () => ok });
  return ok;
}

function abs(u) {
  if (typeof u !== 'string' || u.length === 0) throw new Error('missing URL');
  if (/^https?:\/\//i.test(u)) {
    if (u === ORIGIN || u.indexOf(ORIGIN + '/') === 0) return u;
    throw new Error('off-target URL refused');
  }
  if (u.charAt(0) !== '/') throw new Error('unsupported URL form');
  return ORIGIN + u;
}

function hdr(res, name) {
  const want = name.toLowerCase();
  const h = res.headers || {};
  const keys = Object.keys(h);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return h[keys[i]];
  }
  return undefined;
}

function json(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function adopt(st, body) {
  if (body && typeof body.csrf === 'string' && body.csrf !== '') st.csrf = body.csrf;
}

function ifMatch(st) {
  return st.etag ? { 'If-Match': st.etag } : {};
}

function authHeaders(st, extra) {
  return Object.assign({ 'Content-Type': 'application/json', 'X-CSRF-Token': st.csrf }, extra || {});
}

function plain(name) {
  return { headers: {}, redirects: 0, tags: { name: name } };
}

// ---------- HTML parsing (attribute-order, quoting and decoy tolerant) ----------

function parseAttrs(s) {
  const out = Object.create(null);
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'<>=`]+)))?/g;
  let m;
  while ((m = re.exec(s)) !== null) {
    const k = m[1].toLowerCase();
    if (!(k in out)) {
      out[k] = m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] !== undefined ? m[4] : ''));
    }
  }
  return out;
}

function inputsNamed(html, name) {
  const clean = String(html || '').replace(/<!--[\s\S]*?-->/g, '');
  const out = [];
  const re = /<input\b([^>]*)>/gi;
  let m;
  while ((m = re.exec(clean)) !== null) {
    const a = parseAttrs(m[1]);
    if (a.name === name && a.disabled === undefined && a.value) out.push(a);
  }
  return out;
}

function challengeForm(html) {
  const clean = String(html || '').replace(/<!--[\s\S]*?-->/g, '');
  const re = /<form\b([^>]*)>([\s\S]*?)<\/form\s*>/gi;
  let m;
  while ((m = re.exec(clean)) !== null) {
    const a = parseAttrs(m[1]);
    if (!a.action || !/^(https?:\/\/127\.0\.0\.1:8000)?\/v2\/challenges\/[^\/?#\s]+$/.test(a.action)) continue;
    const inp = inputsNamed(m[2], 'challenge');
    if (inp.length) return { action: a.action, challenge: inp[0].value };
  }
  return null;
}

// ---------- session handling ----------

function login(st) {
  const form = http.get(ORIGIN + '/v2/login-form', plain('login-form'));
  if (!assertThat('login form served', form.status === 200)) return false;
  const csrfInputs = inputsNamed(form.body, 'csrf');
  if (!assertThat('login csrf input found', csrfInputs.length > 0)) return false;
  st.csrf = csrfInputs[0].value;

  const res = http.post(
    ORIGIN + '/v2/login',
    JSON.stringify({ username: st.username, password: PASSWORD, csrf: st.csrf }),
    { headers: JSON_HDR, redirects: 0, tags: { name: 'login' } }
  );
  adopt(st, json(res));
  if (!assertThat('login accepted', res.status === 200 || res.status === 302)) return false;

  if (res.status === 302) {
    const loc = hdr(res, 'Location');
    if (!assertThat('login redirect has Location', !!loc)) return false;
    const g = http.get(abs(loc), plain('login-redirect'));
    const gb = json(g);
    adopt(st, gb);
    if (!gb || !gb.csrf) {
      const fallback = inputsNamed(g.body, 'csrf');
      if (fallback.length) st.csrf = fallback[0].value;
    }
    if (!assertThat('login redirect followed', g.status === 200)) return false;
  }
  return assertThat('session csrf captured', !!st.csrf);
}

function renew(st) {
  const res = http.post(ORIGIN + '/v2/session/renew', '{}', {
    headers: authHeaders(st), redirects: 0, tags: { name: 'session-renew' },
  });
  if (res.status < 200 || res.status >= 300) return false;
  adopt(st, json(res));
  return true;
}

function recoverCart(st) {
  const res = http.post(ORIGIN + '/v2/carts/' + st.cartId + '/recover', '{}', {
    headers: authHeaders(st), redirects: 0, tags: { name: 'cart-recover' },
  });
  if (res.status < 200 || res.status >= 300) return false;
  adopt(st, json(res));
  const e = hdr(res, 'ETag');
  if (e) st.etag = e;
  return true;
}

function errorKind(res) {
  const b = json(res);
  return b && typeof b.error === 'string' ? b.error : '';
}

// Runs one authenticated operation. At most one recovery and one retry per operation.
// error=denied (or unknown) is returned unchanged so the assertion fails.
function authOp(st, doReq) {
  const first = doReq();
  if (first.status !== 401) return first;
  const kind = errorKind(first);
  if (kind !== 'expired' && kind !== 'session') return first;

  let recovered;
  if (kind === 'expired') {
    recovered = renew(st);
  } else {
    recovered = renew(st) || login(st);
  }
  if (recovered && st.cartId) recovered = recoverCart(st);
  if (!recovered) return first;
  return doReq();
}

// ---------- business work (metric source) ----------

function workUnexpected(res) {
  const b = json(res);
  if (res.status === 200) return !(b && b.ok === true);
  if (res.status === 429) {
    return !(hdr(res, 'Retry-After') !== undefined || (b && b.error === 'scheduled'));
  }
  if (res.status === 401) return !(b && (b.error === 'expired' || b.error === 'session'));
  return true;
}

function rawWork(st) {
  const res = http.post(ORIGIN + '/v2/work', '{}', {
    headers: authHeaders(st), redirects: 0, tags: { name: 'work' },
  });
  businessFailure.add(workUnexpected(res));
  return res;
}

function retryAfterSeconds(res) {
  const v = parseFloat(String(hdr(res, 'Retry-After') || '1').replace(/s$/i, ''));
  return isNaN(v) || v < 0 ? 1 : v;
}

function work(st) {
  let res = authOp(st, () => rawWork(st));
  for (let retries = 0; res.status === 429 && retries < 4; retries++) {
    sleep(retryAfterSeconds(res));
    res = authOp(st, () => rawWork(st));
  }
  const b = json(res);
  return assertThat('work ok', res.status === 200 && !!b && b.ok === true);
}

// ---------- catalog ----------

function inStockVariant(product) {
  const vs = (product && product.variants) || [];
  for (let i = 0; i < vs.length; i++) {
    if (vs[i] && vs[i].in_stock === true) return vs[i];
  }
  return null;
}

function findPurchasable() {
  const res = http.get(ORIGIN + '/v2/catalog', plain('catalog'));
  if (!assertThat('catalog served', res.status === 200)) return null;
  const b = json(res);
  let products = (b && b.data && b.data.products) || [];
  if (PROFILE.reverse_catalog) products = products.slice().reverse();
  for (let i = 0; i < products.length; i++) {
    const v = inStockVariant(products[i]);
    if (v) return { product: products[i], variant: v };
  }

  let url = '/v2/catalog/page';
  for (let page = 0; page < 3 && url; page++) {
    const r = http.get(abs(url), plain('catalog-page'));
    if (!assertThat('catalog page served', r.status === 200)) return null;
    const pb = json(r);
    if (!pb) return null;
    const p = pb.product || (pb.data && pb.data.products && pb.data.products[0]);
    const v = inStockVariant(p);
    if (v) return { product: p, variant: v };
    url = pb.next || null;
  }
  return null;
}

// ---------- challenge / grant ----------

function challenge(st) {
  const form = http.get(ORIGIN + '/v2/challenge-form', plain('challenge-form'));
  if (!assertThat('challenge form served', form.status === 200)) return null;
  const cf = challengeForm(form.body);
  if (!assertThat('challenge form has action and challenge', !!cf)) return null;

  const res = authOp(st, () => http.post(
    abs(cf.action),
    JSON.stringify({ challenge: cf.challenge }),
    { headers: authHeaders(st), redirects: 0, tags: { name: 'challenge' } }
  ));
  if (!assertThat('challenge redirects 302', res.status === 302)) return null;
  const loc = hdr(res, 'Location');
  if (!assertThat('challenge Location present', !!loc)) return null;

  const g = http.get(abs(loc), plain('challenge-grant'));
  const b = json(g);
  adopt(st, b);
  if (!assertThat('grant issued', g.status === 200 && !!b && !!b.grant_id)) return null;
  return b.grant_id;
}

// ---------- cart ----------

function createCart(st, pick, grant) {
  const payload = { product_id: pick.product.id, variant_id: pick.variant.id };
  if (grant) payload.grant_id = grant;
  const body = JSON.stringify(payload);
  const res = authOp(st, () => http.post(ORIGIN + '/v2/carts', body, {
    headers: authHeaders(st), redirects: 0, tags: { name: 'cart-create' },
  }));
  const b = json(res);
  if (!assertThat('cart created 201 with id', res.status === 201 && !!b && b.id !== undefined)) return false;
  st.cartId = b.id;
  adopt(st, b);
  st.etag = hdr(res, 'ETag') || st.etag;
  return true;
}

function refreshCart(st) {
  const res = authOp(st, () => http.get(ORIGIN + '/v2/carts/' + st.cartId, plain('cart-read')));
  const e = hdr(res, 'ETag');
  if (res.status === 200 && e) st.etag = e;
  return assertThat('cart re-read with ETag', res.status === 200 && !!e);
}

function setQuantity(st, qty) {
  const body = JSON.stringify({ quantity: qty });
  const send = () => http.request('PATCH', ORIGIN + '/v2/carts/' + st.cartId, body, {
    headers: authHeaders(st, ifMatch(st)), redirects: 0, tags: { name: 'cart-patch' },
  });
  let res = authOp(st, send);
  if (res.status === 412) {
    if (!refreshCart(st)) return false;
    res = authOp(st, send);
  }
  if (!assertThat('cart patched 200', res.status === 200)) return false;
  const e = hdr(res, 'ETag');
  if (e) st.etag = e;
  adopt(st, json(res));
  return true;
}

// ---------- reservation ----------

function requestReservation(st) {
  const res = authOp(st, () => http.post(
    ORIGIN + '/v2/reservations',
    JSON.stringify({ cart_id: st.cartId }),
    { headers: authHeaders(st), redirects: 0, tags: { name: 'reservation' } }
  ));
  const b = json(res);
  adopt(st, b);
  if (!assertThat('reservation job accepted 202', res.status === 202 && !!b && typeof b.status_url === 'string')) {
    return null;
  }
  const url = abs(b.status_url);
  const jobId = b.job_id !== undefined ? b.job_id : b.id;
  assertThat('status URL correlates with job id', jobId === undefined || url.indexOf(String(jobId)) !== -1);
  return url;
}

function pollJob(url) {
  let polls = 0;
  while (polls < MAX_POLLS) {
    if (polls > 0) sleep(POLL_GAP_S);
    polls++;
    const res = http.get(url, plain('job-status'));
    const b = json(res);
    if (!assertThat('job status readable', (res.status === 200 || res.status === 202) && !!b)) {
      return { state: 'error', polls: polls };
    }
    if (b.status === 'ready') return { state: 'ready', polls: polls, reservationId: b.reservation_id };
    if (b.status === 'failed') return { state: 'failed', polls: polls };
    if (b.status !== 'pending') return { state: 'error', polls: polls };
  }
  return { state: 'timeout', polls: polls };
}

// ---------- checkout ----------

function checkout(st, reservationId) {
  const key = 'order-' + String(st.cartId);
  const body = JSON.stringify({ cart_id: st.cartId, reservation_id: reservationId });
  const res = authOp(st, () => http.post(ORIGIN + '/v2/orders', body, {
    headers: authHeaders(st, Object.assign({ 'Idempotency-Key': key }, ifMatch(st))),
    redirects: 0,
    tags: { name: 'order' },
  }));
  const b = json(res);
  adopt(st, b);
  return assertThat(
    'order accepted 201',
    res.status === 201 && !!b && b.accepted === true && b.id !== undefined
  );
}

// ---------- journey ----------

function journey(username) {
  const st = { username: username, csrf: '', cartId: null, etag: '' };

  if (!login(st)) return;
  work(st);

  const pick = findPurchasable();
  if (!assertThat('purchasable in-stock variant found', !!pick)) return;

  // Challenge grants expire after 2 s, so obtain it immediately before cart creation.
  const grant = challenge(st);
  if (!grant) return;

  if (!createCart(st, pick, grant)) return;
  if (!setQuantity(st, 1)) return;

  const statusUrl = requestReservation(st);
  if (!statusUrl) return;

  const job = pollJob(statusUrl);
  assertThat('polls within limit', job.polls <= MAX_POLLS);
  assertThat('job ready', job.state === 'ready');

  // Only a ready job with a reservation_id may reach checkout.
  if (job.state !== 'ready' || !assertThat('ready job carries reservation_id', !!job.reservationId)) return;

  if (!refreshCart(st)) return;
  checkout(st, job.reservationId);
}

export default function () {
  http.cookieJar().clear(ORIGIN);
  const username = ACCOUNTS[(__VU - 1) % ACCOUNTS.length];
  try {
    journey(username);
  } catch (e) {
    assertThat('journey completed without exception', false);
  }
}
