import json
import os
import time
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, StopUser, task

BASE_URL = os.environ["BASE_URL"].rstrip("/")
BASE = urlsplit(BASE_URL)
PASSWORD = "bench"
ACCOUNTS = [f"bench-{i}" for i in range(1, 17)] + ["bench"]
USERS = 2
ITERATIONS = 2
MAX_RUN_SECONDS = 180

JOB_POLLS = max(1, min(5, int(os.environ.get("JOB_POLLS", "2"))))
# Protocol requires polls at least 50 ms apart; the profile interval is honored as a floor too.
POLL_INTERVAL = max(0.05, float(os.environ.get("POLL_INTERVAL", "0.02")))


class _Pool:
    def __init__(self, names):
        self._names = names
        self._i = 0

    def next(self):
        name = self._names[self._i % len(self._names)]
        self._i += 1
        return name


ACCOUNT_POOL = _Pool(ACCOUNTS)


class _Fail(Exception):
    pass


class _Res:
    __slots__ = ("status", "data", "text", "headers", "msg")

    def __init__(self, status, data, text, headers, msg):
        self.status = status
        self.data = data
        self.text = text
        self.headers = headers
        self.msg = msg


class _Scan(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inputs = []
        self.forms = []
        self._tpl = 0

    def handle_starttag(self, tag, attrs):
        if tag == "template":
            self._tpl += 1
            return
        if self._tpl or tag not in ("input", "form"):
            return
        a = {k: (v or "").strip() for k, v in attrs}
        if tag == "input":
            if "disabled" in a:
                return
            self.inputs.append(a)
        else:
            self.forms.append(a)

    def handle_endtag(self, tag):
        if tag == "template" and self._tpl:
            self._tpl -= 1


def _parse(text):
    try:
        return json.loads(text)
    except Exception:
        return None


def _err(r):
    return r.data.get("error") if isinstance(r.data, dict) else None


def _auth_expired(r):
    return r.status == 401 and _err(r) in ("expired", "session")


def _resolve(raw):
    if not isinstance(raw, str) or not raw.strip():
        raise _Fail("missing URL")
    absolute = urljoin(BASE_URL + "/", raw.strip())
    parts = urlsplit(absolute)
    if parts.scheme != BASE.scheme or parts.netloc != BASE.netloc:
        raise _Fail("off-target URL refused")
    return absolute


def _csrf_from_form(html):
    scan = _Scan()
    scan.feed(html)
    scan.close()
    found = [a for a in scan.inputs if a.get("name") == "csrf" and a.get("value")]
    found.sort(key=lambda a: a.get("type", "").lower() != "hidden")
    return found[0]["value"] if found else None


def _challenge_fields(html):
    scan = _Scan()
    scan.feed(html)
    scan.close()
    action = None
    for f in scan.forms:
        raw = f.get("action", "")
        if raw and urlsplit(urljoin(BASE_URL + "/", raw)).path.startswith("/v2/challenges/"):
            action = raw
            break
    value = None
    for i in scan.inputs:
        if i.get("name") == "challenge" and i.get("value"):
            value = i["value"]
            break
    return action, value


def _products_of(d):
    if not isinstance(d, dict):
        return []
    inner = d.get("data")
    if isinstance(inner, dict) and isinstance(inner.get("products"), list):
        return inner["products"]
    if isinstance(d.get("products"), list):
        return d["products"]
    if isinstance(d.get("product"), dict):
        return [d["product"]]
    return []


def _first_in_stock(products):
    for p in products:
        if not isinstance(p, dict) or p.get("id") is None:
            continue
        for v in p.get("variants") or []:
            if isinstance(v, dict) and v.get("id") is not None and v.get("in_stock") is True:
                return p["id"], v["id"]
    return None


def _cart_check(status, d):
    return None if isinstance(d, dict) and d.get("id") not in (None, "") else "cart id missing"


def _reserve_check(status, d):
    ok = isinstance(d, dict) and isinstance(d.get("status_url"), str) and d["status_url"]
    return None if ok else "status_url missing"


def _order_check(status, d):
    ok = isinstance(d, dict) and d.get("accepted") is True and d.get("id") not in (None, "")
    return None if ok else "order not accepted"


def _job_check(job_id, last):
    def check(status, d):
        if not isinstance(d, dict):
            return "status body malformed"
        if "id" in d and str(d["id"]) != job_id:
            return "status id does not match job"
        state = d.get("status")
        if state == "ready":
            rid = d.get("reservation_id")
            return None if rid not in (None, "") else "ready without reservation_id"
        if state == "pending":
            return "job still pending after final poll" if last else None
        if state == "failed":
            return "job failed"
        return f"unknown job status {state!r}"

    return check


class ReservationShopUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        self.done = 0
        self.csrf = None
        self.cart_id = None
        self.account = None
        self._failed = False

    def _req(self, method, path, name, expect, body=None, headers=None, check=None,
             retry_auth=False, retry_412=False):
        url = _resolve(path)
        hdrs = dict(headers or {})
        if method != "GET" and self.csrf and "X-CSRF-Token" not in hdrs:
            hdrs["X-CSRF-Token"] = self.csrf
        with self.client.request(method, url, name=name, json=body, headers=hdrs,
                                 allow_redirects=False, catch_response=True) as resp:
            status = resp.status_code
            text = resp.text
            data = _parse(text)
            out_headers = resp.headers
            err = data.get("error") if isinstance(data, dict) else None
            if status in expect:
                msg = check(status, data) if check else None
            elif status == 401 and err in ("expired", "session") and retry_auth:
                msg = None
            elif status == 412 and retry_412:
                msg = None
            else:
                msg = f"{name}: unexpected HTTP {status}" + (f" error={err}" if err else "")
            if msg:
                resp.failure(msg)
                self._failed = True
            else:
                resp.success()
        if (200 <= status < 300 and isinstance(data, dict)
                and isinstance(data.get("csrf"), str) and data["csrf"]):
            self.csrf = data["csrf"]
        return _Res(status, data, text, out_headers, msg)

    def _api(self, method, path, name, expect, body=None, headers=None, etag=False, check=None):
        recovered = False
        resynced = False
        while True:
            hdrs = dict(headers or {})
            if etag:
                g = self._req("GET", f"/v2/carts/{self.cart_id}", "/v2/carts/[id]", {200},
                              retry_auth=not recovered)
                if g.status != 200:
                    if _auth_expired(g) and not recovered:
                        recovered = True
                        self._recover(_err(g))
                        continue
                    raise _Fail(f"{name}: cart read returned {g.status}")
                tag = g.headers.get("ETag")
                if not tag:
                    raise _Fail("cart ETag missing")
                hdrs["If-Match"] = tag
            r = self._req(method, path, name, expect, body=body, headers=hdrs, check=check,
                          retry_auth=not recovered,
                          retry_412=bool(etag) and not resynced)
            if r.status in expect:
                if r.msg:
                    raise _Fail(r.msg)
                return r
            if _auth_expired(r) and not recovered:
                recovered = True
                self._recover(_err(r))
                continue
            if r.status == 412 and etag and not resynced:
                resynced = True
                continue
            raise _Fail(f"{name}: HTTP {r.status}")

    def _recover(self, err):
        r = self._req("POST", "/v2/session/renew", "/v2/session/renew", {200, 201},
                      body={}, retry_auth=True)
        if r.msg:
            raise _Fail("session renew failed")
        renewed = (r.status in (200, 201) and isinstance(r.data, dict)
                   and bool(r.data.get("csrf")))
        if not renewed:
            self._login()
        if self.cart_id is not None:
            c = self._req("POST", f"/v2/carts/{self.cart_id}/recover", "/v2/carts/[id]/recover",
                          {200, 201, 204}, body={})
            if c.msg:
                raise _Fail("cart recovery failed")

    def _login(self):
        form = self._req("GET", "/v2/login-form", "/v2/login-form", {200})
        if form.msg:
            raise _Fail(form.msg)
        token = _csrf_from_form(form.text)
        if not token:
            raise _Fail("login csrf not found")
        self.csrf = token
        r = self._req("POST", "/v2/login", "/v2/login", {200, 302},
                      body={"username": self.account, "password": PASSWORD, "csrf": token})
        if r.msg:
            raise _Fail(r.msg)
        payload = r.data
        if r.status == 302:
            loc = r.headers.get("Location")
            if not loc:
                raise _Fail("login redirect without Location")
            g = self._req("GET", loc, "/v2/login/location", {200})
            if g.msg:
                raise _Fail(g.msg)
            payload = g.data
        if not isinstance(payload, dict) or not payload.get("csrf"):
            raise _Fail("login csrf missing")
        self.csrf = payload["csrf"]

    def _pick_product(self):
        r = self._api("GET", "/v2/catalog", "/v2/catalog", {200})
        hit = _first_in_stock(_products_of(r.data))
        if hit:
            return hit
        url = "/v2/catalog/page"
        for _ in range(3):
            page = self._api("GET", url, "/v2/catalog/page", {200})
            hit = _first_in_stock(_products_of(page.data))
            if hit:
                return hit
            nxt = page.data.get("next") if isinstance(page.data, dict) else None
            if not nxt:
                break
            url = nxt
        raise _Fail("no in-stock variant found")

    def _challenge(self):
        form = self._api("GET", "/v2/challenge-form", "/v2/challenge-form", {200})
        action, value = _challenge_fields(form.text)
        if not action or not value:
            raise _Fail("challenge form incomplete")
        posted = self._api("POST", action, "/v2/challenges/[id]", {302},
                           body={"challenge": value})
        location = posted.headers.get("Location")
        if not location:
            raise _Fail("challenge redirect missing")
        claim = self._api("GET", location, "/v2/challenges/[claim]", {200})
        if not isinstance(claim.data, dict) or not claim.data.get("grant_id"):
            raise _Fail("grant_id missing")
        return claim.data["grant_id"]

    def _create_cart(self, product_id, variant_id, grant_id):
        r = self._api("POST", "/v2/carts", "/v2/carts", {201},
                      body={"product_id": product_id, "variant_id": variant_id,
                            "grant_id": grant_id},
                      check=_cart_check)
        self.cart_id = r.data["id"]

    def _reserve(self):
        r = self._api("POST", "/v2/reservations", "/v2/reservations", {202},
                      body={"cart_id": self.cart_id}, check=_reserve_check)
        url = _resolve(r.data["status_url"])
        path = urlsplit(url).path
        job_id = str(r.data.get("job_id") or r.data.get("id")
                     or path.rstrip("/").rsplit("/", 1)[-1])
        if not job_id or job_id not in path:
            raise _Fail("status URL not correlated with job id")
        return url, job_id

    def _poll_job(self, status_url, job_id):
        polls = 0
        recovered = False
        while True:
            if polls:
                time.sleep(POLL_INTERVAL)
            polls += 1
            last = polls >= JOB_POLLS
            can_retry = not recovered and not last
            r = self._req("GET", status_url, "/v2/reservations/[status]", {200},
                          check=_job_check(job_id, last), retry_auth=can_retry)
            if r.msg is None and _auth_expired(r):
