import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final String BASE_URL = resolveBaseUrl();

  private static final HttpProtocolBuilder PROTOCOL = http
      .baseUrl(BASE_URL)
      .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8")
      .disableFollowRedirect();

  private static final String JSON = "application/json";

  private static final String FORM_CSRF =
      "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>";

  public ModelSimulation() {
    ChainBuilder journey = journey();
    ScenarioBuilder scn = scenario("ModelSimulation")
        .feed(accounts())
        .exec(journey)
        .exec(journey);
    setUp(scn.injectOpen(atOnceUsers(2))).protocols(PROTOCOL);
  }

  // ---------- configuration helpers ----------

  private static String resolveBaseUrl() {
    String v = System.getenv("BASE_URL");
    return (v == null || v.isEmpty()) ? "http://127.0.0.1:8000" : v;
  }

  private static Iterator<Map<String, Object>> accounts() {
    List<Map<String, Object>> rows = new ArrayList<>();
