import http from 'k6/http';
import { check } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';
const FORM_CSRF_RE = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/;
const ERROR_RE = /"error"\s*:\s*"(expired|session|denied)"/;

export const options = {
  scenarios: {
    shop_flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
};

function verify(name, cond) {
  const passed = Boolean(cond);
  check(passed, { [name]: (v) => v === true });
  return passed;
}

function parseJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function header(res, name) {
  const want = name.toLowerCase();
  const h = res.headers || {};
  const keys = Object.keys(h);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) {
      return h[keys[i]];
    }
  }
  return null;
}

function formToken(html) {
  const m = FORM_CSRF_RE.exec(html || '');
  return m ? m[1] : null;
}

function errorKind(res) {
  const m = ERROR_RE.exec(res.body || '');
  return m ? m[1] : null;
}

function adoptCsrf(st, b) {
  if (b && typeof b.csrf === 'string' && b.csrf.length > 0) {
    st.csrf = b.csrf;
  }
}

function resolveLocation(loc) {
  const target = loc.indexOf('://') >= 0
    ? loc
    : BASE_URL + (loc.charAt(0) === '/' ? '' : '/') + loc;
  return target.indexOf(BASE_URL + '/') === 0 ? target : null;
}

function send(st, method, path, body, opts) {
  const headers = {};
  if (body !== undefined) {
    headers['Content-Type'] = 'application/json';
  }
  if (st.csrf) {
    headers['X-CSRF-Token'] = st.csrf;
  }
  if (opts && opts.ifMatch && st.etag) {
    headers['If-Match'] = st.etag;
  }
  if (opts && opts.idem && st.cartId) {
    headers['Idempotency-Key'] = st.cartId;
  }
  return http.request(
    method,
    `${BASE_URL}${path}`,
    body === undefined ? null : JSON.stringify(body),
    { headers: headers, redirects: 0 },
  );
}

function renew(st) {
  const res = send(st, 'POST', '/v2/session/renew', {});
  const b = parseJson(res);
  if (res.status >= 200 && res.status < 300 && b && typeof b.csrf === 'string') {
    st.csrf = b.csrf;
    return true;
  }
  return false;
}

function recoverCart(st) {
  const res = send(st, 'POST', `/v2/carts/${encodeURIComponent(st.cartId)}/recover`, {});
  if (res.status < 200 || res.status >= 300) {
    return false;
  }
  adoptCsrf(st, parseJson(res));
  const et = header(res, 'ETag');
  if (et) {
    st.etag = et;
  }
  return true;
}

function freshLogin(st) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  const token = formToken(formRes.body);
  if (!verify('login form 200 with csrf input', formRes.status === 200 && token !== null)) {
    return false;
  }

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username: st.user, password: PASSWORD, csrf: token }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 },
  );

  const loc = header(loginRes, 'Location');
  if (loc) {
    const target = resolveLocation(loc);
    if (!verify('login 302 with same-host Location', loginRes.status === 302 && target !== null)) {
      return false;
    }
    const r = http.get(target, { redirects: 0 });
    const rb = parseJson(r);
    if (!verify('location 200 with csrf', r.status === 200 && rb && typeof rb.csrf === 'string')) {
      return false;
    }
    st.csrf = rb.csrf;
    if (!st.cartId && rb.grant_id !== undefined && rb.grant_id !== null) {
      st.grant = rb.grant_id;
    }
    return true;
  }

  const lb = parseJson(loginRes);
  if (!verify('login 200 with csrf', loginRes.status === 200 && lb && typeof lb.csrf === 'string')) {
    return false;
  }
  st.csrf = lb.csrf;
  return true;
}

function relogin(st) {
  return freshLogin(st);
}

function authedCall(st, method, path, body, opts) {
  const res = send(st, method, path, body, opts);
  if (res.status !== 401) {
    return res;
  }

  const kind = errorKind(res);
  if (kind === 'expired') {
    if (!renew(st)) {
      return res;
    }
  } else if (kind === 'session') {
    if (!renew(st) && !relogin(st)) {
      return res;
    }
  } else {
    // denied or unknown 401 is not expiry: leave it to the assertion
    return res;
  }

  if (st.cartId && !recoverCart(st)) {
    return res;
  }

  // single retry of the interrupted operation
  return send(st, method, path, body, opts);
}

function pickProduct(st) {
  const res = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
  const b = parseJson(res);
  if (!verify('catalog 200 with products', res.status === 200 && b && b.data && Array.isArray(b.data.products))) {
    return false;
  }
  adoptCsrf(st, b);

  const p = b.data.products.find((x) =>
    x && Array.isArray(x.variants) && x.variants.length > 0 &&
    x.variants[0] && x.variants[0].in_stock === true
  );
  if (!verify('in-stock product with first variant found', Boolean(p) && p.id !== undefined && p.variants[0].id !== undefined)) {
    return false;
  }
  st.product = p.id;
  st.variant = p.variants[0].id;
  return true;
}

function createCart(st) {
  const body = { product_id: st.product, variant_id: st.variant };
  if (st.grant) {
    body.grant_id = st.grant;
  }
  const res = authedCall(st, 'POST', '/v2/carts', body, {});
  const b = parseJson(res);
  const ok = verify(
    'cart created 201 with cart id',
    res.status === 201 && b && typeof b.id === 'string' && b.id.indexOf('cart-') === 0,
  );
  if (!ok) {
    return false;
  }
  st.cartId = b.id;
  st.grant = null; // grant_id is passed once, to cart creation
  adoptCsrf(st, b);
  const et = header(res, 'ETag');
  if (et) {
    st.etag = et;
  }
  return true;
}

function placeOrder(st) {
  const res = authedCall(st, 'POST', '/v2/orders', { cart_id: st.cartId }, { idem: true, ifMatch: true });
  const b = parseJson(res);
  return verify(
    'order 201 with accepted true',
    res.status === 201 && b && b.accepted === true,
  );
}

export default function () {
  http.cookieJar().clear(BASE_URL);

  const st = {
    user: `bench-${__VU}`,
    csrf: null,
    etag: null,
    cartId: null,
    grant: null,
    product: null,
    variant: null,
  };

  if (!freshLogin(st)) return;
  if (!pickProduct(st)) return;
  if (!createCart(st)) return;
  placeOrder(st);
}
