import itertools
import json
import os
import re
from urllib.parse import urlsplit

from locust import HttpUser, LoadTestShape, StopUser, constant, task

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"
USERS = 2
ITERATIONS = 2                      # iterations per user (journeys)
TOTAL_JOURNEYS = USERS * ITERATIONS
TIMEOUT = (2, 3)                    # connect 2000 ms / response 3000 ms, as in the JMX
MAX_RUN_SECONDS = 900               # safety bound for the shape
AUTH_EXPIRY = ("expired", "session")

# Login form: input[name=csrf] with value, attribute-order/quoting tolerant, comments ignored
_COMMENT_RE = re.compile(r"<!--.*?-->", re.S)
_INPUT_RE = re.compile(r"<input\b[^>]*>", re.I)
_CSRF_NAME_RE = re.compile(
    r"""(?<![\w-])name\s*=\s*(?:"csrf"|'csrf'|csrf(?=[\s/>]))""", re.I
)
_VALUE_RE = re.compile(
    r"""(?<![\w-])value\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s"'>]+))""", re.I
)
_CSRF_KEY_RE = re.compile(r'"csrf"\s*:')
_CART_ID_RE = re.compile(r'"id"\s*:\s*"cart-')
_ACCEPTED_RE = re.compile(r'"accepted"\s*:\s*true')

_slots = itertools.count(1)         # virtual-user slot (threadNum equivalent)
_journeys_done = 0                  # global completed-journey counter


def _as_json(text):
    try:
        return json.loads(text)
    except (TypeError, ValueError):
        return None


def _form_token(html):
    html = _COMMENT_RE.sub("", html or "")
    for tag in _INPUT_RE.findall(html):
        if not _CSRF_NAME_RE.search(tag):
            continue
        m = _VALUE_RE.search(tag)
        if m:
            return next(g for g in m.groups() if g)
    return None


def _pick_in_stock(products):
    # JMX: first product whose variants[0].in_stock == true; product.id and variants[0].id
    for product in products:
        if not isinstance(product, dict):
            continue
        variants = product.get("variants")
        if not isinstance(variants, list) or not variants or not isinstance(variants[0], dict):
            continue
        pid = product.get("id")
        vid = variants[0].get("id")
        if variants[0].get("in_stock") is True and pid is not None and vid is not None:
            return pid, vid
    return None


def _has_csrf(resp, data):
    return isinstance(data, dict) and isinstance(data.get("csrf"), str) and bool(data["csrf"])


def _form_check(resp, data):
    return _form_token(resp.text) is not None


def _login_check(resp, data):
    if resp.status_code == 302:
        return bool(resp.headers.get("Location"))
    return bool(_CSRF_KEY_RE.search(resp.text)) and _has_csrf(resp, data)


def _catalog_check(resp, data):
    if not isinstance(data, dict) or not isinstance(data.get("data"), dict):
        return False
    products = data["data"].get("products")
    return isinstance(products, list) and _pick_in_stock(products) is not None


def _cart_check(resp, data):
    return (
        isinstance(data, dict)
        and isinstance(data.get("id"), str)
        and bool(_CART_ID_RE.search(resp.text))
    )


def _order_check(resp, data):
    return (
        isinstance(data, dict)
        and data.get("accepted") is True
        and bool(_ACCEPTED_RE.search(resp.text))
    )


def _relative(location):
    # Keep the request on the configured host; use only the path (+query) of Location.
    parts = urlsplit(location)
    path = parts.path or "/"
    if not path.startswith("/"):
        path = "/" + path
    return f"{path}?{parts.query}" if parts.query else path


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.slot = next(_slots)
        self.username = f"bench-{((self.slot - 1) % 16) + 1}"
        self.iterations_done = 0
        self._reset()

    def _reset(self):
        self.csrf = None
        self.grant = None
        self.cart_id = None
        self.etag = None

    @task
    def journey(self):
        global _journeys_done
        if (
            self.slot > USERS
            or self.iterations_done >= ITERATIONS
            or _journeys_done >= TOTAL_JOURNEYS
        ):
            raise StopUser()
        self.iterations_done += 1
        try:
            self._run_journey()
        finally:
            _journeys_done += 1

    # ----- journey -------------------------------------------------------

    def _run_journey(self):
        # JMX CookieManager clearEachIteration=true
        self.client.cookies.clear()
        self._reset()
        if not self._login():
            return
        picked = self._catalog()
        if picked is None:
            return
        if not self._create_cart(*picked):
            return
        self._create_order()

    def _login(self):
        form = self._send(
            "GET", "/v2/login-form", "login-form",
            ok=(200,), check=_form_check, auth=False,
        )
        if form["kind"] != "ok":
            return False
        token = _form_token(form["text"])

        login = self._send(
            "POST", "/v2/login", "login",
            body={"username": self.username, "password": PASSWORD, "csrf": token},
            ok=(200, 302), check=_login_check, auth=False,
        )
        if login["kind"] != "ok":
            return False

        self.grant = None
        if login["status"] == 302:
            # Redirects are not followed automatically; GET the dynamic Location exactly once.
            login = self._send(
                "GET", _relative(login["headers"]["Location"]), "login-redirect",
                ok=(200,), check=_has_csrf, auth=False,
            )
            if login["kind"] != "ok":
                return False
            self.grant = login["data"].get("grant_id")

        self.csrf = login["data"]["csrf"]
        return True

    def _catalog(self):
        res = self._call(
            "GET", "/v2/catalog", "catalog",
            ok=(200,), check=_catalog_check,
        )
        if res is None:
            return None
        return _pick_in_stock(res["data"]["data"]["products"])

    def _create_cart(self, product, variant):
        body = {"product_id": product, "variant_id": variant}
        if self.grant is not None:
            body["grant_id"] = self.grant
        res = self._call(
            "POST", "/v2/carts", "cart-create",
            body=body, ok=(201,), check=_cart_check,
        )
        self.grant = None  # grant_id is passed exactly once
        if res is None:
            return False
        self.cart_id = res["data"]["id"]
        return True

    def _create_order(self):
        # Idempotency-Key is the cart id: unique per cart, stable on retry.
        # The source plan declares quantity=2 but never sends it; no PATCH is issued.
        headers = {"Idempotency-Key": str(self.cart_id)}
        if self.etag:
            headers["If-Match"] = self.etag
        self._call(
            "POST", "/v2/orders", "order-create",
            body={"cart_id": self.cart_id}, headers=headers,
            ok=(200, 201), check=_order_check,
        )

    # ----- request plumbing ----------------------------------------------

    def _send(self, method, path, name, body=None, headers=None, ok=(200,),
              check=None, auth=True, recoverable=True):
        hdrs = dict(headers or {})
        if auth and method != "GET" and self.csrf:
            hdrs["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method, path, name=name, json=body, headers=hdrs,
            allow_redirects=False, timeout=TIMEOUT, catch_response=True,
        ) as resp:
            status = resp.status_code
            text = resp.text
            data = _as_json(text)
            err = data.get("error") if isinstance(data, dict) else None

            if auth and recoverable and status == 401 and err in AUTH_EXPIRY:
                # Expected expiry/revocation: handled by recovery, not a failure.
                resp.success()
                kind = err
            elif status in ok and (check is None or check(resp, data)):
                resp.success()
                kind = "ok"
            else:
                resp.failure(f"{name}: HTTP {status} error={err!r} expected={ok}")
                kind = "fail"

        return {
            "kind": kind,
            "status": status,
            "text": text,
            "data": data,
            "headers": resp.headers,
        }

    def _call(self, method, path, name, body=None, headers=None, ok=(200,), check=None):
        res = self._send(method, path, name, body, headers, ok, check)
        if res["kind"] in AUTH_EXPIRY:
            if not self._recover(res["kind"]):
                return None
            # Retry the interrupted operation exactly once, same payload and key.
            res = self._send(method, path, name, body, headers, ok, check, recoverable=False)
        if res["kind"] != "ok":
            return None
        self._absorb(res)
        return res

    def _absorb(self, res):
        data = res["data"]
        if isinstance(data, dict) and isinstance(data.get("csrf"), str) and data["csrf"]:
            self.csrf = data["csrf"]
        etag = res["headers"].get("ETag")
