import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const ACCOUNTS_FIXTURE = '/fixtures/accounts.json';
const POLL_LIMIT = 5;
const POLL_GAP_S = 0.06;
const CATALOG_PAGE_LIMIT = 3;

export const options = {
  scenarios: {
    m04_journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
    journey_committed: ['rate==1'],
  },
};

const journeyCommitted = new Rate('journey_committed');
const ACCOUNTS = loadAccounts(ACCOUNTS_FIXTURE);

function loadAccounts(path) {
  const rows = JSON.parse(open(path));
  if (!Array.isArray(rows) || rows.length === 0) {
    throw new Error('accounts fixture must be a non-empty array');
  }
  return rows.map(function (r, i) {
    if (!r || typeof r.username !== 'string' || r.username === '') {
      throw new Error('row ' + i + ': username');
    }
    if (typeof r.password !== 'string') {
      throw new Error('row ' + i + ': password');
    }
    if (!Number.isInteger(r.quantity) || r.quantity < 1 || r.quantity > 20) {
      throw new Error('row ' + i + ': quantity must be integer 1..20');
    }
    if (typeof r.delay !== 'number') {
      throw new Error('row ' + i + ': delay');
    }
    return { username: r.username, password: r.password, quantity: r.quantity, delay: r.delay };
  });
}

function rowForVU(vu) {
  return ACCOUNTS[(vu - 1) % ACCOUNTS.length];
}

function newState(row) {
  return {
    row: row,
    csrf: null,
    etag: null,
    cartId: null,
    cartKey: 'm04-' + __VU + '-' + __ITER + '-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10),
    grantId: null,
    reservationId: null,
    orderId: null,
  };
}

export default function () {
  const state = newState(rowForVU(__VU));
  http.cookieJar().clear(BASE_URL);
  let committed = false;
  try {
    committed = runJourney(state) && state.orderId !== null;
  } catch (err) {
    console.error('journey aborted for ' + state.row.username + ': ' + err);
    committed = false;
  }
  journeyCommitted.add(committed);
}

