  if (!freshLogin(state)) return false;

  const cand = findCandidate();
  if (!check({ cand: cand }, { 'catalog candidate in stock': (v) => v.cand !== null })) return false;

  const created = withRecovery(state, function () { return createCartOp(state, cand); });
  if (!check(created, { 'cart created 201': (r) => r.status === 201 })) return false;
  if (!check({ cart: state.cartId }, { 'cart id returned': (v) => v.cart !== null })) return false;

  const patched = withRecovery(state, function () { return patchCartOp(state, state.row.quantity); });
  if (!check(patched, {
    'cart quantity PATCH 200': (r) => r.status === 200,
    'cart quantity echoed when reported': (r) => {
      const b = jsonOf(r);
      return b === null || b.quantity === undefined || b.quantity === state.row.quantity;
    },
  })) return false;

  withRecovery(state, function () { return reserveOp(state); });
  if (!check({ reservation: state.reservationId }, {
    'reservation ready before checkout': (v) => v.reservation !== null,
  })) return false;

  const ordered = withRecovery(state, function () { return orderOp(state); });
  const accepted = check(ordered, {
    'order 201': (r) => r.status === 201,
    'order accepted true': (r) => {
      const b = jsonOf(r);
      return b !== null && b.accepted === true;
    },
    'order id returned': (r) => {
      const b = jsonOf(r);
      return b !== null && b.id !== undefined && b.id !== null && b.id !== '';
    },
    'order cart matches journey cart when reported': (r) => {
      const b = jsonOf(r);
      return b === null || b.cart_id === undefined || b.cart_id === state.cartId;
    },
    'order quantity matches row when reported': (r) => {
      const b = jsonOf(r);
      return b === null || b.quantity === undefined || b.quantity === state.row.quantity;
