// ---------- session / login ----------

function freshLogin(state) {
  const form = http.get(BASE_URL + '/v2/login-form', { redirects: 0, headers: { Accept: 'text/html' } });
  if (!check(form, { 'login form 200': (r) => r.status === 200 })) return false;

