  private static final String BASE_URL =
      System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

  private static ActionBuilder order(String name, boolean retry) {
    if (retry) {
      return http(name).post("/v2/orders")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .header("If-Match", "#{etag}")
          .header("Idempotency-Key", "#{cart}")
          .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
          .check(status().is(201))
          .check(regex("\"accepted\"\\s*:\\s*true").exists())
          .check(jsonPath("$.csrf").optional().saveAs("csrf"));
    }
    return http(name).post("/v2/orders")
        .header("Content-Type", "application/json")
        .header("X-CSRF-Token", "#{csrf}")
        .header("If-Match", "#{etag}")
        .header("Idempotency-Key", "#{cart}")
        .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
        .check(status().in(201, 401))
        .check(status().saveAs("orderStatus"))
        .check(regex("\"accepted\"\\s*:\\s*true|\"error\"\\s*:\\s*\"expired\"").exists())
        .check(jsonPath("$.csrf").optional().saveAs("csrf"));
  }

