    HttpProtocolBuilder protocol = http.baseUrl(BASE_URL)
        .acceptHeader("application/json")
        .disableFollowRedirect()
        .disableCaching();

    Iterator<Map<String, Object>> accounts = IntStream.iterate(0, i -> i + 1)
        .mapToObj(i -> {
          Map<String, Object> row = new HashMap<>();
          row.put("username", "bench-" + (i % 16 + 1));
          return row;
        })
        .iterator();

    ActionBuilder loginForm = http("login-form").get("/v2/login-form")
        .check(status().is(200))
        .check(css("input[name=csrf]", "value").saveAs("formCsrf"));

