        .exec(order("order", false))
        .doIf((Session s) -> s.getInt("orderStatus") == 401).then(renewAndRetry);

    ScenarioBuilder scn = scenario("checkout-journey")
        .feed(accounts)
        .exec(checkout);

    setUp(scn.injectOpen(constantUsersPerSec(2.0).during(Duration.ofSeconds(38))))
        .protocols(protocol)
        .assertions(global().failedRequests().percent().lte(1.0));
  }
}
