```javascript
import http from 'k6/http';
import { check } from 'k6';
import { Rate, Counter } from 'k6/metrics';

const BASE = String(__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const RATE = 2;
const MAX_VUS = 4;
const DURATION = '38s';
const MAX_CATALOG_PAGES = 3;

const unexpectedFailures = new Rate('journey_unexpected_failures');
const acceptedOrders = new Counter('checkout_orders_accepted');

// 401 (expiry/revocation/denial) and 412 (stale ETag) are handled by the journey logic,
// so they are not counted as transport-level failures here.
const EXPECTED = http.expectedStatuses({ min: 200, max: 399 }, 401, 412);

const NAME_RE = /(?:^|\s)name\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/i;
const VALUE_RE = /(?:^|\s)value\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/i;

export const options = {
  scenarios: {
    checkout_journey: {
      executor: 'constant-arrival-rate',
      exec: 'journey',
      rate: RATE,
      timeUnit: '1s',
      duration: DURATION,
      preAllocatedVUs: MAX_VUS,
      maxVUs: MAX_VUS,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    journey_unexpected_failures: ['rate<=0.01'],
    dropped_iterations: ['count==0'],
  },
};

function newState() {
  return {
    jar: new http.CookieJar(),
    user: 'bench-' + __VU,
    csrf: '',
    etag: '',
    grant: '',
    cartId: '',
    recovered: {},
  };
}

function json(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function header(res, name) {
  const headers = res.headers || {};
  const want = name.toLowerCase();
  const keys = Object.keys(headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return String(headers[keys[i]]);
  }
  return null;
}

// Only follow targets on the configured base URL; anything else is rejected.
function resolveUrl(loc) {
  if (!loc) return null;
  const s = String(loc);
  if (s.charAt(0) === '/' && s.charAt(1) !== '/') return BASE + s;
  if (s === BASE || s.indexOf(BASE + '/') === 0) return s;
  return null;
}

function attrOf(tag, re) {
  const m = re.exec(tag);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  if (m[3] !== undefined) return m[3];
  return null;
}

function formCsrf(html) {
  const clean = String(html || '').replace(/<!--[\s\S]*?-->/g, '');
  const inputs = clean.match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < inputs.length; i++) {
    if (attrOf(inputs[i], NAME_RE) !== 'csrf') continue;
    const value = attrOf(inputs[i], VALUE_RE);
    if (value) return value;
  }
  return null;
}

function errorKind(res) {
  const b = json(res);
  if (b && typeof b.error === 'string') return b.error;
  const m = /"error"\s*:\s*"(expired|session|denied)"/.exec(String(res.body || ''));
  return m ? m[1] : null;
}

function send(st, method, target, body, extra, op) {
  const url = target.charAt(0) === '/' ? BASE + target : target;
  const headers = {};
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && st.csrf) headers['X-CSRF-Token'] = st.csrf;
  const keys = Object.keys(extra || {});
  for (let i = 0; i < keys.length; i++) {
    if (extra[keys[i]]) headers[keys[i]] = extra[keys[i]];
  }
  const payload = body === undefined ? null : JSON.stringify(body);
  return http.request(method, url, payload, {
    headers: headers,
    jar: st.jar,
    redirects: 0,
    responseCallback: EXPECTED,
    tags: { op: op },
  });
}

function setCsrf(st, b) {
  if (b && typeof b.csrf === 'string' && b.csrf) st.csrf = b.csrf;
}

// Session renew: capture the fresh csrf from the response.
function renew(st) {
  const res = send(st, 'POST', '/v2/session/renew', {}, {}, 'session_renew');
  if (res.status < 200 || res.status > 299) return false;
  const b = json(res);
  if (!b || typeof b.csrf !== 'string' || !b.csrf) return false;
  st.csrf = b.csrf;
  return true;
}

function recoverCart(st) {
  const res = send(st, 'POST', '/v2/carts/' + encodeURIComponent(st.cartId) + '/recover', {}, {}, 'cart_recover');
  if (res.status < 200 || res.status > 299) return false;
  setCsrf(st, json(res));
  st.etag = header(res, 'ETag') || st.etag;
  return true;
}

// Fresh form + login. Login may answer 302; the dynamic Location is fetched exactly once.
function freshLogin(st) {
  const form = send(st, 'GET', '/v2/login-form', undefined, {}, 'login_form');
  if (!check(form, { 'login form 200': (r) => r.status === 200 })) return false;
  const nonce = formCsrf(form.body);
  if (!nonce) return false;
  st.csrf = nonce;

  const login = send(st, 'POST', '/v2/login', { username: st.user, password: PASSWORD, csrf: nonce }, {}, 'login');

  if (login.status === 302) {
    const next = resolveUrl(header(login, 'Location'));
    if (!next) return false;
    const landing = send(st, 'GET', next, undefined, {}, 'login_redirect');
    const lb = json(landing);
    if (!check(landing, {
      'login redirect 200 with csrf': (r) => r.status === 200 && !!lb && typeof lb.csrf === 'string' && lb.csrf.length > 0,
    })) return false;
    setCsrf(st, lb);
    if (lb.grant_id) st.grant = String(lb.grant_id);
    return true;
  }

  const lb = json(login);
  if (!check(login, {
    'login 200 with csrf': (r) => (r.status === 200 || r.status === 201) && !!lb && typeof lb.csrf === 'string' && lb.csrf.length > 0,
  })) return false;
  st.csrf = lb.csrf;
  return true;
}

// Bounded recovery: at most one recovery per operation. Denied or unknown 401s fail their assertion.
function recover401(st, name, res, fn) {
  const kind = errorKind(res);
  if (kind !== 'expired' && kind !== 'session') return res;
  if (st.recovered[name]) return res;
  st.recovered[name] = true;
  if (!(renew(st) || freshLogin(st))) return res;
  if (st.cartId && !recoverCart(st)) return res;
  return fn();
}

function run(st, name, fn) {
  const res = fn();
  if (res.status !== 401) return res;
  return recover401(st, name, res, fn);
}

function findInStock(body) {
  let list = [];
  if (body && body.data && Array.isArray(body.data.products)) {
    list = body.data.products;
  } else if (body && body.data && body.data.product) {
    list = [body.data.product];
  } else if (body && body.product) {
    list = [body.product];
  }
  for (let i = 0; i < list.length; i++) {
    const p = list[i];
    if (!p || p.id === undefined || p.id === null) continue;
    const v = Array.isArray(p.variants) ? p.variants[0] : null;
    if (v && v.id !== undefined && v.id !== null && v.in_stock === true) {
      return { product: p.id, variant: v.id };
    }
  }
  return null;
}

function selectItem(st) {
  let res = run(st, 'catalog', () => send(st, 'GET', '/v2/catalog', undefined, {}, 'catalog'));
  if (!check(res, { 'catalog 200': (r) => r.status === 200 })) return null;
  let body = json(res);
  let pages = 1;
  for (;;) {
    const item = findInStock(body);
    if (item) return item;
    if (!body || !body.next || pages >= MAX_CATALOG_PAGES) return null;
    const next = resolveUrl(body.next);
    if (!next) return null;
    pages++;
    res = run(st, 'catalog_page', () => send(st, 'GET', next, undefined, {}, 'catalog_page'));
    if (!check(res, { 'catalog page 200': (r) => r.status === 200 })) return null;
    body = json(res);
  }
}

function createCart(st, item) {
  const payload = { product_id: item.product, variant_id: item.variant };
  if (st.grant) payload.grant_id = st.grant;
  const res = run(st, 'cart', () => send(st, 'POST', '/v2/carts', payload, {}, 'cart'));
  const b = json(res);
  const ok = check(res, {
    'cart 201 with id': (r) => r.status === 201 && !!b && typeof b.id === 'string' && b.id.indexOf('cart-') === 0,
  });
  if (!ok) return false;
  st.cartId = b.id;
  setCsrf(st, b);
  st.etag = header(res, 'ETag') || st.etag;
  st.grant = ''; // grant_id is passed exactly once
  return true;
}

function orderRequest(st) {
  const extra = { 'Idempotency-Key': 'idem-' + st.cartId };
  if (st.etag) extra['If-Match'] = st.etag;
  return send(st, 'POST', '/v2/orders', { cart_id: st.cartId }, extra, 'order');
}

function reread(st) {
  const res = run(st, 'cart_reread', () =>
    send(st, 'GET', '/v2/carts/' + encodeURIComponent(st.cartId), undefined, {}, 'cart_reread'));
  const etag = header(res, 'ETag');
  if (!check(res, { 'cart re-read 200': (r) => r.status === 200 }) || !etag) return false;
  st.etag = etag;
  return true;
}

function placeOrder(st) {
  let res = run(st, 'order', () => orderRequest(st));
  if (res.status === 412) {
    if (!reread(st)) return false;
    res = run(st, 'order', () => orderRequest(st));
  }
  const b = json(res);
  const ok = check(res, {
    // HTTP 200 accepted:false is a business failure, not success.
    'order 201 accepted': (r) => r.status === 201 && !!b && b.accepted === true,
  });
  if (!ok) return false;
  setCsrf(st, b);
  acceptedOrders.add(1);
  return true;
}

function runJourney(st) {
  if (!freshLogin(st)) return false;
  const item = selectItem(st);
  if (!item) return false;
  if (!createCart(st, item)) return false;
  return placeOrder(st);
}

export function journey() {
  const st = newState();
  let ok = false;
  try {
    ok = runJourney(st);
  } catch (e) {
    ok = false;
  }
  unexpectedFailures.add(!ok);
}
