from urllib.parse import urlparse

from locust import HttpUser, LoadTestShape, StopUser, constant, task

BASE_URL = os.environ["BASE_URL"]
PASSWORD = "bench"
ACCOUNTS = 16

VUS = 4
# Execution contract rate: 2 committed checkout starts per second.
# (JMX ConstantThroughputTimer 121.2/min is ~2.02/s; the contract value is used.)
RATE = 2.0
LEAD_S = 3.0               # claim-to-T0 lead; first authenticated checkout anchors T0
ANCHOR_DEADLINE_S = 10.0
WARMUP_S = 5.0
SCORE_S = 30.0             # six 5s windows over [T0+5, T0+35)
DRAIN_S = 5.0
END_S = WARMUP_S + SCORE_S + DRAIN_S
TOTAL_SLOTS = int(round((WARMUP_S + SCORE_S) * RATE))  # 70 scheduled checkout starts

QUANTITY = 2
CATALOG_MAX_PAGES = 3

Result = namedtuple("Result", "kind code headers json text")

_SCHED = {"t0": None, "next": 0}
_ACCOUNT_SEQ = itertools.count()

_COMMENT_RE = re.compile(r"<!--.*?-->", re.S)
_INPUT_RE = re.compile(r"""<input\b((?:[^>"']|"[^"]*"|'[^']*')*)>""", re.I)
_FORM_RE = re.compile(r"""<form\b((?:[^>"']|"[^"]*"|'[^']*')*)>""", re.I)
_ATTR_RE = re.compile(r"""([^\s"'>/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?""")


def _claim_slot():
    k = _SCHED["next"]
    if k >= TOTAL_SLOTS:
        return None
    if _SCHED["t0"] is None:
        _SCHED["t0"] = time.monotonic() + LEAD_S
    _SCHED["next"] = k + 1
    return _SCHED["t0"] + k / RATE


class CheckoutShape(LoadTestShape):
    def tick(self):
        t0 = _SCHED["t0"]
        if t0 is None:
