_FORM_RE = re.compile(r"""<form\b((?:[^>"']|"[^"]*"|'[^']*')*)>""", re.I)
_ATTR_RE = re.compile(r"""([^\s"'>/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?""")


def _claim_slot():
    k = _SCHED["next"]
    if k >= TOTAL_SLOTS:
        return None
    if _SCHED["t0"] is None:
        _SCHED["t0"] = time.monotonic() + LEAD_S
    _SCHED["next"] = k + 1
    return _SCHED["t0"] + k / RATE


class CheckoutShape(LoadTestShape):
    def tick(self):
        t0 = _SCHED["t0"]
        if t0 is None:
            if self.get_run_time() > ANCHOR_DEADLINE_S:
                return None
            return VUS, VUS
        if time.monotonic() >= t0 + END_S:
            return None
        return VUS, VUS


def _j(text):
    try:
        return json.loads(text)
    except (TypeError, ValueError):
        return None


def _jd(resp):
    d = _j(resp.text)
    return d if isinstance(d, dict) else {}


def _path(loc):
    p = urlparse(loc)
    path = p.path if p.path.startswith("/") else "/" + p.path
    return path + ("?" + p.query if p.query else "")


def _attrs(s):
    out = {}
    for m in _ATTR_RE.finditer(s):
        val = next((g for g in m.group(2, 3, 4) if g is not None), "")
        out.setdefault(m.group(1).lower(), html.unescape(val))
    return out


def _input_value(text, name):
    for m in _INPUT_RE.finditer(_COMMENT_RE.sub("", text or "")):
        a = _attrs(m.group(1))
        if a.get("name") == name and a.get("value"):
            return a["value"]
    return None


def _challenge_parts(text):
    text = _COMMENT_RE.sub("", text or "")
    action = None
    for m in _FORM_RE.finditer(text):
        path = urlparse(_attrs(m.group(1)).get("action", "")).path
        if re.fullmatch(r"/v2/challenges/[^/\s]+", path):
            action = path
            break
    token = _input_value(text, "challenge")
    if action and token:
        return action, token
    return None


def _products(d):
    if not isinstance(d, dict):
        return []
    data = d.get("data")
    if isinstance(data, dict) and isinstance(data.get("products"), list):
        return data["products"]
    if isinstance(d.get("products"), list):
        return d["products"]
    if isinstance(d.get("product"), dict):
        return [d["product"]]
    return []


def _pick_variant(products):
    for p in products:
        if not isinstance(p, dict) or p.get("id") is None:
            continue
        for v in p.get("variants") or []:
            if isinstance(v, dict) and v.get("id") is not None and v.get("in_stock") is True:
                return p["id"], v["id"]
    return None


def _next_url(d):
    nxt = d.get("next") if isinstance(d, dict) else None
    if not isinstance(nxt, str) or not nxt:
        return None
    return _path(nxt)


def _catalog_check(last):
    def check(r):
        d = _j(r.text)
        if _pick_variant(_products(d)) is not None:
            return True
        return (not last) and _next_url(d) is not None
    return check


def _login_check(r):
    if r.status_code == 302:
        return bool(r.headers.get("Location"))
    return bool(_jd(r).get("csrf"))


def _cart_check(r):
    d = _jd(r)
    return isinstance(d.get("id"), str) and bool(d.get("id")) and bool(r.headers.get("ETag"))


def _accepted(r):
    d = _jd(r)
    return d.get("accepted") is True and bool(d.get("id"))


def _resolve(x):
    return x() if callable(x) else x


class CheckoutUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)
    weight = 1

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = f"bench-{next(_ACCOUNT_SEQ) % ACCOUNTS + 1}"
        self._reset()

    def _reset(self):
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.product = None
        self.variant = None
        self.grant = None

    @task
    def journey(self):
        self._reset()
        self.client.cookies.clear()
        if not self._setup():
            return
        # Claim the scheduled checkout slot only after setup succeeds, so failed
        # setups do not consume committed-start slots.
        slot = _claim_slot()
        if slot is None:
            raise StopUser()
        delay = slot - time.monotonic()
        if delay > 0:
            time.sleep(delay)
        self._checkout()
        raise StopUser()

    def _send(self, method, path, name, body=None, headers=None, ok=(200,),
              check=None, soft=()):
        hdrs = {"Accept": "application/json"}
        data = None
        if body is not None:
            hdrs["Content-Type"] = "application/json"
            data = json.dumps(body)
        if method != "GET" and self.csrf:
            hdrs["X-CSRF-Token"] = self.csrf
        if headers:
            hdrs.update({k: v for k, v in headers.items() if v is not None})
        with self.client.request(method, path, name=name, data=data, headers=hdrs,
                                 catch_response=True, allow_redirects=False) as r:
            code = r.status_code
            hdr = r.headers
            text = r.text
            payload = _j(text)
            err = payload.get("error") if isinstance(payload, dict) else None
            if code in ok and (check is None or check(r)):
                kind = "ok"
                r.success()
            elif code == 401 and 401 in soft and err in ("expired", "session"):
                kind = "auth-" + err
                r.success()
            elif code != 401 and code in soft:
                kind = "soft"
                r.success()
            else:
                kind = "fail"
                r.failure(f"{name}: HTTP {code} error={err!r}")
        if kind == "ok" and isinstance(payload, dict) and payload.get("csrf"):
            self.csrf = payload["csrf"]
        return Result(kind, code, hdr, payload, text)

    def _op(self, method, path, name, body=None, headers=None, ok=(200,),
            check=None, cart_op=False):
        """One bounded operation: at most one auth recovery and one 412 re-read."""
        soft = (401, 412) if cart_op else (401,)
        recovered = False
        reread = False
        while True:
            res = self._send(method, path, name, body=_resolve(body),
                             headers=_resolve(headers), ok=ok, check=check, soft=soft)
            if res.kind == "ok":
                return res
            if res.kind in ("auth-expired", "auth-session") and not recovered:
                recovered = True
                if self._recover_auth(res.kind):
                    continue
                return None
            if cart_op and res.code == 412 and not reread:
                reread = True
                if self._reread_cart():
                    continue
            return None

    def _recover_auth(self, kind):
        if kind == "auth-expired":
            r = self._send("POST", "/v2/session/renew", "session-renew", body={},
                           ok=(200, 201), soft=(401,))
            if r.kind == "ok":
                return self._recover_cart()
            if r.kind == "fail":
                return False
        # Revoked session (or failed renew): fresh form and login, then recover cart.
        if not self._login("relogin"):
            return False
        return self._recover_cart()

    def _recover_cart(self):
        if self.cart_id is None:
            return True
        r = self._send("POST", f"/v2/carts/{self.cart_id}/recover", "cart-recover",
                       body={}, ok=(200, 201, 204))
        if r.kind != "ok":
            return False
        return self._reread_cart()

    def _reread_cart(self):
        r = self._send("GET", f"/v2/carts/{self.cart_id}", "cart-reread", ok=(200,),
                       check=lambda x: bool(x.headers.get("ETag")))
        if r.kind != "ok":
            return False
        self.etag = r.headers["ETag"]
        return True

    def _login(self, tag):
        form = self._send("GET", "/v2/login-form", f"{tag}-form", ok=(200,),
                          check=lambda r: _input_value(r.text, "csrf") is not None)
        if form.kind != "ok":
            return False
        token = _input_value(form.text, "csrf")
        self.csrf = token
        post = self._send("POST", "/v2/login", f"{tag}-post",
                          body={"username": self.username, "password": PASSWORD, "csrf": token},
                          ok=(200, 201, 302), check=_login_check)
        if post.kind != "ok":
            return False
        if post.code == 302:
            redirect = self._send("GET", _path(post.headers["Location"]),
                                  f"{tag}-redirect", ok=(200,))
            return redirect.kind == "ok"
        return True

    def _select(self):
        path, name = "/v2/catalog", "catalog"
        for page in range(CATALOG_MAX_PAGES):
            last = page == CATALOG_MAX_PAGES - 1
            res = self._op("GET", path, name, ok=(200,), check=_catalog_check(last))
            if res is None:
                return False
            pick = _pick_variant(_products(res.json))
            if pick is not None:
                self.product, self.variant = pick
                return True
            path = _next_url(res.json)
            if path is None:
                return False
            name = "catalog-page"
        return False

    def _challenge(self):
        form = self._op("GET", "/v2/challenge-form", "challenge-form", ok=(200,),
                        check=lambda r: _challenge_parts(r.text) is not None)
        if form is None:
            return False
        action, token = _challenge_parts(form.text)
        submit = self._op("POST", action, "challenge-submit", body={"challenge": token},
                          ok=(302,), check=lambda r: bool(r.headers.get("Location")))
        if submit is None:
            return False
        claim = self._op("GET", _path(submit.headers["Location"]), "challenge-claim",
                         ok=(200,), check=lambda r: _jd(r).get("grant_id") is not None)
        if claim is None:
            return False
        self.grant = claim.json["grant_id"]
        return True

    def _create_cart(self):
        def body():
            b = {"product_id": self.product, "variant_id": self.variant}
            if self.grant is not None:
                b["grant_id"] = self.grant
                self.grant = None  # grant_id is passed once
            return b

        res = self._op("POST", "/v2/carts", "cart-create", body=body, ok=(201,),
                       check=_cart_check, cart_op=True)
        if res is None:
            return False
        self.cart_id = res.json["id"]
        self.etag = res.headers["ETag"]
        return True

    def _set_quantity(self):
        res = self._op("PATCH", f"/v2/carts/{self.cart_id}", "cart-quantity",
                       body={"quantity": QUANTITY},
                       headers=lambda: {"If-Match": self.etag},
                       ok=(200, 204), cart_op=True)
        if res is None:
            return False
        self.etag = res.headers.get("ETag", self.etag)
        return True

    def _setup(self):
        return (self._login("login") and self._select() and self._challenge()
                and self._create_cart() and self._set_quantity())

    def _checkout(self):
        self._op("POST", "/v2/orders", "checkout",
                 body=lambda: {"cart_id": self.cart_id},
                 headers=lambda: {"If-Match": self.etag,
                                  "Idempotency-Key": f"checkout-{self.cart_id}"},
                 ok=(201,), check=_accepted, cart_op=True)
