import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import java.time.Duration;

public class ModelSimulation extends Simulation {

  private static final String BASE_URL =
      System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

  // Attribute-order-independent csrf input extraction (decoys/attribute variants tolerated).
  private static final String FORM_CSRF_RE =
      "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>";

  // Builds the cart payload; grant_id is passed once, only when a challenge grant was obtained.
  private static String cartBody(Session s) {
    StringBuilder b = new StringBuilder("{\"product_id\":\"")
        .append(s.getString("product"))
        .append("\",\"variant_id\":\"")
        .append(s.getString("variant"))
        .append("\"");
    if (s.contains("grant")) {
      b.append(",\"grant_id\":\"").append(s.getString("grant")).append("\"");
    }
    return b.append("}").toString();
  }

  // One fresh login/cart/order journey per iteration.
  private final ChainBuilder journey =
      exec(session -> session.set("username", "bench-" + (session.userId() % 16 + 1)))
          .exec(
              http("Login form")
                  .get("/v2/login-form")
                  .check(status().is(200))
                  .check(regex(FORM_CSRF_RE).group(1).find().saveAs("form")))
          .exec(
              http("Login")
                  .post("/v2/login")
                  .header("Content-Type", "application/json")
                  .body(StringBody(
                      "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
                  .check(status().in(200, 302))
                  .check(status().saveAs("loginStatus"))
                  .check(bodyString().transform(b -> b.isEmpty()
                      || b.replaceAll("\\s", "").contains("\"csrf\":")).is(true))
                  .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                  .check(header("Location").optional().saveAs("location")))
          .doIf(session -> session.getInt("loginStatus") == 302)
          .then(
              exec(
                  http("Challenge redirect")
                      .get("#{location}")
                      .check(status().is(200))
                      .check(jsonPath("$.grant_id").saveAs("grant"))
                      .check(jsonPath("$.csrf").saveAs("csrf"))))
          .exec(
              http("Catalog")
                  .get("/v2/catalog")
                  .check(status().is(200))
                  .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                      .find().saveAs("product"))
                  .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                      .find().saveAs("variant"))
                  .check(jsonPath("$.csrf").optional().saveAs("csrf")))
          .exec(
              http("Create cart")
                  .post("/v2/carts")
                  .header("Content-Type", "application/json")
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(StringBody(session -> cartBody(session)))
                  .check(status().is(201))
                  .check(jsonPath("$.id").saveAs("cart"))
                  .check(jsonPath("$.id").matches("cart-.*"))
                  .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                  .check(header("ETag").saveAs("etag")))
          .exec(
              http("Place order")
                  .post("/v2/orders")
                  .header("Content-Type", "application/json")
                  .header("X-CSRF-Token", "#{csrf}")
                  .header("If-Match", "#{etag}")
                  .header("Idempotency-Key", "#{cart}")
                  .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                  .check(status().in(200, 201))
                  // HTTP 200 with accepted:false is a business failure, not success.
                  .check(jsonPath("$.accepted").ofType(Boolean.class).is(true))
                  .check(jsonPath("$.id").optional().saveAs("order"))
                  .check(jsonPath("$.csrf").optional().saveAs("csrf")));

  private final ScenarioBuilder scn =
      scenario("ModelSimulation").exec(repeat(2).on(journey));

  public ModelSimulation() {
    HttpProtocolBuilder protocol = http
        .baseUrl(BASE_URL)
        .acceptHeader("application/json")
        .disableFollowRedirect()
        .requestTimeout(Duration.ofSeconds(3));

    setUp(scn.injectOpen(atOnceUsers(2)))
        .protocols(protocol)
        .assertions(
            // Denominator: 2 users x 2 iterations = 4 journeys, one cart and one order each.
            details("Create cart").successfulRequests().count().is(4L),
            details("Place order").successfulRequests().count().is(4L),
            global().failedRequests().count().is(0L));
  }
}
