                  // HTTP 200 with accepted:false is a business failure, not success.
                  .check(regex("\"accepted\"\\s*:\\s*true").exists())
                  .check(jsonPath("$.id").optional().saveAs("order"))
                  .check(jsonPath("$.csrf").optional().saveAs("csrf")));

  private final ScenarioBuilder scn =
      scenario("ModelSimulation").exec(repeat(2).on(journey));

  public ModelSimulation() {
    HttpProtocolBuilder protocol = http
        .baseUrl(BASE_URL)
        .acceptHeader("application/json")
        .disableFollowRedirect();

    setUp(scn.injectOpen(atOnceUsers(2)))
        .protocols(protocol)
        .assertions(
            // Denominator: 2 users x 2 iterations = 4 journeys, one cart and one order each.
            details("Create cart").successfulRequests().count().is(4L),
            details("Place order").successfulRequests().count().is(4L),
            global().failedRequests().count().is(0L));
