```javascript
import http from 'k6/http';
import { check } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PROFILE = __ENV.FIXTURE_PROFILE || 'default';
const PASSWORD = 'bench';
const MAX_PAGES = 3;
const REQ_TIMEOUT = '3000ms';

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
  discardResponseBodies: false,
  thresholds: {
    checks: ['rate>=1'],
    'checks{txn:login-form}': ['rate>=1'],
    'checks{txn:login}': ['rate>=1'],
    'checks{txn:catalog}': ['rate>=1'],
    'checks{txn:cart-create}': ['rate>=1'],
    'checks{txn:order}': ['rate>=1'],
  },
};

function absolute(path) {
  if (/^https?:\/\//i.test(path)) {
    if (path === BASE || path.indexOf(BASE + '/') === 0) return path;
    throw new Error('off-target URL refused: ' + path);
  }
  return BASE + (path.charAt(0) === '/' ? path : '/' + path);
}

function newState(user) {
  return { user: user, jar: new http.CookieJar(), csrf: null, etag: null, cartId: null };
}

function header(res, name) {
  const want = name.toLowerCase();
  const h = (res && res.headers) || {};
  for (const k in h) {
    if (k.toLowerCase() === want) return h[k];
  }
  return null;
}

function parse(res) {
  if (!res || typeof res.body !== 'string') return null;
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function absorb(st, res) {
  const etag = header(res, 'etag');
  if (etag) st.etag = etag;
  const j = parse(res);
  if (j && typeof j.csrf === 'string' && j.csrf.length > 0) st.csrf = j.csrf;
}

function csrfHeader(st) {
  return st.csrf ? { 'X-CSRF-Token': st.csrf } : {};
}

// Single request helper: per-iteration cookie jar, no auto redirects, transaction tag.
function call(st, txn, method, path, body, headers) {
  const p = {
    jar: st.jar,
    redirects: 0,
    timeout: REQ_TIMEOUT,
    headers: Object.assign({}, headers || {}),
    tags: { txn: txn, profile: PROFILE },
  };
  let res;
  if (body === undefined) {
    res = http.request(method, absolute(path), null, p);
  } else {
    p.headers['Content-Type'] = 'application/json';
    res = http.request(method, absolute(path), JSON.stringify(body), p);
  }
  absorb(st, res);
  return res;
}

function stripComments(html) {
  return String(html || '').replace(/<!--[\s\S]*?-->/g, '');
}

function attr(tag, name) {
  const re = new RegExp('(?:^|\\s)' + name + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s"\'>]+))', 'i');
  const m = re.exec(tag);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  return m[3] === undefined ? null : m[3];
}

function formField(html, name) {
  const tags = stripComments(html).match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i++) {
    if (attr(tags[i], 'name') === name) {
      const v = attr(tags[i], 'value');
      if (v) return v;
    }
  }
  return null;
}

function challengeAction(html) {
  const forms = stripComments(html).match(/<form\b[^>]*>/gi) || [];
  for (let i = 0; i < forms.length; i++) {
    const a = attr(forms[i], 'action');
    if (a && a.indexOf('/v2/challenges/') >= 0) return a;
  }
  return null;
}

function productsOf(j) {
  if (j && j.data && Array.isArray(j.data.products)) return j.data.products;
  if (j && j.product) return [j.product];
  return [];
}

function inStock(p) {
  return !!p && Array.isArray(p.variants) && p.variants.length > 0 &&
    !!p.variants[0] && p.variants[0].in_stock === true;
}

// 401 classification from the error body; only expired/session are recoverable.
function authKind(res) {
  if (res.status !== 401) return null;
  const m = /"error"\s*:\s*"(expired|session|denied)"/.exec(res.body || '');
  return m ? m[1] : 'unknown';
}

function renew(st) {
  const res = call(st, 'session-renew', 'POST', '/v2/session/renew', {}, csrfHeader(st));
  const j = parse(res);
  return res.status === 200 && !!j && typeof j.csrf === 'string' && j.csrf.length > 0;
}

function recoverCart(st) {
  const res = call(st, 'cart-recover', 'POST', '/v2/carts/' + st.cartId + '/recover', {}, csrfHeader(st));
  return res.status >= 200 && res.status < 300;
}

function loginForm(st) {
  const res = call(st, 'login-form', 'GET', '/v2/login-form');
  const token = formField(res.body, 'csrf');
  check(res, {
    'login form 200': (r) => r.status === 200,
    'login form csrf input': () => !!token,
  }, { txn: 'login-form' });
  return token;
}

function login(st, token) {
  st.csrf = token;
  const res = call(st, 'login', 'POST', '/v2/login',
    { username: st.user, password: PASSWORD, csrf: token }, csrfHeader(st));
  if (res.status === 302) {
    const loc = header(res, 'location');
    if (!check(res, { 'login redirect has location': () => !!loc }, { txn: 'login' })) {
      return false;
    }
    const follow = call(st, 'login-redirect', 'GET', loc);
    return check(follow, {
      'login redirect 200': (r) => r.status === 200,
      'login csrf issued': (r) => /"csrf"\s*:/.test(r.body || ''),
    }, { txn: 'login' });
  }
  return check(res, {
    'login 200': (r) => r.status === 200,
    'login csrf issued': (r) => /"csrf"\s*:/.test(r.body || ''),
  }, { txn: 'login' });
}

function freshLogin(st) {
  const token = loginForm(st);
  return !!token && login(st, token);
}

// Bounded: at most one recovery and one retry per operation; never restarts checkout.
function guarded(st, build) {
  const first = build(st, false);
  const kind = authKind(first);
  if (kind !== 'expired' && kind !== 'session') return first;

  const renewed = renew(st);
  if (kind === 'expired' && !renewed) return first;
  if (kind === 'session' && !renewed && !freshLogin(st)) return first;
  if (st.cartId && !recoverCart(st)) return first;

  return build(st, true);
}

function pickProduct(st) {
  let next = '/v2/catalog';
  for (let page = 1; page <= MAX_PAGES && next; page++) {
    const path = next;
    const txn = page === 1 ? 'catalog' : 'catalog-page';
    const res = guarded(st, (s) => call(s, txn, 'GET', path));
    const j = parse(res);
    const ok = check(res, {
      'catalog page 200 with JSON': (r) => r.status === 200 && !!j,
    }, { txn: 'catalog' });
    if (!ok) return null;
    const hit = productsOf(j).find(inStock);
    if (hit) {
      return { product: hit.id, variant: hit.variants[0].id };
    }
    next = typeof j.next === 'string' && j.next.length > 0 ? j.next : null;
  }
  check(null, { 'in-stock product found': () => false }, { txn: 'catalog' });
  return null;
}

function acquireGrant(st) {
  const form = call(st, 'challenge-form', 'GET', '/v2/challenge-form');
  const action = challengeAction(form.body);
  const challenge = formField(form.body, 'challenge');
  const formOk = check(form, {
    'challenge form 200': (r) => r.status === 200,
    'challenge form action and input': () => !!action && !!challenge,
  }, { txn: 'challenge' });
  if (!formOk) return null;

  const post = guarded(st, (s) =>
    call(s, 'challenge-post', 'POST', action, { challenge: challenge }, csrfHeader(s)));
  const postLoc = header(post, 'location');
  const postOk = check(post, {
    'challenge 302 with location': (r) => r.status === 302 && !!postLoc,
  }, { txn: 'challenge' });
  if (!postOk) return null;

  const claim = call(st, 'challenge-claim', 'GET', postLoc);
  const j = parse(claim);
  const claimOk = check(claim, {
    'grant issued': (r) => r.status === 200 && !!j && j.grant_id !== undefined &&
      j.grant_id !== null && String(j.grant_id) !== '',
  }, { txn: 'challenge' });
  return claimOk ? j.grant_id : null;
}

function createCart(st, sel, grant) {
  const res = guarded(st, (s, retry) => {
    const body = { product_id: sel.product, variant_id: sel.variant };
    if (grant && !retry) body.grant_id = grant;
    return call(s, 'cart-create', 'POST', '/v2/carts', body, csrfHeader(s));
  });
  const j = parse(res);
  const ok = check(res, {
    'cart created 201': (r) => r.status === 201,
    'cart id issued': () => !!j && typeof j.id === 'string' && j.id.indexOf('cart-') === 0,
  }, { txn: 'cart-create' });
  return ok ? j.id : null;
}

function orderHeaders(s) {
  const h = csrfHeader(s);
  h['Idempotency-Key'] = s.cartId;
  if (s.etag) h['If-Match'] = s.etag;
  return h;
}

// Business failure (HTTP 2xx with accepted:false) is not success; never resubmitted.
function submitOrder(st) {
  const res = guarded(st, (s) =>
    call(s, 'order', 'POST', '/v2/orders', { cart_id: s.cartId }, orderHeaders(s)));
  const j = parse(res);
  check(res, {
    'order 2xx': (r) => r.status >= 200 && r.status < 300,
    'order accepted true': () => !!j && j.accepted === true,
  }, { txn: 'order' });
}

export default function () {
  const st = newState('bench-' + __VU);
  const token = loginForm(st);
  if (!token || !login(st, token)) return;

  const sel = pickProduct(st);
  if (!sel) return;

  const grant = acquireGrant(st);
  const cartId = createCart(st, sel, grant);
  if (!cartId) return;

  st.cartId = cartId;
  submitOrder(st);
}
