import itertools
import json
import os
import re
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, StopUser, constant, task

HOST = os.environ["BASE_URL"]
PASSWORD = "bench"
ITERATIONS = 2
ACCOUNT_POOL = 16
MAX_CATALOG_PAGES = 3
MAX_RUN_SECONDS = 1800

COMMENT_RE = re.compile(r"<!--.*?-->", re.S)
INPUT_RE = re.compile(r"<input\b[^>]*>", re.I)
CSRF_ASSERT_RE = re.compile(r'"csrf"\s*:')
CART_ASSERT_RE = re.compile(r'"id"\s*:\s*"cart-')
ACCEPTED_ASSERT_RE = re.compile(r'"accepted"\s*:\s*true')
AUTH_ERROR_RE = re.compile(r'"error"\s*:\s*"(expired|session|denied)"')

_ACCOUNT_SEQ = itertools.count(1)


def _attr(tag, attr):
    m = re.search(
        r"""(?<![\w-])%s\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))""" % attr,
        tag,
        re.I,
    )
    if not m:
        return None
    return next(g for g in m.groups() if g is not None)


def form_csrf(html):
    """Return the value of the input whose name is exactly csrf, ignoring comments/decoys."""
    for tag in INPUT_RE.findall(COMMENT_RE.sub("", html or "")):
        if _attr(tag, "name") == "csrf":
            value = _attr(tag, "value")
            if value:
                return value
    return None


def _json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def _local(location):
    """Resolve a (possibly dynamic) Location to a path on HOST only; never leave the target."""
    parts = urlsplit(urljoin(HOST + "/", location))
    return parts.path + (("?" + parts.query) if parts.query else "")


def _products(data):
    if not isinstance(data, dict):
        return []
    inner = data.get("data")
    if isinstance(inner, dict):
        if isinstance(inner.get("products"), list):
            return inner["products"]
        if isinstance(inner.get("product"), dict):
            return [inner["product"]]
    if isinstance(data.get("product"), dict):
        return [data["product"]]
    if isinstance(data.get("products"), list):
        return data["products"]
    return []


def _pick(data):
