        return product["id"], variants[0]["id"]
    return None


def _form_ok(resp, data):
    if resp.status_code != 200:
        return f"login form status {resp.status_code}"
    if not form_csrf(resp.text):
        return "login form has no csrf input"
    return None


def _login_ok(resp, data):
    if resp.status_code == 302:
        return None if resp.headers.get("Location") else "302 without Location"
    if resp.status_code != 200:
        return f"login status {resp.status_code}"
    if not CSRF_ASSERT_RE.search(resp.text or ""):
        return "login response missing csrf"
    return None


def _redirect_ok(resp, data):
    if resp.status_code != 200:
        return f"login redirect status {resp.status_code}"
    if not CSRF_ASSERT_RE.search(resp.text or ""):
        return "login redirect response missing csrf"
    return None


def _csrf_ok(resp, data):
    if resp.status_code != 200:
        return f"status {resp.status_code}"
    if not (isinstance(data, dict) and isinstance(data.get("csrf"), str) and data["csrf"]):
        return "missing fresh csrf"
    return None


def _2xx(resp, data):
    return None if 200 <= resp.status_code < 300 else f"status {resp.status_code}"


def _catalog_ok(page):
    def judge(resp, data):
        if resp.status_code != 200:
            return f"catalog status {resp.status_code}"
        if not isinstance(data, dict):
            return "catalog body is not json"
        if _pick(data) is not None:
            return None
        more = data.get("next")
        if isinstance(more, str) and more and page < MAX_CATALOG_PAGES - 1:
            return None
        return "no in-stock variant within catalog page budget"

    return judge


def _cart_ok(resp, data):
    if resp.status_code != 201:
        return f"cart status {resp.status_code}"
    if not CART_ASSERT_RE.search(resp.text or ""):
        return "cart response missing id"
    if not (isinstance(data, dict) and str(data.get("id", "")).startswith("cart-")):
        return "cart id malformed"
    return None


def _order_ok(resp, data):
    code = resp.status_code
    if isinstance(data, dict) and data.get("accepted") is False:
        return f"business failure: order accepted=false (status {code})"
    if code == 201 and isinstance(data, dict) and data.get("accepted") is True \
            and data.get("id") and ACCEPTED_ASSERT_RE.search(resp.text or ""):
        return None
    return f"order status {code} without accepted:true"


class Res:
    __slots__ = ("resp", "data", "auth", "msg")

    def __init__(self, resp, data, auth, msg):
        self.resp = resp
        self.data = data
        self.auth = auth  # set only for expected expiry/revocation that needs recovery
        self.msg = msg    # None means the step passed (or is awaiting recovery)


class ShopUser(HttpUser):
    host = HOST
    wait_time = constant(0)

    def on_start(self):
        n = next(_ACCOUNT_SEQ)
        self.account = "bench-%d" % (((n - 1) % ACCOUNT_POOL) + 1)
        self.iterations_done = 0
        self._reset()

    def _reset(self):
        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant = None

    @task
    def checkout_journey(self):
        if self.iterations_done >= ITERATIONS:
            raise StopUser()
        self.iterations_done += 1
        self.client.cookies.clear()  # JMX CookieManager clearEachIteration=true
        self._reset()
        if not self._login():
            return
        pick = self._find_product()
        if pick is None:
            return
        if not self._create_cart(pick):
            return
        self._place_order()

    def _absorb(self, resp, data, cart):
        if isinstance(data, dict):
            token = data.get("csrf")
            if isinstance(token, str) and token:
                self.csrf = token
        if cart:
            tag = resp.headers.get("ETag")
            if tag:
                self.etag = tag

    def _step(self, method, path, name, ok=None, body=None, recover=False,
              if_match=False, idem=None, cart=False):
        """One sampler. Expired/revoked 401 is expected here only when recover=True."""
        headers = {}
        payload = None
        if body is not None:
            headers["Content-Type"] = "application/json"
            payload = json.dumps(body)
        if method != "GET" and self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if if_match and self.etag:
            headers["If-Match"] = self.etag
        if idem:
            headers["Idempotency-Key"] = idem

        with self.client.request(
            method,
            path,
            name=name,
            data=payload,
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            data = _json(resp)
            auth = None
            if resp.status_code == 401:
                m = AUTH_ERROR_RE.search(resp.text or "")
                auth = m.group(1) if m else "unknown"

            if auth in ("expired", "session") and recover:
                # Expected expiry/revocation: handled by bounded recovery, not a failed sample.
                resp.success()
                return Res(resp, data, auth, None)

            if auth is not None:
                msg = f"401 error={auth}"
            elif ok is not None:
                msg = ok(resp, data)
            else:
                msg = None

            if msg is None:
                self._absorb(resp, data, cart)
                resp.success()
            else:
                resp.failure(msg)
            return Res(resp, data, None, msg)

    def _op(self, method, path, name, ok, body=None, if_match=False, idem=None, cart=False):
        """Operation with at most one recovery cycle, then one retry of the interrupted step."""
        res = self._step(method, path, name, ok=ok, body=body, recover=True,
                         if_match=if_match, idem=idem, cart=cart)
        if res.auth is None:
            return res
        if not self._recover(res.auth):
            return Res(None, None, None, "session recovery failed")
        return self._step(method, path, name, ok=ok, body=body, recover=False,
                          if_match=if_match, idem=idem, cart=cart)

    def _recover(self, kind):
        renewed = False
        if kind == "expired":
            renew = self._step("POST", "/v2/session/renew", "session renew",
                               ok=_csrf_ok, body={})
            renewed = renew.msg is None
        if not renewed and not self._login():
            return False
        if self.cart_id is not None:
            rec = self._step("POST", "/v2/carts/%s/recover" % self.cart_id, "cart recover",
                             ok=_2xx, body={}, cart=True)
            if rec.msg is not None:
                return False
        return True

    def _login(self):
        self.grant = None
        form = self._step("GET", "/v2/login-form", "login form", ok=_form_ok)
        if form.msg is not None:
            return False
        self.csrf = form_csrf(form.resp.text)
        login = self._step(
            "POST", "/v2/login", "login", ok=_login_ok,
            body={"username": self.account, "password": PASSWORD, "csrf": self.csrf},
        )
        if login.msg is not None:
            return False
        if login.resp.status_code == 302:
            redirect = self._step("GET", _local(login.resp.headers["Location"]),
                                  "login redirect", ok=_redirect_ok)
            if redirect.msg is not None:
                return False
            grant = redirect.data.get("grant_id") if isinstance(redirect.data, dict) else None
            self.grant = grant or None
        return True

    def _find_product(self):
        url = "/v2/catalog"
        for page in range(MAX_CATALOG_PAGES):
            name = "catalog" if page == 0 else "catalog page"
            res = self._op("GET", url, name, ok=_catalog_ok(page))
            if res.msg is not None:
                return None
            pick = _pick(res.data)
            if pick is not None:
                return pick
            nxt = res.data.get("next") if isinstance(res.data, dict) else None
            if not isinstance(nxt, str) or not nxt:
                return None
            url = _local(nxt)
        return None

    def _create_cart(self, pick):
        product_id, variant_id = pick
        body = {"product_id": product_id, "variant_id": variant_id}
        if self.grant:
            body["grant_id"] = self.grant  # passed once to cart creation
        res = self._op("POST", "/v2/carts", "cart create", ok=_cart_ok, body=body, cart=True)
        if res.msg is not None:
            return False
        self.cart_id = res.data["id"]
        self.grant = None
        return True

    def _place_order(self):
        # Idempotency-Key is unique per cart and stable across retries.
        res = self._op(
            "POST", "/v2/orders", "order", ok=_order_ok,
            body={"cart_id": self.cart_id},
            if_match=True,
            idem=self.cart_id,
        )
        return res.msg is None


class RunShape(LoadTestShape):
    """Start 2 users once; keep the current population until they stop themselves.

    Exit-code rule (zero tolerance, no custom listeners): every failed sample -- including
    declined orders, unexpected 500s, denied 401s and failed recoveries -- is a failed sample,
    and Locust's default --exit-code-on-error 1 makes the run exit non-zero.
    """

    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        if self.get_run_time() > MAX_RUN_SECONDS:
            return None
        if not self.started:
            self.started = True
            return (2, 2)
        running = self.runner.user_count if self.runner is not None else 0
        if running == 0:
            return None
        return (running, 2)
