import http from 'k6/http';
import { check } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = { users: 2, iterations: 2, mode: 'flow' };
const rows = [
  { username: 'bench-1', password: 'bench', quantity: 2 },
  { username: 'bench-2', password: 'bench', quantity: 3 },
  { username: 'bench-3', password: 'bench', quantity: 4 },
  { username: 'bench-4', password: 'bench', quantity: 5 },
  { username: 'bench-5', password: 'bench', quantity: 6 },
  { username: 'bench-6', password: 'bench', quantity: 7 },
  { username: 'bench-7', password: 'bench', quantity: 8 },
  { username: 'bench-8', password: 'bench', quantity: 9 },
  { username: 'bench-9', password: 'bench', quantity: 10 },
  { username: 'bench-10', password: 'bench', quantity: 11 },
  { username: 'bench-11', password: 'bench', quantity: 12 },
  { username: 'bench-12', password: 'bench', quantity: 13 },
  { username: 'bench-13', password: 'bench', quantity: 14 },
  { username: 'bench-14', password: 'bench', quantity: 15 },
  { username: 'bench-15', password: 'bench', quantity: 16 },
  { username: 'bench-16', password: 'bench', quantity: 17 },
];

const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

const base = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// Per-VU session state; reset at the start of every journey.
let csrf = '';
let cart = '';

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  const h = r.headers || {};
  const want = name.toLowerCase();
  const keys = Object.keys(h);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return h[keys[i]];
  }
  return undefined;
}

// Convert an absolute or relative URL into a path under base (single origin only).
function local(u) {
  return String(u).replace(/^https?:\/\/[^/]+/, '');
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = Object.assign(
    { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    extra
  );
  const r = http.request(
    method,
    base + path,
    data === null ? null : JSON.stringify(data),
    { headers: headers, redirects: 0, timeout: '3s' }
  );
  const b = body(r);
  if (b.csrf) csrf = b.csrf; // retain previous token when absent
  if (path === '/v2/work') {
    failure.add(
      r.status >= 400 && r.status !== 429 && !(r.status === 401 && b.error === 'expired')
    );
  }
  return r;
}

// Fresh login: token must come from the login-form response, not any other response.
function login() {
  csrf = '';
  const form = raw('/v2/login-form');
  const token = form.html().find('input[name="csrf"]').first().attr('value');
  if (!token) {
    check(null, { 'login token extracted': () => false });
    return false;
  }
  csrf = token;
  const row = rows[(__VU - 1) % rows.length];
  let r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token,
  });
  if (r.status === 302) {
    const loc = header(r, 'Location');
    if (!loc) {
      check(null, { 'login redirect location': () => false });
      return false;
    }
    r = raw(local(loc)); // GET the dynamic Location exactly once
  }
  return check(r, { login: (x) => x.status === 200 });
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  if (r.status === 401) {
    const err = body(r).error;
    if (err === 'expired') {
      const renewed = raw('/v2/session/renew', 'POST', {});
      if (renewed.status !== 200) {
        if (!login()) return r;
      }
    } else if (err === 'session') {
      if (!login()) return r;
    } else {
      return r; // denied or other: not expiry, fail its assertion
    }
    if (cart) raw('/v2/carts/' + cart + '/recover', 'POST', {});
    r = raw(path, method, data, extra); // retry interrupted operation once
  }
  return r;
}

function flow() {
  csrf = '';
  cart = '';

  if (!login()) return;

  // Catalog traversal: at most 3 pages, following provided next URLs only.
  let page = '/v2/catalog';
  let product = null;
  let variant = null;
  for (let n = 0; n < 3 && page; n++) {
    const b = body(request(page));
    const data = b.data || {};
    const items = data.products || (data.product ? [data.product] : []);
    for (let i = 0; i < items.length && !product; i++) {
      const v = (items[i].variants || []).find((x) => x.in_stock);
      if (v) {
        product = items[i];
        variant = v;
      }
    }
    if (product) break;
    page = b.next ? local(b.next) : null;
  }
  check(product, { 'eligible product': (x) => !!x });
  if (!product) return;

  // Cart creation: one cart per journey.
  let r = request('/v2/carts', 'POST', { product_id: product.id, variant_id: variant.id });
  check(r, { 'cart created': (x) => x.status === 201 && !!body(x).id });
  cart = body(r).id;
  if (!cart) return;
  let etag = header(r, 'ETag');

  if (!etag) {
    const g = request('/v2/carts/' + cart);
    etag = header(g, 'ETag');
  }

  // Order: Idempotency-Key unique per cart and stable across retries.
  const orderHeaders = { 'Idempotency-Key': 'order-' + cart };
  if (etag) orderHeaders['If-Match'] = etag;
  r = request('/v2/orders', 'POST', { cart_id: cart }, orderHeaders);
  check(r, {
    'order accepted': (x) => x.status === 201 && body(x).accepted === true,
  });
}

export default function () {
  flow();
}
