import http from 'k6/http';
import {check, sleep} from 'k6';
import {Rate} from 'k6/metrics';

const cfg = {"users": 2, "iterations": 2, "mode": "flow"};
const rows = [{"username": "bench-1", "password": "bench", "quantity": 2}, {"username": "bench-2", "password": "bench", "quantity": 3}, {"username": "bench-3", "password": "bench", "quantity": 4}, {"username": "bench-4", "password": "bench", "quantity": 5}, {"username": "bench-5", "password": "bench", "quantity": 6}, {"username": "bench-6", "password": "bench", "quantity": 7}, {"username": "bench-7", "password": "bench", "quantity": 8}, {"username": "bench-8", "password": "bench", "quantity": 9}, {"username": "bench-9", "password": "bench", "quantity": 10}, {"username": "bench-10", "password": "bench", "quantity": 11}, {"username": "bench-11", "password": "bench", "quantity": 12}, {"username": "bench-12", "password": "bench", "quantity": 13}, {"username": "bench-13", "password": "bench", "quantity": 14}, {"username": "bench-14", "password": "bench", "quantity": 15}, {"username": "bench-15", "password": "bench", "quantity": 16}, {"username": "bench-16", "password": "bench", "quantity": 17}];
const failure = new Rate('business_failure');

export const options = {"scenarios": {"journeys": {"executor": "per-vu-iterations", "vus": 2, "iterations": 2, "maxDuration": "30s"}}, "thresholds": {"checks": ["rate==1"]}};

const base = __ENV.BASE_URL;

// No module-level mutable state: every journey owns a fresh state object,
// and each iteration starts from an empty cookie jar, so nothing (session,
// CSRF, cart, grant, reservation) can leak from one iteration into the next.

function newState() {
  return {csrf: '', cart: null, etag: null, grant: null, reservation: null};
}

function parse(r) {
  try {
    return r.json() || {};
  } catch (_) {
    return {};
  }
}

function hdr(r, name) {
  const h = r.headers || {};
  const want = name.toLowerCase();
  const keys = Object.keys(h);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return h[keys[i]];
  }
  return undefined;
}

function abs(p) {
  return /^https?:\/\//.test(p) ? p : base + p;
}

function send(state, method, path, data, extra) {
  const headers = Object.assign({'Content-Type': 'application/json'}, extra || {});
  if (method !== 'GET' && state.csrf) headers['X-CSRF-Token'] = state.csrf;
  const body = (data === undefined || data === null) ? null : JSON.stringify(data);
  const r = http.request(method, abs(path), body, {headers: headers, redirects: 0, timeout: '3s'});
  const b = parse(r);
  if (typeof b.csrf === 'string' && b.csrf) state.csrf = b.csrf;
  if (path === '/v2/work') {
    const expired = r.status === 401 && parse(r).error === 'expired';
    failure.add(r.status >= 400 && !expired && r.status !== 429);
  }
  return r;
}

// Authenticated operation with bounded recovery: at most one renew/login plus
// one cart recover, then one retry of the interrupted operation.
function request(state, method, path, data, extra) {
  let r = send(state, method, path, data, extra);
