}

function present(v) {
  return v !== undefined && v !== null && v !== '';
}

function target(path) {
  if (path.indexOf('/') === 0) return base + path;
  if (path.indexOf(base + '/') === 0) return path;
  throw new Error('refused off-target URL: ' + path);
}

function json(r) {
  try {
