  try {
    return doc.find('input[name="' + name + '"]').first().attr('value') || '';
  } catch (_) {
    return '';
  }
}

function formAction(doc) {
  try {
    const scoped = doc.find('form[action^="/v2/challenges/"]').first().attr('action');
    if (scoped) return scoped;
    return doc.find('form').first().attr('action') || '';
  } catch (_) {
    return '';
  }
}

