  const d = b.data && typeof b.data === 'object' ? b.data : {};
  if (Array.isArray(d.products)) return d.products;
  if (d.product && typeof d.product === 'object') return [d.product];
  if (b.product && typeof b.product === 'object') return [b.product];
  return [];
