  return once('POST', '/v2/session/renew', {}, {}).status === 200;
}

function recoverCart() {
  if (!cart) return;
  const r = once('POST', '/v2/carts/' + cart + '/recover', {}, {});
  ok('cart recovered', r.status === 200);
}

// Sends one operation. A 401 error=expired or error=session is recovered once
// (renew / fresh login, cart recovery, single retry of this operation only).
// A 401 error=denied, or any other 401, is returned unchanged so the caller's
// assertion fails.
function send(method, path, payload, extra) {
  const first = once(method, path, payload, extra);
  if (first.status !== 401) return first;
  const kind = errorOf(first);
  if (kind === 'expired') {
    expiryRecognized.add(1);
    if (!renew()) return first;
  } else if (kind === 'session') {
    if (!renew() && !login()) return first;
  } else {
    return first;
  }
  recoverCart();
  return once(method, path, payload, extra);
}

// Challenge flow: form -> POST action {challenge} -> 302 -> GET Location once.
function obtainGrant() {
  let r = send('GET', '/v2/challenge-form', null, {});
  if (!ok('challenge form', r.status === 200)) return false;
  const doc = r.html();
  const action = formAction(doc);
  const token = fieldValue(doc, 'challenge');
  if (!ok('challenge fields', action.indexOf('/v2/challenges/') === 0 && token !== '')) return false;
  r = send('POST', action, { challenge: token }, {});
  if (!ok('challenge redirect', r.status === 302)) return false;
  const loc = header(r, 'Location');
  if (!ok('challenge location', loc !== '')) return false;
  r = send('GET', loc, null, {});
  const b = json(r);
  if (!ok('grant issued', r.status === 200 && present(b.grant_id))) return false;
  grant = b.grant_id;
  return true;
