// Catalog: first /v2/catalog, then /v2/catalog/page, following relative next
// cursors as given. At most 3 pages. No guessed cursors.
function pickVariant() {
  let page = '/v2/catalog';
  for (let n = 0; n < 3 && page; n++) {
    const r = send('GET', page, null, {});
    if (!ok('catalog page ' + (n + 1), r.status === 200)) return null;
    const b = json(r);
    const list = productsOf(b);
    for (let i = 0; i < list.length; i++) {
      const p = list[i];
      if (!p || !Array.isArray(p.variants)) continue;
      for (let j = 0; j < p.variants.length; j++) {
        const v = p.variants[j];
        if (v && v.in_stock === true) return { product: p, variant: v };
      }
    }
    if (typeof b.next === 'string' && b.next !== '') page = b.next;
    else page = n === 0 ? '/v2/catalog/page' : null;
  }
  ok('eligible in-stock product', false);
  return null;
}

// One committed order per journey. Cart is created once, order is
// idempotent per cart, and the journey stops at the first failed assertion.
function journey() {
  csrf = '';
  cart = '';
  etag = '';
  grant = '';

  if (!login()) return;
  const pick = pickVariant();
  if (!pick) return;
  if (!obtainGrant()) return;

  const payload = { product_id: pick.product.id, variant_id: pick.variant.id };
  if (grant) payload.grant_id = grant;
  let r = send('POST', '/v2/carts', payload, {});
  const cb = json(r);
  if (!ok('cart created', r.status === 201 && present(cb.id))) return;
  cart = String(cb.id);
  etag = header(r, 'ETag');
  grant = '';
  if (!ok('cart etag', etag !== '')) return;

  const cartPath = '/v2/carts/' + cart;
  const quantity = rows[(__VU - 1) % rows.length].quantity;
  r = send('PATCH', cartPath, { quantity: quantity }, ifMatch(etag));
  if (r.status === 412) {
    const reread = send('GET', cartPath, null, {});
    if (!ok('cart re-read after 412', reread.status === 200)) return;
    etag = header(reread, 'ETag') || etag;
    r = send('PATCH', cartPath, { quantity: quantity }, ifMatch(etag));
  }
  if (!ok('cart updated', r.status === 200)) return;
  etag = header(r, 'ETag') || etag;

  const orderHeaders = () => Object.assign({ 'Idempotency-Key': 'order-' + cart }, ifMatch(etag));
  r = send('POST', '/v2/orders', { cart_id: cart }, orderHeaders());
  if (r.status === 412) {
    const reread = send('GET', cartPath, null, {});
    if (!ok('cart re-read before order', reread.status === 200)) return;
    etag = header(reread, 'ETag') || etag;
    r = send('POST', '/v2/orders', { cart_id: cart }, orderHeaders());
  }
  const ob = json(r);
  ok('order accepted', r.status === 201 && ob.accepted === true && present(ob.id));
}

// Business work endpoints (not part of checkout). Scheduled 429 honours
// Retry-After and is retried at most 4 times.
function work(path) {
  if (!csrf && !login()) return;
  let r = send('POST', path, {}, {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    const wait = Number(header(r, 'Retry-After'));
    sleep(wait > 0 ? wait : 1);
    r = send('POST', path, {}, {});
  }
  const scheduled = r.status === 429 && header(r, 'Retry-After') !== '';
  ok(path + ' completed or scheduled', (r.status === 200 && json(r).ok === true) || scheduled);
}

export default function () {
  journey();
}

export function checkout() {
  journey();
}

export function browse() {
  work('/v2/browse');
}

export function workload() {
  work('/v2/work');
}
