            raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        if CFG.get('workload'):
            users = CFG.get('max_vus', 64 if CFG.get('capacity') or CFG.get('pools') else 32)
            return None if self.get_run_time() >= DURATION + 5 else (users, max(1, users))
        users = CFG.get('users', 2)
        if self.first_tick:
            self.first_tick = False
            return users, max(1, users)
        remaining = users - FINISHED[0]
        if remaining <= 0:
            return None
        return remaining, max(1, remaining)
