                    and response.elapsed.total_seconds() * 1000 > CHECKOUT_THRESHOLD_MS):
                allowed = False
                reason = 'checkout latency above %dms threshold' % CHECKOUT_THRESHOLD_MS
            if allowed:
                response.success()
            else:
                response.failure(reason)
                self.environment.process_exit_code = FAILURE_EXIT_CODE
            if body.get('csrf'):
                self.csrf = body['csrf']
            return response, body

    def login(self):
