        form, _ = self.raw('/v2/login-form')
        token = re.search(
            r'<input(?=[^>]*\sname=["\']csrf["\'])(?=[^>]*\svalue=["\']([^"\']+)["\'])[^>]*>',
            form.text, re.IGNORECASE)
        if not token:
            self.environment.process_exit_code = FAILURE_EXIT_CODE
            return
        response, body = self.raw('/v2/login', 'POST',
