import itertools
import os
import re
import time

from gevent import sleep
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

# Timeline in seconds from launch. T0 is the first authenticated POST /v2/work, within 10 s of launch.
TARGET_RATE = 5.0                              # operations per second
WARMUP = 5                                     # unscored lead-in
SCORED = 30                                    # six 5 s windows: [T0+5, T0+35)
DRAIN = 5                                      # in-flight drain after the last scheduled arrival
ARRIVAL_END = WARMUP + SCORED                  # arrivals are scheduled in [0, 35)
STOP_AT = ARRIVAL_END + DRAIN                  # shape stops at 40 s
TOTAL_ARRIVALS = int(TARGET_RATE * ARRIVAL_END)  # 175 arrivals, 150 inside the scored window

# One virtual user per bench account. Each user serializes its own arrivals, so 5/s at a
# ~0.2 s server delay needs more than one user. 16 users gives headroom for 3x target and
# stays under the 32 concurrent-user cap.
USERS = 16
ACCOUNTS = 16
PASSWORD = 'bench'
WORK_PATH = '/v2/work'
MAX_429_RETRIES = 4


class ArrivalClock:
    """Hands out arrival slots at a fixed rate. Slot k is due at started + k / TARGET_RATE."""

    def __init__(self):
        self.lock = Semaphore()
        self.issued = 0
        self.started = None

    def claim(self):
        with self.lock:
            if self.issued >= TOTAL_ARRIVALS:
                return False
            if self.started is None:
                self.started = time.monotonic()
            deadline = self.started + self.issued / TARGET_RATE
            self.issued += 1
        delay = deadline - time.monotonic()
        if delay > 0:
            sleep(delay)
        return True


CLOCK = ArrivalClock()
_SEQ = itertools.count(1)


def _attr(tag, attr):
    match = re.search(
        r'(?<![\w-])%s\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+))' % attr,
        tag, re.IGNORECASE)
    if not match:
        return None
    return next(group for group in match.groups() if group is not None)


def csrf_from_form(html):
    html = re.sub(r'<!--.*?-->', '', html, flags=re.S)
    for tag in re.findall(r'<input\b[^>]*>', html, re.IGNORECASE):
        if _attr(tag, 'name') == 'csrf':
            value = _attr(tag, 'value')
            if value:
                return value
    return None


def retry_after(response):
    try:
        return max(0.0, float(response.headers.get('Retry-After', 1)))
    except (TypeError, ValueError):
        return 1.0


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = constant(0)

    def on_start(self):
        number = next(_SEQ)
        self.username = 'bench-%d' % ((number - 1) % ACCOUNTS + 1)
        self.csrf = ''

    def send(self, method, path, data=None, headers=None):
        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})
        with self.client.request(method, path, json=data, headers=request_headers,
                                 catch_response=True, allow_redirects=False,
                                 timeout=3) as response:
            status = response.status_code
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}
            error = body.get('error')
            # Expected expiry (expired or revoked session) is not a failure.
            expired = status == 401 and error in ('expired', 'session')
            if path == WORK_PATH and method == 'POST':
                # Scheduled 429 is expected. A 200 counts only with ok:true.
                allowed = ((status == 200 and body.get('ok') is True)
                           or status == 429 or expired)
            else:
                allowed = status < 400 or expired
            if allowed:
                response.success()
            else:
                response.failure('%s %s -> %s %s' % (method, path, status, error or ''))
            if status < 400 and body.get('csrf'):
                self.csrf = body['csrf']
            return response, body

    def call(self, method, path, data=None):
        response, body = self.send(method, path, data)
        if response.status_code == 401 and body.get('error') in ('expired', 'session'):
            # One recovery per operation, then one retry of the interrupted call.
            if self.recover():
                response, body = self.send(method, path, data)
        return response, body

    def recover(self):
        renewed, _ = self.send('POST', '/v2/session/renew', {})
        if renewed.status_code == 200:
            return True
        return self.login()

    def login(self):
        self.csrf = ''
        form, _ = self.send('GET', '/v2/login-form')
        token = csrf_from_form(form.text)
        if not token:
            return False
        response, _ = self.send('POST', '/v2/login',
                                {'username': self.username, 'password': PASSWORD,
                                 'csrf': token})
        if response.status_code == 302:
            location = response.headers.get('Location')
            if not location:
                return False
            # Follow the dynamic Location exactly once.
            response, _ = self.send('GET', location)
        return response.status_code == 200 and bool(self.csrf)

    def work(self):
        if not self.csrf and not self.login():
            return
        for attempt in range(MAX_429_RETRIES + 1):
            response, _ = self.call('POST', WORK_PATH, {})
            if response.status_code != 429:
                return
            if attempt < MAX_429_RETRIES:
                sleep(retry_after(response))

    @task
    def work_arrival(self):
        if not CLOCK.claim():
            raise StopUser()
        self.work()


class ShopShape(LoadTestShape):
    def tick(self):
        if self.get_run_time() >= STOP_AT:
            return None
        return USERS, USERS
