    // Fixture rows: accounts.json (JSON variant) or account-N.csv (CSV variant), read via Gatling feeders.
    private static List<Map<String, Object>> fixtureRows() {
        List<Map<String, Object>> rows = new ArrayList<>();
        try {
            for (Map<String, ?> record : jsonFile("/fixtures/accounts.json").readRecords()) {
                rows.add(new HashMap<String, Object>(record));
