        int units = 2;
        try {
            units = Integer.parseInt(String.valueOf(quantity).trim());
        } catch (RuntimeException ignored) {
            units = 2;
        }
        Map<String, Object> entry = new HashMap<>();
        entry.put("username", username);
        entry.put("password", password);
        entry.put("quantity", Math.max(1, Math.min(20, units)));
        return entry;
    }

    // Distinct pool: fixture rows first, then documented bench-N accounts (password bench), no duplicates.
    private static List<Map<String, Object>> accountPool() {
        List<Map<String, Object>> pool = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (Map<String, Object> row : fixtureRows()) {
            Object name = row.get("username");
            if (name == null) {
                continue;
            }
            String username = String.valueOf(name).trim();
            if (username.isEmpty() || !seen.add(username)) {
                continue;
            }
            pool.add(account(username, String.valueOf(row.getOrDefault("password", "bench")), row.get("quantity")));
        }
        for (int index = 1; pool.size() < USERS * ITERATIONS && index <= 16; index++) {
            String username = "bench-" + index;
            if (seen.add(username)) {
                pool.add(account(username, "bench", null));
            }
        }
        if (pool.size() < USERS * ITERATIONS) {
            throw new IllegalStateException("Not enough distinct accounts for partitioned journeys");
