```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = { users: 2, iterations: 2, mode: 'partition' };
const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const FIXTURE_ACCOUNTS = '/fixtures/accounts.json'; // read-only alias of r10-accounts.json
const REQUIRED = cfg.users * cfg.iterations;
const failure = new Rate('business_failure');

function parse(r) {
  try {
    const v = r.json();
    return v && typeof v === 'object' ? v : {};
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  const h = r.headers || {};
  const want = name.toLowerCase();
  const keys = Object.keys(h);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return h[keys[i]];
  }
  return undefined;
}

// Build a pool of distinct accounts: fixture rows first, then protocol accounts bench-N (password bench).
function loadAccounts() {
  let rows = [];
  try {
    const parsed = JSON.parse(open(FIXTURE_ACCOUNTS));
    if (Array.isArray(parsed)) rows = parsed;
  } catch (_) {
    rows = [];
  }
  const pool = [];
  const seen = {};
  const add = (row) => {
    if (!row || typeof row.username !== 'string' || typeof row.password !== 'string') return;
    if (seen[row.username]) return;
    seen[row.username] = true;
    pool.push({ username: row.username, password: row.password, delay: Number(row.delay) || 0 });
  };
  rows.forEach(add);
  for (let k = 1; k <= 16 && pool.length < REQUIRED; k++) {
    add({ username: 'bench-' + k, password: 'bench', delay: 0 });
  }
  return pool;
}

const ACCOUNTS = loadAccounts();
if (ACCOUNTS.length < REQUIRED) {
  throw new Error('insufficient distinct accounts: need ' + REQUIRED + ', have ' + ACCOUNTS.length);
}

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

// Per-journey state. Each journey pins one account, one cookie jar and one cart.
let account = null;
let csrf = '';
let cartId = '';
let jar = null;

// Exclusive partition: slot is unique per (VU, iteration) across the whole run.
function accountFor(vu, iter) {
  const slot = iter * cfg.users + (vu - 1);
  return ACCOUNTS[slot];
}

function raw(path, method, data, extra) {
  const url = path.indexOf('http') === 0 ? path : BASE + path;
  if (url.indexOf(BASE) !== 0) {
    throw new Error('non-target url: ' + url);
  }
  const headers = Object.assign({}, extra || {});
  if (data !== null && data !== undefined) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && csrf) headers['X-CSRF-Token'] = csrf;
  const params = { headers: headers, redirects: 0, timeout: '3s' };
  if (jar) params.jar = jar;
  const r = http.request(method, url, data === null || data === undefined ? null : JSON.stringify(data), params);
  const b = parse(r);
  if (r.status < 400 && b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    const unexpected = r.status >= 500 ||
      (r.status >= 400 && r.status !== 429 && !(r.status === 401 && b.error === 'expired'));
    failure.add(unexpected);
  }
  return r;
}

function formToken(r) {
  const inputs = r.html().find('input[name="csrf"]');
  for (let i = 0; i < inputs.size(); i++) {
    const v = inputs.eq(i).attr('value');
    if (v) return v;
  }
  return '';
}

function login() {
  csrf = '';
  let r = raw('/v2/login-form', 'GET', null, {});
  const token = formToken(r);
  r = raw('/v2/login', 'POST', { username: account.username, password: account.password, csrf: token }, {});
  if (r.status === 302) {
    const loc = header(r, 'Location');
    if (loc) r = raw(loc, 'GET', null, {}); // dynamic Location fetched exactly once
  }
  check(r, { 'login': (x) => x.status === 200 });
  return r.status === 200;
}

function authFailure(r) {
  if (r.status !== 401) return null;
  const e = parse(r).error;
  return (e === 'expired' || e === 'session') ? e : null;
}

// One bounded recovery per operation: renew (or re-login), recover cart, retry once.
// error=denied is not treated as expiry and is returned to the caller for assertion.
function request(path, method, data, extra) {
  const r = raw(path, method, data, extra);
  if (authFailure(r) === null) return r;
  const renewed = raw('/v2/session/renew', 'POST', {}, {});
  if (renewed.status !== 200) {
    if (!login()) return r;
  }
  if (cartId) raw('/v2/carts/' + cartId + '/recover', 'POST', {}, {});
  return raw(path, method, data, extra);
}

function journey(acct) {
  account = acct;
  csrf = '';
  cartId = '';
  jar = new http.CookieJar();

  if (account.delay > 0) sleep(account.delay / 1000);

  if (!login()) return;

  // Catalog discovery: never guess cursors; follow server-provided next, at most 3 pages.
  let page = '/v2/catalog';
  let product = null;
  for (let n = 0; n < 3 && page && !product; n++) {
    const r = request(page, 'GET', null, {});
    const b = parse(r);
    const products = (b.data && Array.isArray(b.data.products)) ? b.data.products : [];
    product = products.find((p) => (p.variants || []).some((v) => v.in_stock)) || null;
    page = b.next || null;
  }
  if (!product) {
    check(null, { 'eligible product': () => false });
    return;
  }
  const variant = product.variants.find((v) => v.in_stock);

  // Exactly one cart per journey.
  const cr = request('/v2/carts', 'POST', { product_id: product.id, variant_id: variant.id }, {});
  const cb = parse(cr);
  check(cr, { 'cart': (x) => x.status === 201 && !!cb.id });
  if (cr.status !== 201 || !cb.id) return;
  cartId = cb.id;

  // Fresh ETag before ordering.
  const gr = request('/v2/carts/' + cartId, 'GET', null, {});
  check(gr, { 'cart read': (x) => x.status === 200 });
  let etag = header(gr, 'ETag');

  const orderHeaders = { 'Idempotency-Key': 'order-' + cartId };
  if (etag) orderHeaders['If-Match'] = etag;
  let r = request('/v2/orders', 'POST', { cart_id: cartId }, orderHeaders);

  // Precondition failure: re-read the cart and retry the same payload once.
  if (r.status === 412) {
    const again = request('/v2/carts/' + cartId, 'GET', null, {});
    etag = header(again, 'ETag');
    if (etag) orderHeaders['If-Match'] = etag;
    r = request('/v2/orders', 'POST', { cart_id: cartId }, orderHeaders);
  }

  const ob = parse(r);
  check(r, { 'order accepted': (x) => x.status === 201 && ob.accepted === true });
}

export default function () {
  const acct = accountFor(__VU, __ITER);
  journey(acct);
}
