import itertools
import json
import os
import re

from gevent.event import Event
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

CFG = {'users': 2, 'iterations': 2, 'mode': 'partition'}
USERS = int(CFG['users'])
ITERATIONS = int(CFG['iterations'])
FAIL_EXIT = 99
PASSWORD = 'bench'
SHARED_ACCOUNT = 'bench'
NO_EXPECTED = frozenset()
RECOVERABLE = frozenset({(401, 'expired'), (401, 'session')})
ETAG_RETRY = frozenset({(412, 'etag'), (412, 'etag_conflict')})

with open('/fixtures/accounts.json', encoding='utf-8') as accounts_file:
    ROWS = json.load(accounts_file)
if not isinstance(ROWS, list):
    raise ValueError('accounts fixture must be a list of account rows')


def build_pool(rows, needed):
    pool = []
    seen = set()

    def add(username, password):
        if not username or username == SHARED_ACCOUNT or username in seen:
            return
        seen.add(username)
        pool.append({'username': username, 'password': password})

    for row in rows:
        if not isinstance(row, dict) or not row.get('username'):
            raise ValueError('malformed account row')
        add(str(row['username']), str(row.get('password') or PASSWORD))
    for number in range(1, 17):
        if len(pool) >= needed:
            break
        add('bench-%d' % number, PASSWORD)
    if len(pool) < needed:
        raise ValueError('not enough exclusive accounts for partition')
    return pool


POOL = build_pool(ROWS, USERS * ITERATIONS)
PARTITIONS = {}
for _user_no in range(1, USERS + 1):
    PARTITIONS[_user_no] = POOL[(_user_no - 1) * ITERATIONS: _user_no * ITERATIONS]
ALL_USERNAMES = [acct['username'] for part in PARTITIONS.values() for acct in part]
if len(ALL_USERNAMES) != USERS * ITERATIONS or len(set(ALL_USERNAMES)) != len(ALL_USERNAMES):
    raise ValueError('account partitions are not disjoint')

USER_SEQ = itertools.count(1)
START = {'count': 0, 'ready': Event()}

COMMENT_RE = re.compile(r'<!--.*?-->|<script\b.*?</script>|<style\b.*?</style>',
                        re.IGNORECASE | re.DOTALL)
INPUT_RE = re.compile(r'<input\b[^>]*>', re.IGNORECASE)
ATTR_RE = re.compile(r'(?<![\w-])([\w:-]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\')')


def input_value(html, field):
    markup = COMMENT_RE.sub('', html or '')
    for tag in INPUT_RE.findall(markup):
        attrs = {}
        for match in ATTR_RE.finditer(tag):
            key = match.group(1).lower()
            value = match.group(2) if match.group(2) is not None else match.group(3)
            attrs.setdefault(key, value)
        if attrs.get('name') == field and attrs.get('value'):
            return attrs['value']
    return None


def error_of(body):
    error = body.get('error')
    return error if isinstance(error, str) else None


class MatrixUser(HttpUser):
    host = os.environ.get('BASE_URL', 'http://127.0.0.1:8000')
    wait_time = constant(0)

    def on_start(self):
        self.user_no = next(USER_SEQ)
        if self.user_no > USERS:
            self.environment.process_exit_code = FAIL_EXIT
            raise StopUser()
        self.accounts = PARTITIONS[self.user_no]
        self.iteration = 0
        self.username = ''
        self.password = ''
        self.csrf = ''
        self.cart = ''
        self.etag = ''

    def raw(self, path, method='GET', data=None, headers=None, name=None, expected=NO_EXPECTED):
        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})
        with self.client.request(method, path, json=data, headers=request_headers,
                                 name=name, catch_response=True,
                                 allow_redirects=False, timeout=3) as response:
            body = {}
            try:
                parsed = response.json()
                if isinstance(parsed, dict):
                    body = parsed
            except ValueError:
                pass
            status = response.status_code
            allowed = status < 400 or (status, error_of(body)) in expected
            if (method == 'POST' and path.split('?', 1)[0] == '/v2/orders'
                    and status < 400 and body.get('accepted') is not True):
                allowed = False
            if allowed:
                response.success()
            else:
                response.failure('request assertion failed')
                self.environment.process_exit_code = FAIL_EXIT
            if body.get('csrf'):
                self.csrf = str(body['csrf'])
        return response, body

    def login(self):
        self.csrf = ''
        form, _ = self.raw('/v2/login-form', name='/v2/login-form')
        token = input_value(form.text, 'csrf')
        if not token:
            self.environment.process_exit_code = FAIL_EXIT
            return False
        response, body = self.raw('/v2/login', 'POST',
                                  {'username': self.username,
                                   'password': self.password,
                                   'csrf': token},
                                  name='/v2/login')
        if response.status_code == 302:
            location = response.headers.get('Location')
            if not location:
                self.environment.process_exit_code = FAIL_EXIT
                return False
            _, body = self.raw(location, name='login-redirect')
        user = body.get('user')
        if not self.csrf or (user is not None and user != self.username):
            self.csrf = ''
            self.environment.process_exit_code = FAIL_EXIT
            return False
        return True

    def recover(self):
        renewed, body = self.raw('/v2/session/renew', 'POST', {},
                                 name='/v2/session/renew', expected=RECOVERABLE)
        if renewed.status_code != 200 or not body.get('csrf'):
            if not self.login():
                return False
        if self.cart:
            response, _ = self.raw('/v2/carts/%s/recover' % self.cart, 'POST', {},
                                   name='/v2/carts/[id]/recover', expected=RECOVERABLE)
            self.etag = response.headers.get('ETag', self.etag)
        return True

    def refresh_cart(self):
        if self.cart:
            response, _ = self.raw('/v2/carts/%s' % self.cart, name='/v2/carts/[id]')
            self.etag = response.headers.get('ETag', self.etag)

    def send(self, path, method='GET', data=None, name=None, headers_factory=None,
             etag_retry=False):
        expected = (RECOVERABLE | ETAG_RETRY) if etag_retry else RECOVERABLE

        def build_headers():
            return headers_factory() if headers_factory else None

        response, body = self.raw(path, method, data, build_headers(), name, expected)
