            for product in products:
                variant = next((item for item in product.get('variants', [])
                                if item.get('in_stock')), None)
                if variant:
                    return product, variant
            nxt = body.get('next')
            if not isinstance(nxt, str) or not nxt:
                break
            page = nxt
        return None, None

    def wait_for_peers(self):
        START['count'] += 1
        if START['count'] >= USERS:
            START['ready'].set()
