            return
        response, body = self.send('/v2/carts', 'POST',
                                   {'product_id': product['id'],
                                    'variant_id': variant['id']},
                                   '/v2/carts')
        self.cart = str(body.get('id') or '')
        self.etag = response.headers.get('ETag', '')
        if not self.cart:
