    def run_journey(self):
        if self.iteration >= ITERATIONS:
            raise StopUser()
        try:
            self.journey()
        except StopUser:
            raise
        except Exception:
            self.environment.process_exit_code = FAIL_EXIT
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


