import itertools
import os
import re

from gevent import sleep
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

CFG = {'users': 2, 'iterations': 2, 'mode': 'errors'}
USERS = int(CFG.get('users', 2))
ITERATIONS = int(CFG.get('iterations', 2))
WORK_OPS_PER_ITERATION = 4
MAX_RETRIES = 4
RETRY_AFTER = 1.0
TIMEOUT = 3

LOGIN_FORM = '/v2/login-form'
LOGIN = '/v2/login'
RENEW = '/v2/session/renew'
WORK = '/v2/work'
REDIRECT_NAME = '/v2/login [redirect]'

OK = 'ok'
EXPECTED = 'expected'
FAIL = 'fail'
SESSION_ERRORS = ('expired', 'session')

COMMENT_RE = re.compile(r'<!--.*?-->', re.S)
BLOCK_RE = re.compile(r'<(script|style|textarea|template|noscript)\b.*?</\1\s*>', re.S | re.I)
INPUT_RE = re.compile(r'<input\b[^>]*>', re.I)
ATTR_RE = re.compile(r'([\w:.-]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+))')

_SEQ = itertools.count(1)


def find_csrf(html):
    html = BLOCK_RE.sub('', COMMENT_RE.sub('', html or ''))
    for tag in INPUT_RE.findall(html):
        attrs = {}
        for key, dq, sq, bare in ATTR_RE.findall(tag):
            attrs.setdefault(key.lower(), dq or sq or bare)
        if attrs.get('name') == 'csrf' and attrs.get('value'):
            return attrs['value']
    return ''


def parse_body(response):
    try:
        body = response.json()
    except ValueError:
        return {}
    return body if isinstance(body, dict) else {}


def scheduled_429(response):
    try:
        return float(response.headers.get('Retry-After', '')) == RETRY_AFTER
    except ValueError:
        return False


def judge_form(response, body):
    if response.status_code == 200 and find_csrf(response.text):
        return OK, ''
    return FAIL, 'login form missing csrf input (status %s)' % response.status_code


def judge_login(response, body):
    if response.status_code == 302 and response.headers.get('Location'):
        return OK, ''
    if response.status_code == 200 and body.get('csrf'):
        return OK, ''
    return FAIL, 'login rejected (status %s)' % response.status_code


def judge_redirect(response, body):
    if response.status_code == 200:
        return OK, ''
    return FAIL, 'login redirect failed (status %s)' % response.status_code


def judge_renew(response, body):
    if response.status_code == 200:
        return OK, ''
    if response.status_code == 401 and body.get('error') in SESSION_ERRORS:
        # Expected recovery path: renew may fail, caller logs in again.
        return EXPECTED, ''
    return FAIL, 'renew failed (status %s error %s)' % (response.status_code, body.get('error'))


def judge_work(can_recover, can_retry):
    def judge(response, body):
        status = response.status_code
        if status == 200 and body.get('ok') is True:
            return OK, ''
        if status == 401 and body.get('error') == 'expired' and can_recover:
            return EXPECTED, ''
        if status == 429 and can_retry and scheduled_429(response):
            return EXPECTED, ''
        return FAIL, 'unexpected /v2/work status %s error %s' % (status, body.get('error'))
    return judge


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = constant(0)

    def on_start(self):
        number = next(_SEQ)
        self.username = 'bench-%d' % ((number - 1) % 16 + 1)
        self.password = 'bench'
        self.csrf = ''
        self.iterations_done = 0

    def call(self, method, path, data=None, name=None, judge=None):
        headers = {'Content-Type': 'application/json'}
        if self.csrf:
            headers['X-CSRF-Token'] = self.csrf
        with self.client.request(method, path, json=data, headers=headers,
                                 name=name or path, catch_response=True,
                                 allow_redirects=False, timeout=TIMEOUT) as response:
            body = parse_body(response)
            verdict, reason = judge(response, body)
            if verdict == FAIL:
                response.failure(reason or 'unexpected response')
            else:
                response.success()
            if body.get('csrf'):
                self.csrf = body['csrf']
        return response, body, verdict

    def login(self):
        self.csrf = ''
        form, _, verdict = self.call('GET', LOGIN_FORM, name=LOGIN_FORM, judge=judge_form)
        token = find_csrf(form.text)
        if verdict != OK or not token:
            return False
        response, _, verdict = self.call(
            'POST', LOGIN,
            {'username': self.username, 'password': self.password, 'csrf': token},
            name=LOGIN, judge=judge_login)
        if verdict != OK:
            return False
        if response.status_code == 302:
            location = response.headers.get('Location')
            _, _, verdict = self.call('GET', location, name=REDIRECT_NAME, judge=judge_redirect)
            return verdict == OK
        return True

    def renew(self):
        _, _, verdict = self.call('POST', RENEW, {}, name=RENEW, judge=judge_renew)
        if verdict != OK:
            self.login()

    def work(self):
        recovered = False
        retries = 0
        while True:
            response, body, verdict = self.call(
                'POST', WORK, {}, name=WORK,
                judge=judge_work(not recovered, retries < MAX_RETRIES))
            if verdict == OK:
                return
            error = body.get('error')
            if response.status_code == 401 and error in SESSION_ERRORS and not recovered:
                # Bounded: one recovery per work operation, then retry it once.
                recovered = True
                self.renew()
                continue
            if verdict == EXPECTED and response.status_code == 429:
                retries += 1
                sleep(RETRY_AFTER)
                continue
            return

    @task
    def run_iteration(self):
        self.login()
        for _ in range(WORK_OPS_PER_ITERATION):
            self.work()
        self.iterations_done += 1
        if self.iterations_done >= ITERATIONS:
            raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.spawned = False

    def tick(self):
        if not self.spawned:
            self.spawned = True
            return USERS, USERS
        running = self.runner.user_count if self.runner else 0
        if running == 0:
            return None
        # Hold the target at the current live count so finished users are not respawned.
        return running, USERS
