```javascript
// k6 1.0.0 - POST /v2/work pool at 5 operation starts/s over a 35s scenario
// (5s warmup + 30s scored window, drain capped by gracefulStop=5s).
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Counter } from 'k6/metrics';
import { parseHTML } from 'k6/html';
import exec from 'k6/execution';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';
const TARGET_RATE = 5;
const WARMUP_S = 5;
const SCORE_S = 30;
const MAX_429_RETRIES = 4;
const MAX_RECOVERIES = 1;

const ACCOUNTS = [];
for (let i = 1; i <= 16; i++) {
  ACCOUNTS.push('bench-' + i);
}
ACCOUNTS.push('bench');

// Statuses that are expected by this protocol and must not trip http_req_failed.
const EXPECTED = http.expectedStatuses({ min: 200, max: 399 }, 401, 429);

// One point per raw /v2/work response.
// true = unexpected failure; expected expiry and scheduled 429 are false.
const businessFailure = new Rate('business_failure');
const workSucceeded = new Counter('work_succeeded');
const workScheduled429 = new Counter('work_scheduled_429');
const sessionRenewals = new Counter('session_renewals');
const sessionRelogins = new Counter('session_relogins');
const workDropped = new Counter('work_dropped');

export const options = {
  scenarios: {
    work_pool: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: (WARMUP_S + SCORE_S) + 's',
      preAllocatedVUs: 8,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    http_req_failed: ['rate<0.01'],
    business_failure: ['rate<=0.01'],
    work_dropped: ['count<=1'],
    dropped_iterations: ['count<=1'],
  },
};

function jsonOf(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function header(res, name) {
  const h = res.headers || {};
  return h[name] || h[name.toLowerCase()] || '';
}

// Resolve a Location header against BASE only. Off-target locations are rejected.
function resolveLocation(loc) {
  if (!loc) {
    return null;
  }
  if (loc.indexOf('://') >= 0) {
    if (loc === BASE || loc.indexOf(BASE + '/') === 0) {
      return loc;
    }
    return null;
  }
  return BASE + (loc.charAt(0) === '/' ? '' : '/') + loc;
}

function retryAfterSeconds(res) {
  const n = parseFloat(header(res, 'Retry-After'));
  if (!isFinite(n) || n <= 0) {
    return 1;
  }
  return Math.min(n, 2);
}

// Fresh login for one account. Returns the CSRF token string, or null on failure.
function login(account) {
  const form = http.get(BASE + '/v2/login-form', {
    redirects: 0,
    responseCallback: EXPECTED,
    tags: { name: 'login-form' },
  });
  if (form.status !== 200) {
    return null;
  }

  const doc = parseHTML(form.body);
  const inputs = doc.find('input[name="csrf"]');
  let formCsrf = null;
  for (let i = 0; i < inputs.size(); i++) {
    const v = inputs.eq(i).attr('value');
    if (v) {
      formCsrf = v;
      break;
    }
  }
  if (!formCsrf) {
    return null;
  }

  const res = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: account, password: PASSWORD, csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      responseCallback: EXPECTED,
      tags: { name: 'login' },
    }
  );

  let body = null;
  if (res.status === 302) {
    const target = resolveLocation(header(res, 'Location'));
    if (!target) {
      return null;
    }
    // Follow the dynamic Location exactly once.
    const loc = http.get(target, {
      redirects: 0,
      responseCallback: EXPECTED,
      tags: { name: 'login-location' },
    });
    if (loc.status !== 200) {
      return null;
    }
    body = jsonOf(loc);
  } else if (res.status === 200) {
    body = jsonOf(res);
  } else {
    return null;
  }

  const ok = check(res, {
    'login accepted': (r) => r.status === 200 || r.status === 302,
  });
  if (!ok) {
    return null;
  }

  // Retain the form token if the response does not provide a fresh one.
  if (body && body.csrf) {
    return body.csrf;
  }
  return formCsrf;
}

function renewSession(session) {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': session.csrf,
    },
    redirects: 0,
    responseCallback: EXPECTED,
    tags: { name: 'session-renew' },
  });
  if (res.status !== 200) {
    return false;
  }
  const b = jsonOf(res);
  if (b && b.csrf) {
    session.csrf = b.csrf;
  }
  sessionRenewals.add(1);
  return true;
}

function relogin(session) {
  const csrf = login(session.account);
  if (!csrf) {
    return false;
  }
  session.csrf = csrf;
  sessionRelogins.add(1);
  return true;
}

// One work operation with bounded 429 retries and one recovery per operation.
function runWorkOperation(session) {
  let retries429 = 0;
  let recoveries = 0;

  for (;;) {
    const res = http.post(BASE + '/v2/work', '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': session.csrf,
      },
      redirects: 0,
      responseCallback: EXPECTED,
      tags: { name: 'work' },
    });
    const b = jsonOf(res);
    const err = b && typeof b.error === 'string' ? b.error : '';

    if (res.status === 200 && b && b.ok === true) {
      businessFailure.add(false);
      workSucceeded.add(1);
      check(res, { 'work accepted': () => true });
      return true;
    }

    if (res.status === 429) {
      if (retries429 >= MAX_429_RETRIES) {
        // Exhausted scheduled retries: the operation did not complete.
        businessFailure.add(true);
        workDropped.add(1);
        check(res, { 'work retries exhausted': () => false });
        return false;
      }
      // Scheduled 429 is expected: in denominator, not in numerator.
      businessFailure.add(false);
      workScheduled429.add(1);
      retries429++;
      sleep(retryAfterSeconds(res));
      continue;
    }

    if (res.status === 401 && err === 'expired' && recoveries < MAX_RECOVERIES) {
      // Expected expiry: in denominator, not in numerator.
      businessFailure.add(false);
      recoveries++;
      let recovered = renewSession(session);
      if (!recovered) {
        recovered = relogin(session);
      }
      if (!recovered) {
        workDropped.add(1);
        return false;
      }
      continue;
    }

    if (res.status === 401 && err === 'session' && recoveries < MAX_RECOVERIES) {
      // Revoked session: renew is not attempted, fresh login is used instead.
      businessFailure.add(false);
      recoveries++;
      if (!relogin(session)) {
        workDropped.add(1);
        return false;
      }
      continue;
    }

    // Unexpected: 401 denied, 401 after recovery, 500, 200 with ok false, other statuses.
    businessFailure.add(true);
    workDropped.add(1);
    check(res, { 'work expected outcome': () => false });
    return false;
  }
}

export default function () {
  // Each journey starts with a fresh login. Accounts rotate by iteration so
  // the same account is not logged in concurrently by overlapping iterations.
  const account = ACCOUNTS[exec.scenario.iterationInTest % ACCOUNTS.length];

  let csrf = null;
  for (let attempt = 0; attempt < 2 && !csrf; attempt++) {
    csrf = login(account);
  }
  if (!csrf) {
    workDropped.add(1);
    return;
  }

  runWorkOperation({ account: account, csrf: csrf });
}
