import html as html_lib
import os
import re
import time
from urllib.parse import urljoin, urlparse

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

BASE_URL = os.environ["BASE_URL"].rstrip("/")
_BASE = urlparse(BASE_URL)

RATE = 5.0                      # work starts per second
INTERVAL = 1.0 / RATE           # 0.2 s slot grid
WARMUP = 5.0
SCORE = 30.0
WINDOW_END = WARMUP + SCORE     # relative to T0: stop starting work at T0+35
DRAIN_END = WINDOW_END + 5.0    # relative to T0: end run at T0+40
ANCHOR_DEADLINE = 10.0          # T0 must be anchored within 10 s of launch
USERS = 16                      # <= 32 max concurrent virtual users
ACCOUNTS = [f"bench-{i}" for i in range(1, 17)]
PASSWORD = "bench"
MAX_THROTTLE_RETRIES = 4

_STATE = {"t0": None, "next_slot": None, "seq": 0}

_INPUT_RE = re.compile(r"<input\b([^>]*)>", re.I | re.S)
_ATTR_RE = re.compile(r"([^\s=/>\"']+)\s*(?:=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s\"'>]+)))?")
_COMMENT_RE = re.compile(r"<!--.*?-->", re.S)


def _extract_csrf(page):
    page = _COMMENT_RE.sub("", page or "")
    for m in _INPUT_RE.finditer(page):
        attrs = {}
        for a in _ATTR_RE.finditer(m.group(1)):
            name = a.group(1).lower()
            value = next((g for g in a.groups()[1:] if g is not None), "")
            attrs.setdefault(name, html_lib.unescape(value))
        if attrs.get("name") == "csrf" and attrs.get("value"):
            return attrs["value"]
    return None


def _json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def _retry_after(resp):
    raw = resp.headers.get("Retry-After")
    try:
        return float(raw)
    except (TypeError, ValueError):
        return 1.0


def _same_origin(location):
    if not location:
        return None
    absolute = urljoin(BASE_URL + "/", location)
    parsed = urlparse(absolute)
    if parsed.scheme != _BASE.scheme or parsed.netloc != _BASE.netloc:
        return None
    return absolute


def _past_window():
    t0 = _STATE["t0"]
    return t0 is not None and time.monotonic() >= t0 + WINDOW_END


def _reserve_delay():
    """Global 5/s slot grid (0.2 s spacing), FIFO by reservation order."""
    now = time.monotonic()
    nxt = _STATE["next_slot"]
    if nxt is None:
        nxt = now
    slot = max(nxt, now)
    _STATE["next_slot"] = slot + INTERVAL
    return slot - now


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def __init__(self, environment, *args, **kwargs):
        super().__init__(environment, *args, **kwargs)
        idx = _STATE["seq"] % len(ACCOUNTS)
        _STATE["seq"] += 1
        self.username = ACCOUNTS[idx]
        self.csrf = ""
        self.authed = False

    # ---------- authentication ----------

    def _login(self):
        self.authed = False
        token = None
        with self.client.get(
            "/v2/login-form",
            name="GET /v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return False
            token = _extract_csrf(r.text)
            if not token:
                r.failure("login csrf input not found")
                return False
            r.success()

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": token},
            headers={"X-CSRF-Token": token},
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                location = _same_origin(r.headers.get("Location", ""))
                if location is None:
                    r.failure("login redirect to foreign or missing location")
                    return False
                r.success()
                with self.client.get(
                    location,
                    name="GET login redirect",
                    catch_response=True,
                    allow_redirects=False,
                ) as g:
                    if g.status_code >= 400:
                        g.failure(f"login redirect status {g.status_code}")
                        return False
                    body = _json(g)
                    if isinstance(body, dict) and body.get("csrf"):
                        token = body["csrf"]
                    g.success()
            elif r.status_code == 200:
                body = _json(r)
                if not isinstance(body, dict) or not body.get("csrf"):
                    r.failure("login response missing csrf")
                    return False
                token = body["csrf"]
                r.success()
            else:
                r.failure(f"login status {r.status_code}")
                return False

        self.csrf = token
        self.authed = True
        return True

    def _renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/session/renew",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            body = _json(r)
            if r.status_code == 200 and isinstance(body, dict) and body.get("csrf"):
                self.csrf = body["csrf"]
                r.success()
                return True
            r.failure(f"renew status {r.status_code}")
            return False

    # ---------- pool operation: POST /v2/work ----------

    def _absorb(self, body):
        if isinstance(body, dict) and body.get("csrf"):
            self.csrf = body["csrf"]

    def _post_work(self):
        with self.client.post(
            "/v2/work",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/work",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            body = _json(r)
            if r.status_code == 200 and isinstance(body, dict) and body.get("ok") is True:
                self._absorb(body)
                r.success()
                return "ok", 0.0
            if r.status_code == 429:
                # scheduled throttle: expected, not a failure
                r.success()
                return "throttled", _retry_after(r)
            if r.status_code == 401:
                err = body.get("error") if isinstance(body, dict) else None
                if err == "expired":
                    r.success()
                    return "expired", 0.0
                if err == "session":
                    r.success()
                    return "revoked", 0.0
                r.failure(f"401 error={err}")
                return "fail", 0.0
            r.failure(f"unexpected work status {r.status_code}")
            return "fail", 0.0

    def _run_work(self):
        throttles = 0
        renewed = False
        relogged = False
        while True:
            outcome, delay = self._post_work()
            if outcome == "ok":
                return True
            if outcome == "throttled":
                throttles += 1
                if throttles > MAX_THROTTLE_RETRIES:
                    return False
                time.sleep(max(0.0, delay))
                continue
            if outcome == "expired" and not renewed:
                renewed = True
                if self._renew():
                    continue
                if relogged:
                    return False
                relogged = True
                if not self._login():
                    return False
                continue
            if outcome == "revoked" and not relogged:
                relogged = True
                if not self._login():
                    return False
                continue
            return False

    @task
    def work(self):
        if _past_window():
            raise StopUser()
        if not self.authed and not self._login():
            time.sleep(0.5)
            return
        time.sleep(_reserve_delay())
        if _past_window():
            raise StopUser()
        if _STATE["t0"] is None:
            _STATE["t0"] = time.monotonic()
        self._run_work()


class ScheduleShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._started = None

    def tick(self):
        now = time.monotonic()
        if self._started is None:
            self._started = now
        t0 = _STATE["t0"]
        if t0 is None:
            if now - self._started > ANCHOR_DEADLINE:
                return None
            return (USERS, USERS)
        if now >= t0 + DRAIN_END:
            return None
        return (USERS, USERS)
