import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;

public class ModelSimulation extends Simulation {

  private static final String BASE_URL = envOr("BASE_URL", "http://127.0.0.1:8000");
  private static final String PASSWORD = "bench";
  private static final AtomicInteger SEQ = new AtomicInteger();

  public ModelSimulation() {
    HttpProtocolBuilder protocol = http
        .baseUrl(BASE_URL)
        .disableFollowRedirect()
        .acceptHeader("application/json");

    ChainBuilder journey = exec(s -> s.set("username", nextUser()))
        .exec(login())
        .exec(operation());

    setUp(
        scenario("ModelSimulation")
            .exec(journey)
            .injectOpen(constantUsersPerSec(5).during(Duration.ofSeconds(45))))
        .protocols(protocol)
        .maxDuration(Duration.ofSeconds(60))
        .assertions(global().failedRequests().percent().lt(1.0));
  }

  // ---------- helpers ----------

  private static String envOr(String key, String dflt) {
    String v = System.getenv(key);
    return (v == null || v.isEmpty()) ? dflt : v;
  }

  private static String nextUser() {
    int i = Math.floorMod(SEQ.getAndIncrement(), 17);
    return i < 16 ? "bench-" + (i + 1) : "bench";
  }

  private static boolean st(Session s, int code) {
    return s.contains("st") && s.getInt("st") == code;
  }

  private static boolean errIs(Session s, String value) {
    return s.contains("err") && value.equals(s.getString("err"));
  }

  private static boolean bodyHas(Session s, String needle) {
    return s.contains("body") && s.getString("body").contains(needle);
  }

  // ---------- login (never counted as an operation) ----------

  private static ChainBuilder login() {
    return exec(http("login form")
            .get("/v2/login-form")
            .check(css("input[name=csrf]", "value").saveAs("csrf")))
        .exec(http("login")
            .post("/v2/login")
            .header("Content-Type", "application/json")
            .body(StringBody("{\"username\":\"#{username}\",\"password\":\"" + PASSWORD
                + "\",\"csrf\":\"#{csrf}\"}"))
            .check(status().in(200, 302))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(header("Location").optional().saveAs("loc")))
        .doIf(s -> s.contains("loc")).then(
            exec(http("login redirect")
                    .get("#{loc}")
                    .check(status().in(200, 302))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(s -> s.remove("loc")));
  }

  // ---------- session renewal (never counted as an operation) ----------

  private static ChainBuilder renew() {
    return exec(http("session renew")
        .post("/v2/session/renew")
        .header("X-CSRF-Token", "#{csrf}")
        .header("Content-Type", "application/json")
        .body(StringBody("{}"))
        .check(status().is(200))
        .check(jsonPath("$.csrf").saveAs("csrf")));
  }

  // ---------- the counted operation: POST /v2/work ----------

  private static ChainBuilder workReq(String name) {
    return exec(s -> s.remove("err").remove("body"))
        .exec(http(name)
            .post("/v2/work")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Content-Type", "application/json")
            .body(StringBody("{}"))
            .check(status().saveAs("st"))
            .check(status().in(200, 401, 429))
            .check(jsonPath("$.error").optional().saveAs("err"))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(bodyString().saveAs("body")))
        // success requires {ok:true}
        .doIf(s -> st(s, 200) && !bodyHas(s, "\"ok\":true")).then(
            exec(s -> s.markAsFailed()))
        // 401 that is neither expiry nor revocation (e.g. denied) fails its assertion
        .doIf(s -> st(s, 401) && !errIs(s, "expired") && !errIs(s, "session")).then(
            exec(s -> s.markAsFailed()));
  }

  // Scheduled 429: wait 1s (Retry-After) and retry, at most 4 retries.
  private static ChainBuilder workWithRetries(String name, int retriesLeft) {
    ChainBuilder first = workReq(name);
    if (retriesLeft <= 0) {
      return first;
    }
    return first.doIf(s -> st(s, 429)).then(
        exec(s -> s)
            .pause(Duration.ofSeconds(1))
            .exec(workWithRetries(name + " retry", retriesLeft - 1)));
  }

  private static ChainBuilder operation() {
    return workWithRetries("work", 4)
        // expired: renew once, retry the interrupted operation once
        .doIf(s -> st(s, 401) && errIs(s, "expired") && !s.contains("recovered")).then(
            exec(s -> s.set("recovered", 1))
                .exec(renew())
                .exec(workWithRetries("work after renew", 4)))
        // revoked: fresh form/login, retry the interrupted operation once
        .doIf(s -> st(s, 401) && errIs(s, "session") && !s.contains("recovered")).then(
            exec(s -> s.set("recovered", 1))
                .exec(login())
                .exec(workWithRetries("work after relogin", 4)));
  }
}
