import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
if (!/^http:\/\/127\.0\.0\.1(:\d+)?$/.test(BASE)) {
  throw new Error('BASE_URL must target http://127.0.0.1 only');
}

const PASSWORD = 'bench';
const USERS = ['bench'];
for (let i = 1; i <= 16; i++) USERS.push(`bench-${i}`);

const businessFailure = new Rate('business_failure');

export const options = {
  discardResponseBodies: false,
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '36s',
      preAllocatedVUs: 8,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
    checks: ['rate>0.99'],
  },
};

function parseJson(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

function header(res, name) {
  const want = name.toLowerCase();
  const h = res.headers || {};
  for (const k of Object.keys(h)) {
    if (k.toLowerCase() === want) return h[k];
  }
  return undefined;
}

function absUrl(loc) {
  if (/^https?:\/\//i.test(loc)) {
    if (loc !== BASE && !loc.startsWith(BASE + '/')) {
      throw new Error('off-target redirect location: ' + loc);
    }
    return loc;
  }
  return BASE + (loc.startsWith('/') ? loc : '/' + loc);
}

function decodeEntities(s) {
  const map = { amp: '&', quot: '"', '#39': "'", '#x27': "'", lt: '<', gt: '>' };
  return s.replace(/&(amp|quot|#39|#x27|lt|gt);/g, (m, e) => map[e]);
}

function parseAttrs(s) {
  const out = {};
  const re = /([^\s"'<>\/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let m;
  while ((m = re.exec(s)) !== null) {
    const key = m[1].toLowerCase();
    if (out[key] !== undefined) continue;
    const raw = m[2] !== undefined ? m[2]
      : m[3] !== undefined ? m[3]
      : m[4] !== undefined ? m[4]
      : '';
    out[key] = decodeEntities(raw);
  }
  return out;
}

function extractCsrf(html) {
  const clean = html
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<(script|style|template)\b[\s\S]*?<\/\1>/gi, '');
  const tagRe = /<input\b([^>]*)>/gi;
  let m;
  while ((m = tagRe.exec(clean)) !== null) {
    const attrs = parseAttrs(m[1]);
    if (attrs.name === 'csrf' && attrs.value) return attrs.value;
  }
  return null;
}

function jsonHeaders(st) {
  const h = { 'Content-Type': 'application/json', Accept: 'application/json' };
  if (st && st.csrf) h['X-CSRF-Token'] = st.csrf;
  return h;
}

// Fresh login: GET form -> POST login -> optional single GET of Location.
function login(username) {
  const form = http.get(BASE + '/v2/login-form', { redirects: 0, tags: { name: 'login-form' } });
  if (form.status !== 200) return null;
  const formCsrf = extractCsrf(form.body || '');
  if (!formCsrf) return null;

  const res = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: username, password: PASSWORD, csrf: formCsrf }),
    { headers: jsonHeaders(null), redirects: 0, tags: { name: 'login' } }
  );

  const body = parseJson(res.body);
  let csrf = body && typeof body.csrf === 'string' && body.csrf ? body.csrf : null;

  if (res.status === 302) {
    const loc = header(res, 'location');
    if (!loc) return null;
    const follow = http.get(absUrl(loc), { redirects: 0, tags: { name: 'login-redirect' } });
    if (follow.status >= 400) return null;
    const fj = parseJson(follow.body);
    if (fj && typeof fj.csrf === 'string' && fj.csrf) csrf = fj.csrf;
  } else if (res.status !== 200) {
    return null;
  }

  return csrf ? { csrf: csrf } : null;
}

function renew(st) {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: jsonHeaders(st),
    redirects: 0,
    tags: { name: 'renew' },
  });
  const body = parseJson(res.body);
  if (res.status >= 400 || !body || typeof body.csrf !== 'string' || !body.csrf) return false;
  st.csrf = body.csrf;
  return true;
}

function postWork(st) {
  return http.post(BASE + '/v2/work', '{}', {
    headers: jsonHeaders(st),
    redirects: 0,
    tags: { name: 'work' },
  });
}

// One logical operation with bounded recovery:
// up to 4 scheduled-429 retries, one renew on expiry, one re-login on revoked session.
function doWork(st, username) {
  let throttled = 0;
  let renewed = false;
  let reauthed = false;

  for (let attempt = 0; attempt < 16; attempt++) {
    const res = postWork(st);
    const body = parseJson(res.body);
    const code = body && typeof body.error === 'string' ? body.error : '';

    if (res.status === 200) {
      const ok = !!body && body.ok === true;
      businessFailure.add(!ok);
      if (ok && typeof body.csrf === 'string' && body.csrf) st.csrf = body.csrf;
      check(res, {
        'work status 200': (r) => r.status === 200,
        'work ok true': () => ok,
      });
      return ok;
    }

    if (res.status === 429) {
      const ra = header(res, 'retry-after');
      const wait = ra !== undefined ? Number(ra) : NaN;
      businessFailure.add(false); // scheduled429 is excluded from the numerator
      if (throttled < 4 && Number.isFinite(wait) && wait > 0 && wait <= 10) {
        throttled++;
        sleep(wait);
        continue;
      }
      check(res, { 'work not throttled beyond budget': () => false });
      return false;
    }

    if (res.status === 401) {
      if (code === 'expired' && !renewed) {
        businessFailure.add(false); // expected expiry is excluded from the numerator
        renewed = true;
        if (renew(st)) continue;
        check(res, { 'renew after expiry succeeded': () => false });
        return false;
      }
      if (code === 'session' && !reauthed) {
        businessFailure.add(true); // revoked session is not an excluded expected outcome
        reauthed = true;
        const fresh = login(username);
        if (fresh) {
          st.csrf = fresh.csrf;
          continue;
        }
        check(res, { 'fresh login after revoked session': () => false });
        return false;
      }
      // error=denied, repeated expiry, or unknown 401: assertion fails
      businessFailure.add(true);
      check(res, { 'work authorized': () => false });
      return false;
    }

    // 500, other 4xx/5xx, or unexpected status
    businessFailure.add(true);
    check(res, { 'work status 200': () => false });
    return false;
  }
  return false;
}

export default function () {
  const idx = exec.scenario.iterationInTest;
  const username = USERS[idx % USERS.length];

  const st = login(username);
  const loggedIn = check(st, { 'login produced csrf': (s) => !!(s && s.csrf) });
  if (!loggedIn) return;

  doWork(st, username);
}
