import itertools
import os
import time
from html.parser import HTMLParser
from urllib.parse import urlsplit

from locust import HttpUser, LoadTestShape, StopUser, constant, task

BASE_URL = os.environ["BASE_URL"]
PASSWORD = "bench"

TARGET_RATE = 5.0            # POST /v2/work starts per second
USERS = 16                   # fixed virtual user count (limit is 32)
WARMUP_S = 5.0
SCORED_WINDOW_S = 30.0       # six 5 s windows
SCORE_END_S = WARMUP_S + SCORED_WINDOW_S   # starts stop at T0+35
DRAIN_S = 5.0
ANCHOR_DEADLINE_S = 30.0     # hard stop if no anchor is ever established
MAX_429_RETRIES = 4
RETRY_AFTER_DEFAULT_S = 1.0


class Pacer(object):
    """Shared fixed-grid start scheduler. Slot k is due at T0 + k / TARGET_RATE.
    T0 is anchored by the first claimed slot (the first work POST)."""

    t0 = None
    next_slot = 0
    total_slots = int(round(SCORE_END_S * TARGET_RATE))  # 175 starts in [T0, T0+35)
    alive = 0

    @classmethod
    def claim(cls):
        if cls.next_slot >= cls.total_slots:
            return None
        if cls.t0 is None:
            cls.t0 = time.monotonic()
        due = cls.t0 + cls.next_slot / TARGET_RATE
        cls.next_slot += 1
        return due

    @classmethod
    def exhausted(cls):
        return cls.next_slot >= cls.total_slots


class _CsrfFormParser(HTMLParser):
    """Collects input[name=csrf] candidates, preferring the /v2/login form,
    hidden inputs, and the earliest occurrence. Ignores disabled and empty inputs.
    Comments and script/style text are never parsed as tags."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._forms = []
        self.candidates = []  # (score, -index, value)

    def handle_starttag(self, tag, attrs):
        attr = {}
        for key, value in attrs:
            if key is None:
                continue
            key = key.lower()
            if key not in attr:
                attr[key] = value if value is not None else ""
        if tag == "form":
            self._forms.append(attr.get("action", "").strip())
            return
        if tag == "input" and attr.get("name", "").strip() == "csrf" and "disabled" not in attr:
            value = attr.get("value", "").strip()
            if not value:
                return
            action = self._forms[-1] if self._forms else ""
            score = 0
            if action.endswith("/v2/login"):
                score += 2
            if attr.get("type", "hidden").strip().lower() == "hidden":
                score += 1
            self.candidates.append((score, -len(self.candidates), value))

    def handle_endtag(self, tag):
        if tag == "form" and self._forms:
            self._forms.pop()


def extract_csrf(text):
    parser = _CsrfFormParser()
    try:
        parser.feed(text or "")
        parser.close()
    except Exception:
        return None
    if not parser.candidates:
        return None
    return max(parser.candidates)[2]


def _json(response):
    try:
        return response.json()
    except Exception:
        return None


def _token(data):
    if isinstance(data, dict):
        value = data.get("csrf")
        if isinstance(value, str) and value:
            return value
    return None


def _retry_after(value):
    if value is None:
        return None
    try:
        seconds = float(value.strip())
    except (ValueError, AttributeError):
        return None
    if seconds != seconds or seconds < 0:  # NaN or negative
        return None
    return seconds


class ShopBase(HttpUser):
    abstract = True
    host = BASE_URL
    wait_time = constant(0)
    _account_seq = itertools.count()

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.account = next(ShopBase._account_seq) % USERS + 1
        self.username = "bench-%d" % self.account
        self.password = PASSWORD
        self.csrf = None
        self.logged_in = False
        Pacer.alive += 1

    # ---- helpers -------------------------------------------------------

    def _auth_headers(self):
        return {"X-CSRF-Token": self.csrf} if self.csrf else {}

    def _fetch_form_csrf(self):
        with self.client.get(
            "/v2/login-form",
            name="setup GET /v2/login-form",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return None
            token = extract_csrf(r.text)
            if token is None:
                r.failure("login-form csrf input missing")
                return None
            r.success()
            return token

    def _follow_login_redirect(self, location):
        base = urlsplit(BASE_URL)
        target = urlsplit(location)
        if target.scheme or target.netloc:
            if (target.scheme, target.netloc) != (base.scheme, base.netloc):
                return None
        path = target.path or "/"
        if target.query:
            path = path + "?" + target.query
        with self.client.get(
            path,
            name="setup GET login redirect",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code != 200:
                r.failure("login redirect status %s" % r.status_code)
                return None
            token = _token(_json(r))
            if token is None:
                token = extract_csrf(r.text)
            if token is None:
                r.failure("login redirect target without csrf")
                return None
            r.success()
            return token

    def _login(self):
        self.logged_in = False
        self.csrf = None
        form_token = self._fetch_form_csrf()
        if form_token is None:
            return False

        redirect = None
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": form_token},
            name="setup POST /v2/login",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code == 302:
                redirect = r.headers.get("Location")
                if not redirect:
                    r.failure("login 302 without Location")
                    return False
                r.success()
            elif r.status_code == 200:
