import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = envOr("BASE_URL", "http://127.0.0.1:8000");
    private static final String PASSWORD = "bench";
    private static final String[] ACCOUNTS = {
        "bench-1", "bench-2", "bench-3", "bench-4", "bench-5", "bench-6", "bench-7", "bench-8",
        "bench-9", "bench-10", "bench-11", "bench-12", "bench-13", "bench-14", "bench-15", "bench-16",
        "bench"
    };

    private static final double TARGET_RPS = 8;
    private static final int INJECT_SECONDS = 40;

    private static final Pattern COMMENT = Pattern.compile("<!--.*?-->", Pattern.DOTALL);
    private static final Pattern INPUT_TAG = Pattern.compile("<input\\b[^>]*>", Pattern.CASE_INSENSITIVE);
    private static final Pattern DISABLED =
        Pattern.compile("(?<![\\w-])disabled(?![\\w-])", Pattern.CASE_INSENSITIVE);
    private static final Pattern VALUE_ATTR =
        Pattern.compile("(?<![\\w-])value\\s*=\\s*[\"']([^\"']+)[\"']", Pattern.CASE_INSENSITIVE);

    public ModelSimulation() {
        HttpProtocolBuilder protocol = http
            .baseUrl(BASE_URL)
            .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8")
            .disableFollowRedirect();

        ChainBuilder journey = exec(s -> s
                .set("user", ACCOUNTS[(int) (s.userId() % ACCOUNTS.length)])
                .set("csrf", "")
                .set("formCsrf", "")
                .set("formHtml", "")
                .set("loc", "")
                .set("lst", 0)
                .set("err", "")
                .set("st", 0))
            .exec(loginChain())
            .exec(attemptChain())
            .doIf(s -> s.getInt("st") == 401 && "expired".equals(s.getString("err")))
            .then(renewChain().exec(attemptChain()))
            .doIf(s -> s.getInt("st") == 401 && "session".equals(s.getString("err")))
            .then(loginChain().exec(attemptChain()));

        ScenarioBuilder scn = scenario("pool-work").exec(journey);

        // Open-model injection at the target rate: one journey (login + one POST /v2/work) per arrival.
        // constantUsersPerSec spaces starts evenly across users, which keeps one-second bursts near the target.
        setUp(scn.injectOpen(constantUsersPerSec(TARGET_RPS).during(Duration.ofSeconds(INJECT_SECONDS))))
            .protocols(protocol);
    }

    // ---------- login ----------

    static ChainBuilder loginChain() {
        return exec(s -> s.set("formCsrf", "").set("formHtml", "").set("loc", "").set("lst", 0).set("lbody", ""))
            .exec(http("login-form")
                .get("/v2/login-form")
                .check(bodyString().saveAs("formHtml"))
                .check(status().is(200)))
            .exec(s -> s.set("formCsrf",
                s.contains("formHtml") ? inputValue(s.getString("formHtml"), "csrf") : ""))
            .exec(http("login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody("{\"username\":\"#{user}\",\"password\":\"" + PASSWORD
                    + "\",\"csrf\":\"#{formCsrf}\"}"))
                .check(bodyString().saveAs("lbody"))
                .check(status().saveAs("lst"))
                .check(status().in(200, 302))
                .check(header("Location").optional().saveAs("loc")))
            .exec(s -> adoptCsrf(s, respBody(s, "lbody")))
            .doIf(s -> s.getInt("lst") == 302 && !s.getString("loc").isEmpty())
            .then(exec(http("login-redirect")
                    .get("#{loc}")
                    .check(bodyString().saveAs("rbody"))
                    .check(status().in(200, 302)))
                .exec(s -> adoptCsrf(s, respBody(s, "rbody"))));
    }

    // ---------- session renewal (not an operation) ----------

    static ChainBuilder renewChain() {
        return exec(http("session-renew")
                .post("/v2/session/renew")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Content-Type", "application/json")
                .body(StringBody("{}"))
                .check(bodyString().saveAs("rnbody"))
                .check(status().in(200, 401)))
            .exec(s -> adoptCsrf(s, respBody(s, "rnbody")));
    }

    // ---------- pool operation: POST /v2/work ----------

    static HttpRequestActionBuilder workRequest() {
        return http("POST /v2/work")
            .post("/v2/work")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Content-Type", "application/json")
            .body(StringBody("{}"))
            .check(bodyString().saveAs("wbody"))
            .check(status().saveAs("st"))
            .check(status().in(200, 401, 429))
            .check(regex("\"error\"\\s*:\\s*\"denied\"").count().is(0));
    }

    // One work request; scheduled 429 retries wait 1s, at most 4 retries.
    static ChainBuilder workRetry(int retriesLeft) {
        ChainBuilder once = exec(s -> s.set("wbody", ""))
            .exec(workRequest())
            .exec(s -> s.set("err", jsonField(respBody(s, "wbody"), "error")))
            .exec(s -> adoptCsrf(s, respBody(s, "wbody")));

        if (retriesLeft <= 0) {
            return once;
        }
        return once
            .doIf(s -> s.getInt("st") == 429)
            .then(exec(s -> s).pause(Duration.ofSeconds(1)).exec(workRetry(retriesLeft - 1)));
    }

    static ChainBuilder attemptChain() {
        return exec(s -> s.set("err", "").set("st", 0))
            .exec(workRetry(4));
    }

    // ---------- helpers ----------

    static String respBody(Session s, String key) {
        return s.contains(key) ? s.getString(key) : "";
    }

    static Session adoptCsrf(Session s, String body) {
        String token = jsonField(body, "csrf");
        return token.isEmpty() ? s : s.set("csrf", token);
    }

    static String jsonField(String body, String key) {
        Matcher m = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]*)\"").matcher(body);
        return m.find() ? m.group(1) : "";
    }

    // Finds the non-disabled <input> whose name is exactly `field`, regardless of attribute order.
    static String inputValue(String html, String field) {
        String clean = COMMENT.matcher(html).replaceAll("");
        Pattern nameField = Pattern.compile(
            "(?<![\\w-])name\\s*=\\s*[\"']?" + Pattern.quote(field) + "[\"'\\s/>]",
            Pattern.CASE_INSENSITIVE);
        Matcher tags = INPUT_TAG.matcher(clean);
        while (tags.find()) {
            String tag = tags.group();
            if (!nameField.matcher(tag).find() || DISABLED.matcher(tag).find()) {
                continue;
            }
            Matcher value = VALUE_ATTR.matcher(tag);
            if (value.find()) {
                return value.group(1);
            }
        }
        return "";
    }

    static String envOr(String key, String fallback) {
        String v = System.getenv(key);
        return (v == null || v.isEmpty()) ? fallback : v;
    }
}
