import http from 'k6/http';
import exec from 'k6/execution';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { parseHTML } from 'k6/html';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';
const WORK_PATH = '/v2/work';
const TARGET_RATE = 8;
const MAX_VUS = 16;
const PRE_ALLOCATED_VUS = 8;
const MAX_429_RETRIES = 4;
const RETRY_AFTER_VALUE = '1';

// One account per VU (16 numbered + 'bench' = 17 accounts, maxVUs = 16).
const ACCOUNTS = [];
for (let i = 1; i <= 16; i++) {
  ACCOUNTS.push('bench-' + i);
}
ACCOUNTS.push('bench');

// Expected statuses are not transport failures; the business rules below decide correctness.
http.setResponseCallback(http.expectedStatuses({ min: 200, max: 399 }, 401, 429));

const businessFailure = new Rate('business_failure');
const workSucceeded = new Counter('work_succeeded');
const workLost = new Counter('work_lost');
const scheduled429 = new Counter('work_scheduled_429');
const authRecoveries = new Counter('auth_recoveries');
const loginFailed = new Counter('login_failed');
const workDuration = new Trend('work_req_duration', true);

export const options = {
  scenarios: {
    work_pacing: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      // Covers launch->T0 (<=10s) + warmup 5s + scored 30s + drain margin.
      duration: '50s',
      preAllocatedVUs: PRE_ALLOCATED_VUS,
      maxVUs: MAX_VUS,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<=0.01'],
    work_lost: ['count<=4'],
    dropped_iterations: ['count<=4'],
  },
};

// Per-VU session state (each VU has its own JS runtime and cookie jar).
let session = null;

function accountName() {
  const idx = (exec.vu.idInTest - 1) % ACCOUNTS.length;
  return ACCOUNTS[idx];
}

function parseJson(body) {
  if (!body) {
    return null;
  }
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function headerValue(res, name) {
  const h = res.headers || {};
  if (h[name] !== undefined) {
    return h[name];
  }
  return h[name.toLowerCase()];
}

function resolveLocation(loc) {
  if (!loc) {
    return null;
  }
  if (loc.indexOf('http://') === 0 || loc.indexOf('https://') === 0) {
    // Only the declared target origin is permitted.
    return loc.indexOf(BASE_URL) === 0 ? loc : null;
  }
  return BASE_URL + (loc.charAt(0) === '/' ? loc : '/' + loc);
}

function formCsrf(body) {
  if (!body) {
    return null;
  }
  const doc = parseHTML(body);
  const selectors = [
    'form[action="/v2/login"] input[name="csrf"]',
    'input[name="csrf"][type="hidden"]',
    'input[name="csrf"]',
  ];
  for (const sel of selectors) {
    let v = null;
    try {
      v = doc.find(sel).first().attr('value');
    } catch (e) {
      v = null;
    }
    if (v) {
      return v;
    }
  }
  return null;
}

function authHeaders() {
  return {
    'Content-Type': 'application/json',
    'X-CSRF-Token': session ? session.csrf : '',
  };
}

function login() {
  const form = http.get(BASE_URL + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'login_form' },
  });
  if (form.status !== 200) {
    loginFailed.add(1);
    return false;
  }
  const loginFormCsrf = formCsrf(form.body);
  if (!loginFormCsrf) {
    loginFailed.add(1);
    return false;
  }

  const res = http.post(
    BASE_URL + '/v2/login',
    JSON.stringify({
      username: accountName(),
      password: PASSWORD,
      csrf: loginFormCsrf,
    }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'login' },
    }
  );
  const accepted = check(res, {
    'login accepted': (r) => r.status === 200 || r.status === 302,
  });
  if (!accepted) {
    loginFailed.add(1);
    return false;
  }

  let csrf = null;
  const body = parseJson(res.body);
  if (body && body.csrf) {
    csrf = body.csrf;
  }

  if (res.status === 302) {
    // Redirects are disabled; the dynamic Location is fetched exactly once.
    const target = resolveLocation(headerValue(res, 'Location'));
    if (target) {
      const follow = http.get(target, {
        redirects: 0,
        tags: { name: 'login_redirect' },
      });
      const fj = parseJson(follow.body);
      if (fj && fj.csrf) {
        csrf = fj.csrf;
      }
    }
  }

  if (!csrf) {
    loginFailed.add(1);
    return false;
  }
  session = { csrf: csrf };
  return true;
}

function ensureSession() {
  if (session) {
    return true;
  }
  for (let attempt = 0; attempt < 2; attempt++) {
    if (login()) {
      return true;
    }
    sleep(0.1);
  }
  return false;
}

function renewSession() {
  if (!session) {
    return false;
  }
  const res = http.post(BASE_URL + '/v2/session/renew', '{}', {
    headers: authHeaders(),
    redirects: 0,
    tags: { name: 'session_renew' },
  });
  const j = res.status === 200 ? parseJson(res.body) : null;
  if (!j || !j.csrf) {
    return false;
  }
  session.csrf = j.csrf;
  return true;
}

// Performs one logical POST /v2/work operation with bounded recovery:
// - at most 4 retries for scheduled 429 (Retry-After: 1)
// - at most 1 auth recovery (renew on expired, fresh login on session), then one retry
// - denied and any other failure are unexpected
function doWork() {
  let recovered = false;
  let retries = 0;

  for (;;) {
    const started = Date.now();
    const res = http.post(BASE_URL + WORK_PATH, '{}', {
      headers: authHeaders(),
      redirects: 0,
      tags: { name: 'work' },
    });
    workDuration.add(Date.now() - started);

    const j = parseJson(res.body);
    const okBody = j !== null && j.ok === true;

    check(res, {
      'work status 200 with ok': (r) => r.status === 200 && okBody,
    });

    if (res.status === 200 && okBody) {
      businessFailure.add(false);
      if (j.csrf && session) {
        session.csrf = j.csrf;
      }
      workSucceeded.add(1);
      return true;
    }

    if (res.status === 429 && String(headerValue(res, 'Retry-After')).trim() === RETRY_AFTER_VALUE) {
      if (retries < MAX_429_RETRIES) {
        retries++;
        businessFailure.add(false);
        scheduled429.add(1);
        sleep(1);
        continue;
      }
      // Retry budget exhausted: the work was not delivered.
      businessFailure.add(true);
      workLost.add(1);
      return false;
    }

    if (res.status === 401 && j && !recovered && (j.error === 'expired' || j.error === 'session')) {
      recovered = true;
      businessFailure.add(false);
      authRecoveries.add(1);

      let ok = false;
      if (j.error === 'expired') {
        ok = renewSession();
      }
      if (!ok) {
        // Revoked session (or failed renewal): fresh form/login.
        session = null;
        ok = ensureSession();
      }
      if (ok) {
        continue; // retry only the interrupted operation, once
      }
      workLost.add(1);
      return false;
    }

    // Unexpected: 500, 200 with ok:false, denied, repeated expiry, other statuses.
    businessFailure.add(true);
    workLost.add(1);
    return false;
  }
}

export default function () {
  if (!ensureSession()) {
    workLost.add(1);
    return;
  }
  doWork();
}
