```python
import itertools
import math
import os
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

from gevent import sleep as _gsleep
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
BASE_NETLOC = urlparse(BASE_URL).netloc

PASSWORD = "bench"
ACCOUNTS = ["bench-%d" % i for i in range(1, 17)]

WORK_PATH = "/v2/work"
RENEW_PATH = "/v2/session/renew"
LOGIN_FORM_PATH = "/v2/login-form"
LOGIN_PATH = "/v2/login"

TARGET_RATE = 8.0                      # POST /v2/work starts per second
WARMUP_S = 5.0
SCORE_WINDOW_S = 30.0
SCORE_END_S = WARMUP_S + SCORE_WINDOW_S  # scored interval is [T0+5, T0+35)
DRAIN_ALLOWANCE_S = 2.0
VIRTUAL_USERS = 16
MAX_THROTTLE_RETRIES = 4
MAX_RECOVERIES = 2
LOGIN_ATTEMPTS = 3
REDIRECT_CODES = (301, 302, 303, 307, 308)

OK = "ok"
EXPIRED = "expired"
REVOKED = "revoked"
THROTTLED = "throttled"
DENIED = "denied"
FAILED = "failed"


class _SharedPacer(object):
    """Process-wide slot allocator shared by all virtual users.

    Slot k is due at T0 + k / TARGET_RATE. T0 is anchored by the first
    authenticated work attempt. Slots are allocated lazily: a late user never
    claims a backlog of past slots, so there is no catch-up flood.
    """

    def __init__(self):
        self.t0 = None
        self.next_index = 0

    def window_over(self):
        if self.t0 is None:
            return False
        return time.monotonic() - self.t0 >= SCORE_END_S

    def acquire(self):
        now = time.monotonic()
        if self.t0 is None:
            self.t0 = now
        lag_index = int(math.ceil((now - self.t0) * TARGET_RATE - 1e-6))
        index = max(self.next_index, lag_index, 0)
        if index / TARGET_RATE >= SCORE_END_S:
            return None
        self.next_index = index + 1
        delay = (self.t0 + index / TARGET_RATE) - time.monotonic()
        if delay > 0:
            _gsleep(delay)
        return index


PACER = _SharedPacer()


class _CsrfInputScanner(HTMLParser):
    """Collects <input name="csrf"> candidates, ignoring comments and scripts."""

    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self._in_form = False
        self._form_action = ""
        self.found = []

    def handle_starttag(self, tag, attrs):
        attr = {}
        for key, value in attrs:
            if key is None:
                continue
            attr.setdefault(key.lower(), value if value is not None else "")
        if tag == "form":
            self._in_form = True
            self._form_action = attr.get("action", "")
        elif tag == "input":
            if attr.get("name", "").strip() != "csrf":
                return
            if "disabled" in attr:
                return
            value = attr.get("value", "").strip()
            if not value:
                return
            score = 0
            if self._in_form and "/v2/login" in self._form_action:
                score += 2
            if attr.get("type", "").strip().lower() == "hidden":
                score += 1
            self.found.append((score, value))

    def handle_endtag(self, tag):
        if tag == "form":
            self._in_form = False
            self._form_action = ""


def _extract_csrf(html):
    scanner = _CsrfInputScanner()
    try:
        scanner.feed(html or "")
        scanner.close()
    except Exception:
        return None
    if not scanner.found:
        return None
    best = max(scanner.found, key=lambda item: item[0])
    return best[1]


def _json_body(resp):
    try:
        return resp.json()
    except ValueError:
        return None


def _is_token(value):
    return isinstance(value, str) and len(value) > 0


def _retry_after_seconds(resp):
    raw = resp.headers.get("Retry-After")
    try:
        value = float(raw)
    except (TypeError, ValueError):
        value = 1.0
    return min(max(value, 1.0), 5.0)


def _same_host_url(location):
    if not location:
        return None
    url = urljoin(BASE_URL + "/", location)
    if urlparse(url).netloc != BASE_NETLOC:
        return None
    return url


_account_seq = itertools.count()


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        if PACER.window_over():
            raise StopUser()
        self.username = ACCOUNTS[next(_account_seq) % len(ACCOUNTS)]
        self.csrf = None
        self._retry_after = 1.0
        if not self._login():
            raise StopUser()

    @task
    def work(self):
        index = PACER.acquire()
        if index is None:
            raise StopUser()
        self._run_operation()

    # ----- operation with bounded recovery -------------------------------

    def _run_operation(self):
        recoveries = 0
        throttles = 0
        while True:
            outcome = self._post_work()
            if outcome == OK:
                return
            if outcome == EXPIRED and recoveries < MAX_RECOVERIES:
                recoveries += 1
                if self._renew():
                    continue
                if self._login():
                    continue
                return
            if outcome == REVOKED and recoveries < MAX_RECOVERIES:
                recoveries += 1
                if self._login():
                    continue
                return
            if outcome == THROTTLED and throttles < MAX_THROTTLE_RETRIES:
                throttles += 1
                _gsleep(self._retry_after)
                if PACER.acquire() is None:
                    raise StopUser()
                continue
            # DENIED / FAILED: failure already recorded on the sample
            return

    def _headers(self):
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        return headers

    def _adopt_csrf(self, body):
        if isinstance(body, dict) and _is_token(body.get("csrf")):
            self.csrf = body["csrf"]

    def _post_work(self):
        with self.client.post(
            WORK_PATH,
            json={},
            headers=self._headers(),
            allow_redirects=False,
            name=WORK_PATH,
            catch_response=True,
        ) as resp:
            status = resp.status_code
            body = _json_body(resp)
            err = body.get("error") if isinstance(body, dict) else None

            if status == 200 and isinstance(body, dict) and body.get("ok") is True:
                self._adopt_csrf(body)
                resp.success()
                return OK
            if status == 401 and err == "expired":
                resp.success()  # expected expiry, not a failure
                return EXPIRED
            if status == 401 and err == "session":
                resp.success()  # expected revocation, recovered by re-login
                return REVOKED
            if status == 429:
                self._retry_after = _retry_after_seconds(resp)
                resp.success()  # scheduled throttle, not a failure
                return THROTTLED
            if status == 401:
                resp.failure("denied 401 error=%s" % err)
                return DENIED
            if status == 200:
                resp.failure("assertion failed: work response ok is not true")
                return FAILED
            resp.failure("unexpected work status %s" % status)
            return FAILED

    # ----- session handling ----------------------------------------------

    def _renew(self):
        with self.client.post(
            RENEW_PATH,
            json={},
            headers=self._headers(),
            allow_redirects=False,
            name=RENEW_PATH,
            catch_response=True,
        ) as resp:
            status = resp.status_code
            body = _json_body(resp)
            if status == 200:
                self._adopt_csrf(body)
                resp.success()
                return True
            if status == 401:
                resp.success()  # renewal may fail after revocation
                return False
            resp.failure("renew unexpected status %s" % status)
            return False

    def _login(self):
        for _ in range(LOGIN_ATTEMPTS):
            token = self._fetch_login_csrf()
            if token and self._submit_login(token):
                return True
            _gsleep(0.2)
        return False

    def _fetch_login_csrf(self):
        with self.client.get(
            LOGIN_FORM_PATH,
            allow_redirects=False,
            name=LOGIN_FORM_PATH,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure("login-form status %s" % resp.status_code)
                return None
            token = _extract_csrf(resp.text)
            if not token:
                resp.failure("login-form csrf input not found")
                return None
            resp.success()
            return token

    def _submit_login(self, token):
        payload = {"username": self.username, "password": PASSWORD, "csrf": token}
        location = None
        with self.client.post(
            LOGIN_PATH,
            json=payload,
            allow_redirects=False,
            name=LOGIN_PATH,
            catch_response=True,
        ) as resp:
            status = resp.status_code
            if status in REDIRECT_CODES:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login redirect without Location")
                    return False
                resp.success()
            elif status == 200:
                body = _json_body(resp)
                if isinstance(body, dict) and _is_token(body.get("csrf")):
                    self.csrf = body["csrf"]
                    resp.success()
                    return True
                resp.failure("login response missing csrf")
                return False
            else:
                resp.failure("login unexpected status %s" % status)
                return False

        # Follow the dynamic Location exactly once.
        url = _same_host_url(location)
        if url is None:
            return False
        with self.client.get(
            url,
            allow_redirects=False,
            name="/v2/login-redirect",
            catch_response=True,
        ) as resp2:
            body = _json_body(resp2)
            if 200 <= resp2.status_code < 300 and isinstance(body, dict) and _is_token(body.get("csrf")):
                self.csrf = body["csrf"]
                resp2.success()
                return True
            resp2.failure("login redirect target did not yield csrf")
            return False


class PacedWindowShape(LoadTestShape):
    """Keeps the virtual-user pool running until the scored window plus drain has elapsed."""

    user_count = VIRTUAL_USERS
    spawn_rate = VIRTUAL_USERS
    anchor_deadline_s = 60.0

    def tick(self):
        if PACER.t0 is None:
            if self.get_run_time() > self.anchor_deadline_s:
                return None
            return self.user_count, self.spawn_rate
        if time.monotonic() >= PACER.t0 + SCORE_END_S + DRAIN_ALLOWANCE_S:
            return None
        return self.user_count, self.spawn_rate
